                    found = False
                    if hasattr(self, 'iteritems'):
                        for k, v in self.iteritems():
                            if k == key:
                                filtered.append(v)
                                found = True
                                break
                    elif hasattr(self, '_items'):
                        for item in self._items:
                            if isinstance(item, (list, tuple)) and len(item) == 2 and item[0] == key:
