                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to extract a value from an item
    def _extract_value(item):
        if isinstance(item, (list, tuple)) and len(item) > 1:
            return item[1]
        return item

    # No keys provided: return all values
    if not keys:
        if isinstance(self._items, dict):
            return list(self._items.values())
        else:
            # Assume sequence of key/value pairs or single values
            return [_extract_value(item) for item in self._items]

    # Keys provided: build filtered list
    result = []
    for key in keys:
        try:
            if isinstance(key, int):
                # Treat as positional index
                item = self._items[key]
                value = _extract_value(item)
            else:
                # Treat as key lookup
                value = self._items[key]
        except (IndexError, KeyError, TypeError, AttributeError):
            # Skip missing entries silently
            continue
        result.append(value)
    return result

