    if not hasattr(self, "_data") or not hasattr(self, "_keys"):
        raise AttributeError("Record object missing _data or _keys attributes")

    data_list = self._data
    key_to_index = self._keys

    # Build reverse mapping from index to key name for use with integer indices
    index_to_key = {index: key for key, index in key_to_index.items()}

    # If no keys requested, return all key/value pairs
    if not keys:
        result = {}
        for key, idx in key_to_index.items():
            # Guard against potentially missing data entries
            value = data_list[idx] if idx < len(data_list) else None
            result[key] = value
        return result

    # Handle specified keys/indices
    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(data_list):
                raise IndexError(f"Index {idx} out of bounds for record of length {len(data_list)}")
            # Obtain corresponding field name; if not mapped, use string representation
            field_name = index_to_key.get(idx, str(idx))
            result[field_name] = data_list[idx]
        else:
            # Treat as a key name
            if k in key_to_index:
                idx = key_to_index[k]
                result[k] = data_list[idx] if idx < len(data_list) else None
            else:
                # Key not present in record
                result[k] = None
    return result

