    if isinstance(key_order, dict):
        # mapping from field name to index
        name_to_index = key_order
        index_to_name = {idx: name for name, idx in key_order.items()}
    else:
        # sequence of field names
        name_to_index = {name: idx for idx, name in enumerate(key_order)}
        index_to_name = {idx: name for idx, name in enumerate(key_order)}

    # Helper to fetch name by index (supports negative indexing)
    def name_from_index(idx):
        try:
            return index_to_name[idx]
        except KeyError:
            # When key_order is a list, index_to_name covers all indices
            # If not, fallback to indexing the list directly
            return key_order[idx]

    result = {}

    # If no keys requested, include everything
    if not keys:
        for idx, value in enumerate(data):
            result[name_from_index(idx)] = value
        return result

    for key in keys:
        if isinstance(key, int):
            # Validate bounds
            if key < -len(data) or key >= len(data):
                raise IndexError(f"Index {key} out of bounds for record of length {len(data)}")
            name = name_from_index(key)
            result[name] = data[key]
        else:
            # Treat as a field name
            if key in name_to_index:
                idx = name_to_index[key]
                result[key] = data[idx]
            else:
                # field not present in the record
                result[key] = None
    return result

