def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    # Determine the ordered list of field names for index-based access.
    if hasattr(self, "_keys"):
        field_names = list(self._keys)
    elif hasattr(self, "_fields"):
        field_names = list(self._fields)
    else:
        # Fallback: use the attributes of the instance.
        field_names = list(vars(self).keys())

    # Helper to fetch attribute value safely.
    def _get_value(name):
        return getattr(self, name, None)

    # If no specific keys requested, return all fields.
    if not keys:
        return {name: _get_value(name) for name in field_names}

    # Otherwise process requested keys/indexes.
    result = {}
    for key in keys:
        if isinstance(key, int):
            idx = key
            if idx < 0 or idx >= len(field_names):
                raise IndexError(f"index {idx} out of bounds")
            name = field_names[idx]
        else:
            name = key
        result[name] = _get_value(name)
    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer. """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit integer")
    # Grab last two bytes
    last_two = self.data[-2:]
    # Remove the bytes from the buffer
    if isinstance(self.data, (bytearray, list)):
        del self.data[-2:]
    else:
        # For immutable types (bytes, str), assign a new trimmed value
        self.data = self.data[:-2]
    # Convert to unsigned int, big-endian
    return int.from_bytes(last_two, byteorder='big')

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
        """
        Appends a DISCARD message to the output queue.

        :param n: number of records to discard, default = -1 (ALL)
        :param qid: query ID to discard for, default = -1 (last query)
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        """
        # Validate arguments
        if not isinstance(n, int):
            raise ValueError("n must be an integer")
        if not isinstance(qid, int):
            raise ValueError("qid must be an integer")

        # Build message payload
        msg = {"command": "DISCARD", "n": n, "qid": qid}

        # Apply dehydration hooks, if any, to the message values
        if dehydration_hooks:
            for key, value in list(msg.items()):
                hook = dehydration_hooks.get(type(value))
                if hook:
                    try:
                        msg[key] = hook(value)
                    except Exception as exc:
                        raise ValueError(f"Dehydration hook for type {type(value)} failed: {exc}")

        # Append the message to the output queue
        try:
            self.output_queue.put_nowait(msg)  # Use put_nowait or append depending on queue type
        except AttributeError:
            # Fallback if output_queue has a different interface
            try:
                self.output_queue.append(msg)
            except Exception as exc:
                raise RuntimeError(f"Failed to append DISCARD message: {exc}")

        # Construct and return a Response object (assuming a Response class exists)
        # The handlers are stored on the Response for later use.
        # hydration_hooks are passed along for use when the response is processed.
        try:
            response = Response(message=msg,
                                handlers=handlers,
                                hydration_hooks=hydration_hooks or {})
        except NameError:
            # If Response is not defined, fallback to a simple dict representation
            response = {
                "message": msg,
                "handlers": handlers,
                "hydration_hooks": hydration_hooks or {}
            }

        return response

