def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Splits the input string on dots and converts each fragment to an integer.
    Non‑numeric fragments cause a ValueError to be raised. Leading and trailing
    whitespace is ignored. This is suitable for simple sortedness checks of
    semantic style version numbers like '1.2.3'.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")

    s = s.strip()
    if not s:
        raise ValueError("Empty version string")

    parts = s.split(".")
    ints = []
    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError(f"Empty component in version string: {s!r}")

        try:
            ints.append(int(part))
        except ValueError as exc:
            # Allow trailing non-digits (e.g. "1.2a")
            digits = ""
            for ch in part:
                if ch.isdigit():
                    digits += ch
                else:
                    break
            if digits:
                ints.append(int(digits))
            else:
                raise ValueError(f"Invalid numeric component {part!r} in version string {s!r}") from exc

    return tuple(ints)

