    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("input must be a string")
    if not s:
        return (0,)
    import re
    parts = s.split(".")
    nums = []
    for p in parts:
        m = re.match(r"(\d+)", p)
        if m:
            nums.append(int(m.group(1)))
    return tuple(nums) if nums else (0,)

