def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd

    exec_path = cmd[0]
    # If the executable does not exist as a file, return original
    if not os.path.exists(exec_path):
        return cmd

    # Resolve to absolute path if needed
    if not os.path.isabs(exec_path):
        try:
            exec_path = os.path.abspath(exec_path)
        except Exception:
            # leave it unchanged
            pass

    # Attempt to read the file for a shebang
    try:
        with open(exec_path, 'r', encoding='utf-8', errors='ignore') as f:
            first_line = f.readline()
    except Exception:
        return cmd

    if not first_line.startswith('#!'):
        return cmd

    # Extract shebang interpreter part
    shebang = first_line[2:].strip()
    if not shebang:
        return cmd

    parts = shebang.split()
    interpreter = None

    # Handle #! /usr/bin/env python style
    if parts[0].endswith('env'):
        if len(parts) >= 2:
            interpreter = parts[1]
    else:
        interpreter = parts[0]

    if interpreter is None:
        return cmd

    # Resolve interpreter if absolute or found in PATH
    if os.path.isabs(interpreter):
        interp_path = interpreter
    elif os.path.sep in interpreter:
        # Relative path with separators, try relative to script dir
        script_dir = os.path.dirname(exec_path)
        interp_path = os.path.normpath(os.path.join(script_dir, interpreter))
        if not os.path.isfile(interp_path):
            # fallback to PATH search
            interp_path = None
    else:
        # look in PATH
        interp_path = None

    if interp_path is None:
        # Attempt to find in PATH
        for path_dir in os.environ.get('PATH', '').split(os.pathsep):
            candidate = os.path.join(path_dir, interpreter)
            if os.path.isfile(candidate):
                interp_path = candidate
                break

    if interp_path is None and not os.path.isfile(interpreter):
        # Could not resolve interpreter; fall back to original command
        return cmd

    # Build new command tuple
    new_cmd = (interp_path,) + cmd[1:]

    # On Windows the argument list may need quoting if path contains spaces
    # We'll rely on subprocess to handle quoting; no changes here.

    return new_cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return cmd
    cmd_list = list(cmd)
    # Quote arguments containing whitespace on Windows
    if platform.system() == 'Windows':
        for idx, arg in enumerate(cmd_list):
            if ' ' in arg or '\t' in arg:
                # Escape internal double quotes
                escaped = arg.replace('"', r'\"')
                cmd_list[idx] = f'"{escaped}"'
    # Handle shebang indirectly: if the first element looks like a python script
    # and is not an interpreter, prepend the correct interpreter.
    first = cmd_list[0]
    if first.lower().endswith('.py') and os.path.isfile(first):
        # If the first element is already a recognized interpreter, leave it
        if not any(first.lower().startswith(p) for p in (sys.executable, '/usr/bin/env')):
            # prepend the system python interpreter
            cmd_list = [sys.executable, first] + cmd_list[1:]
    return tuple(cmd_list)

