def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize < 0:
        raise ValueError("maxsize must be non-negative")
    if maxsize == 0:
        def wrapper(func):
            return func
        return wrapper

    def key_factory(args, kwargs, typed):
        key = args
        if kwargs:
            key += tuple(sorted(kwargs.items()))
        if typed:
            key += tuple(type(a) for a in args)
            key += tuple((k, type(v)) for k, v in sorted(kwargs.items()))
        return key

    def decorator(func):
        cache = {}
        order = collections.OrderedDict()

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = key_factory(args, kwargs, typed)
            if key in cache:
                # mark as most recently used
                order.move_to_end(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order[key] = None
            order.move_to_end(key)
            if len(cache) > maxsize:
                # evict the most recent item
                evicted_key, _ = order.popitem(last=True)
                del cache[evicted_key]
            return result

        return wrapper

    return decorator

