    from collections import OrderedDict, namedtuple

    if not isinstance(maxsize, int) or maxsize <= 0:
        raise TypeError('maxsize must be a positive integer')
    if not isinstance(typed, bool):
        raise TypeError('typed must be a bool')

    _CacheInfo = namedtuple('_CacheInfo', ['hits', 'misses', 'maxsize', 'currsize'])

    def decorating_function(user_function):
        cache = OrderedDict()
        cache_hits = 0
        cache_misses = 0

        def make_key(args, kwargs):
            if typed:
                args_key = tuple((type(v), v) for v in args)
                kwargs_key = tuple((k, type(v), v) for k, v in sorted(kwargs.items()))
                return (args_key, kwargs_key)
            else:
                args_key = tuple(args)
                kwargs_key = tuple(sorted(kwargs.items()))
                return (args_key, kwargs_key)

        @wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal cache_hits, cache_misses
            key = make_key(args, kwargs)
            try:
                result = cache[key]
                cache.move_to_end(key)
                cache_hits += 1
            except KeyError:
                result = user_function(*args, **kwargs)
                cache[key] = result
                cache.move_to_end(key)
                cache_misses += 1
                if len(cache) > maxsize:
                    cache.popitem(last=False)
            return result

        def cache_info():
            return _CacheInfo(cache_hits, cache_misses, maxsize, len(cache))

        def cache_parameters():
            return {'maxsize': maxsize, 'typed': typed}

        wrapper.cache_clear = cache.clear
        wrapper.cache_info = cache_info
        wrapper.cache_parameters = cache_parameters

        return wrapper

    return decorating_function

