    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        from functools import wraps
        from collections import OrderedDict

        cache = OrderedDict()
        hits = misses = 0

        def _make_key(args, kwargs):
            # base key from arguments
            key = args
            if kwargs:
                # sort kwargs to ensure reproducible ordering
                items = tuple(sorted(kwargs.items()))
                key += items
            # optionally include type information
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in items)
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            # disabled cache mode
            if maxsize is not None and maxsize <= 0:
                return func(*args, **kwargs)
            key = _make_key(args, kwargs)
            try:
                result = cache[key]
                hits += 1
            except KeyError:
                misses += 1
                result = func(*args, **kwargs)
                cache[key] = result
                # evict oldest item if beyond maxsize
                if 0 < maxsize <= len(cache):
                    cache.popitem(last=False)
            return result

        def cache_info():
            """Return cache statistics"""
            class _CacheInfo:
                __slots__ = ('hits', 'misses', 'maxsize', 'currsize')
                def __init__(self, hits, misses, maxsize, currsize):
                    self.hits = hits
                    self.misses = misses
                    self.maxsize = maxsize
                    self.currsize = currsize
                def __repr__(self):
                    return (f'_CacheInfo(hits={self.hits}, misses={self.misses}, '
                            f'maxsize={self.maxsize}, currsize={self.currsize})')
            return _CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            """Clear all cache data and statistics"""
            nonlocal hits, misses
            cache.clear()
            hits = misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        freq = {}
        order = {}
        _counter = 0

        def _make_key(args, kwargs, typed_flag):
            """Build a hashable key from args and kwargs."""
            # simple key: tuple of args + sorted kwargs items
            try:
                if typed_flag:
                    args_key = tuple((a, type(a)) for a in args)
                else:
                    args_key = args
                kwargs_key = tuple(sorted(kwargs.items()))
                return args_key + kwargs_key
            except TypeError:
                # if unhashable elements, signal to caller
                raise

        def wrapper(*args, **kwargs):
            nonlocal _counter
            try:
                key = _make_key(args, kwargs, typed)
            except TypeError:
                return func(*args, **kwargs)

            if key in cache:
                freq[key] += 1
                return cache[key]

            result = func(*args, **kwargs)

            # Evict if capacity exceeded
            if len(cache) >= maxsize:
                # Find the least frequently used key(s)
                min_freq = min(freq.values())
                candidates = [k for k, f in freq.items() if f == min_freq]
                # Resolve tie by least recently used order
                evict_key = min(candidates, key=lambda k: order[k])
                del cache[evict_key]
                del freq[evict_key]
                del order[evict_key]

            cache[key] = result
            freq[key] = 1
            _counter += 1
            order[key] = _counter
            return result

        return wrapper
    return decorator

