def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Collect all unique items and remember first occurrence order
    first_occ = {}
    counter = 0
    for ordering in orderings:
        for item in ordering:
            if item not in first_occ:
                first_occ[item] = counter
                counter += 1

    # Build graph: adjacency list and indegree counts
    adjacency = {item: set() for item in first_occ}
    indegree = {item: 0 for item in first_occ}

    for ordering in orderings:
        for u, v in zip(ordering, ordering[1:]):
            if v not in adjacency[u]:
                adjacency[u].add(v)
                indegree[v] += 1

    # Kahn's algorithm with deterministic ordering using first_occ
    import heapq
    zero_heap = []
    for node, deg in indegree.items():
        if deg == 0:
            heapq.heappush(zero_heap, (first_occ[node], node))

    result = []
    while zero_heap:
        _, node = heapq.heappop(zero_heap)
        result.append(node)
        for neigh in adjacency[node]:
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                heapq.heappush(zero_heap, (first_occ[neigh], neigh))

    if len(result) != len(first_occ):
        raise ValueError("Inconsistent orderings: cannot resolve a total order.")
    return result

def _legacy_mergeOrderings(orderings):
    """
    Merge multiple orderings so that within-ordering order is preserved.

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Build directed graph of ordering constraints and compute in-degrees
    adjacency = {}
    indegree = {}
    for ordering in orderings:
        if len(ordering) < 2:
            continue
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            if u not in adjacency:
                adjacency[u] = set()
            if v not in adjacency[u]:
                adjacency[u].add(v)
                indegree[v] = indegree.get(v, 0) + 1
            # Ensure nodes exist in indegree dict
            if u not in indegree:
                indegree[u] = indegree.get(u, 0)

    # Ensure all nodes appear in indegree dict
    all_nodes = set(indegree.keys())
    for ordering in orderings:
        for node in ordering:
            all_nodes.add(node)
            indegree.setdefault(node, 0)

    # Determine priority order for tie-breaking (first appearance)
    priority = {}
    pos = 0
    for ordering in orderings:
        for node in ordering:
            if node not in priority:
                priority[node] = pos
                pos += 1

    # Kahn's algorithm with stable tie-breaking by priority
    zero = [node for node in all_nodes if indegree.get(node, 0) == 0]
    zero.sort(key=lambda x: priority.get(x, pos))
    result = []

    while zero:
        node = zero.pop(0)
        result.append(node)
        for nb in adjacency.get(node, []):
            indegree[nb] -= 1
            if indegree[nb] == 0:
                zero.append(nb)
        zero.sort(key=lambda x: priority.get(x, pos))

    if len(result) != len(all_nodes):
        raise ValueError("Orderings contain a cycle or inconsistency")
    return result

