def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class objects") from None

    minimal = []
    seen = set()
    for cls in iterator:
        if not isinstance(cls, type):
            raise TypeError(f"expected a class object, got {type(cls).__name__}")
        if cls in seen:
            # skip duplicates
            continue
        # keep cls only if it is not a subclass of any already kept class
        if not any(issubclass(cls, base) for base in minimal):
            minimal.append(cls)
            seen.add(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of class objects")
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Item {cls!r} is not a class object")
        # Determine if this class is redundant or should replace old ones
        skip = False
        to_remove = []
        for existing in result:
            try:
                if issubclass(existing, cls):
                    # existing is a subclass of cls, so cls supersedes it
                    to_remove.append(existing)
                elif issubclass(cls, existing):
                    # new class is a subclass of an existing one, so it is redundant
                    skip = True
                    break
            except TypeError:
                # If either is not a class, treat as not subclassable
                continue
        if skip:
            continue
        # Remove any existing classes that are subclasses of the new one
        for rem in to_remove:
            result.remove(rem)
        # Append the new class preserving order
        result.append(cls)
    return result

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent.
    """
    if not classes:
        return []

    result = []
    for cls in classes:
        # Skip non‑class entries; they cannot be part of a bases list
        try:
            is_cls = isinstance(cls, type)
        except Exception:
            # In case of weird objects that raise on isinstance
            is_cls = False

        if not is_cls:
            continue

        # Skip if the class is already implied by an earlier base
        try:
            if any(issubclass(cls, existing) for existing in result):
                continue
        except Exception:
            # If subclass check fails (e.g., cls not a real class), skip it
            continue

        result.append(cls)

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    names = {}
    try:
        mro = self.__class__.__mro__ if all else [self.__class__]
    except AttributeError:
        mro = [self.__class__]
    seen = set()
    for cls in mro:
        for name, member in cls.__dict__.items():
            # Skip internal attributes.
            if name.startswith("_"):
                continue
            # Avoid duplicates from base classes.
            if name in seen:
                continue
            seen.add(name)
            desc = None
            # Handle property objects.
            if isinstance(member, property):
                desc = member.__doc__
                if desc is None and hasattr(member.fget, "__doc__"):
                    desc = member.fget.__doc__
            # Handle methods or functions.
            elif callable(member):
                desc = member.__doc__
            # If the member has a __doc__ attribute directly.
            elif hasattr(member, "__doc__"):
                desc = member.__doc__
            # Only add if a description is available.
            if desc is not None:
                # Remove surrounding whitespace.
                desc = desc.strip() if isinstance(desc, str) else desc
                names[name] = desc
    return names

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    seen = set()

    def add_from_cls(cls):
        for name, obj in vars(cls).items():
            if name in seen:
                continue
            if name.startswith('_'):
                continue
            if name == 'namesAndDescriptions':
                continue
            doc = getattr(obj, "__doc__", "")
            if doc is None:
                doc = ""
            result[name] = doc
            seen.add(name)

    # Add attributes from the class itself
    add_from_cls(self.__class__)

    # If all is True, walk the MRO and add base class attributes
    if all:
        for base in reversed(self.__class__.__mro__[1:]):
            if base is object:
                continue
            add_from_cls(base)

    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Determine which classes to inspect: either just this class or all in the MRO
    classes = (self.__class__,) if not all else tuple(
        cls for cls in self.__class__.__mro__ if cls is not object
    )

    descriptions = {}
    # Iterate over class dictionaries to collect attribute names
    for cls in classes:
        for name, obj in cls.__dict__.items():
            # Skip private and special attributes
            if name.startswith('_'):
                continue
            # Skip methods and other callables
            if callable(obj):
                continue
            # Retrieve the docstring if available
            desc = None
            # Many objects expose a __doc__ attribute
            if hasattr(obj, "__doc__"):
                desc = obj.__doc__
            descriptions[name] = desc
    return descriptions

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect all attribute names from the instance and its class hierarchy
    names = set()

    # Instance attributes
    try:
        names.update(vars(self).keys())
    except Exception:
        pass  # If vars() fails, ignore and continue

    # Class attributes (including those defined in base classes)
    try:
        for cls in type(self).__mro__:
            for name in cls.__dict__:
                # Skip special attributes that are not part of the interface
                if name in ("__dict__", "__weakref__", "__module__", "__doc__"):
                    continue
                names.add(name)
    except Exception:
        pass  # If introspection fails, ignore

    # If not requesting all, filter out private/internal names
    if not all:
        names = {name for name in names if not name.startswith("_")}

    # Return a sorted list for deterministic ordering
    return sorted(names)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect attribute names from the class and its bases.
    attr_names = set()
    for cls in self.__class__.__mro__:
        if cls is object:
            continue
        for name, val in cls.__dict__.items():
            # Skip special/dunder names.
            if name.startswith('__') and name.endswith('__'):
                continue
            # Skip callables like methods.
            if callable(val):
                continue
            # If not requested all, skip private (leading underscore) names.
            if not all and name.startswith('_'):
                continue
            attr_names.add(name)
    # Return a sorted list for consistency.
    return sorted(attr_names)

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    result = []
    for name in dir(self):
        if not all and name.startswith("_"):
            continue
        try:
            val = getattr(self, name)
        except Exception:
            continue
        if callable(val):
            continue
        result.append(name)
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        # Class level attributes that are not private and not callables
        class_attrs = [
            k
            for k, v in getattr(self.__class__, "__dict__", {}).items()
            if not k.startswith("_") and not callable(v)
        ]

        # Instance level attributes that are not private
        instance_attrs = [
            k for k in getattr(self, "__dict__", {}).keys() if not k.startswith("_")
        ]

        # Preserve insertion order and remove duplicates
        names = list(dict.fromkeys(class_attrs + instance_attrs))

        if all:
            # Include every name accessible via dir(self) (methods, private, etc.)
            all_names = set(dir(self))
            return sorted(all_names)

        return names
    except Exception:
        # Fallback: return empty list on any unexpected error
        return []

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Handle None explicitly
    if sequence is None:
        return output

    # If the input is a collection (list, tuple, set), iterate and recurse
    if isinstance(sequence, (list, tuple, set)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        # Anything else is treated as a single interface/spec
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # Check if we hit the special Broken sentinel (from zope.interface)
    # If it is present in the types base classes, just return the sequence
    try:
        bases = getattr(sequence, "__bases__", ())
        if "Broken" in [b.__name__ for b in bases]:
            return [sequence]
    except Exception:
        pass

    # Identify whether the sequence is a single interface specification.
    # We consider it an interface if its class inherits from InterfaceClass
    # or zope.interface.declarations.Implements.  Since these are optional
    # imports, we guard accesses with hasattr and fallback to string checks.
    cls = sequence.__class__
    mro = getattr(cls, "__mro__", ())

    is_interface = any(
        (isinstance(b, type) and b.__name__ in ("InterfaceClass", "Implements"))
        for b in mro
    )

    if is_interface:
        output.append(sequence)
    else:
        # Treat built‑in containers and other iterables (except strings/bytes)
        if isinstance(sequence, (list, tuple, set)):
            for v in sequence:
                _normalizeargs(v, output)
        else:
            try:
                it = iter(sequence)
                if isinstance(sequence, (str, bytes)):
                    output.append(sequence)
                else:
                    for v in it:
                        _normalizeargs(v, output)
            except TypeError:
                # Not iterable: just append it
                output.append(sequence)

    return output

