def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        import importlib
        return importlib.import_module('ase.optimize._coptimizations')
    except ImportError:
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # If PURE_PYTHON is True, only pure‑Python implementation is available;
        # otherwise C optimizations are required.
        return not PURE_PYTHON
    except NameError:
        # If the flag is not defined, default to False (i.e. do not require C)
        return False

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        # C optimizations are required when we are not running in pure‑Python mode
        return not bool(PURE_PYTHON)
    except NameError:
        # If the flag is not set, assume optimizations are desired
        return True

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the current context to an empty dictionary
        if hasattr(self, 'context'):
            self.context = {}
        else:
            # If the attribute does not exist, create it
            self.context = {}

        # Reinitialize bins
        if hasattr(self, 'initial_value') and self.initial_value is not None:
            # If bins already exist, preserve their length
            if hasattr(self, 'bins'):
                self.bins = [self.initial_value] * len(self.bins)
            else:
                self.bins = [self.initial_value]
        else:
            # Fall back to a method that creates bins dynamically
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                try:
                    self.bins = self.make_bins()
                except Exception as e:
                    # In case bin creation fails, store an empty list
                    self.bins = []
                    raise RuntimeError(f"Failed to create bins: {e}") from e
            else:
                # If no bin creation method is available, store an empty list
                self.bins = []

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset the context dictionary to an empty dict
        if hasattr(self, "context"):
            self.context = {}
        else:
            # If a different attribute name is used, set it to an empty dict
            setattr(self, "context", {})

        # Reinitialize the bins
        try:
            # Prefer an explicit initial_value if available
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # Determine the number of bins; use existing bin list length if present,
                # otherwise fall back to a defined nbins attribute
                bin_count = getattr(self, "nbins", 0)
                if bin_count == 0 and hasattr(self, "bins"):
                    bin_count = len(self.bins)
                # Create a new bins list filled with initial_value
                self.bins = [self.initial_value for _ in range(bin_count)]
            # Otherwise, try to use the make_bins method
            elif hasattr(self, "make_bins") and callable(getattr(self, "make_bins")):
                self.bins = self.make_bins()
            else:
                raise ValueError("No valid method for reinitializing bins: missing 'initial_value' "
                                 "and callable 'make_bins'")
        except Exception as exc:
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize the bins
    if getattr(self, 'initial_value', None) is not None:
        iv = self.initial_value
        if hasattr(self, 'bins') and isinstance(self.bins, list):
            # Refill existing bins with the initial value
            self.bins = [iv] * len(self.bins)
        elif hasattr(self, 'counts') and isinstance(self.counts, list):
            # Alternative name for bin contents
            self.counts = [iv] * len(self.counts)
        else:
            # No conventional bin/container attribute found; do nothing
            pass
    elif hasattr(self, 'make_bins') and callable(self.make_bins):
        try:
            # Use the make_bins method to generate bins anew
            self.bins = self.make_bins()
        except Exception as e:
            raise RuntimeError(f"Failed to create bins during reset: {e}") from e
    else:
        raise AttributeError("Histogram cannot be reset: no 'initial_value' or "
                             "'make_bins' defined")

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    try:
        self.context = {}
    except Exception:
        # If the object doesn't have a context attribute, ignore
        pass

    # Reinitialize bins
    try:
        # If an explicit initial_value is defined, use it
        initial = getattr(self, 'initial_value', None)
        if initial is not None:
            # Preserve the original number of bins if they already exist
            if hasattr(self, 'bins') and isinstance(self.bins, (list, tuple)):
                self.bins = [initial] * len(self.bins)
            else:
                self.bins = initial
        else:
            # Fall back to generating new bins
            if hasattr(self, 'make_bins') and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If there is no make_bins method, clear bins if possible
                if hasattr(self, 'bins'):
                    self.bins = []
    except Exception:
        # In case any of the attributes are missing or operations fail, quietly ignore
        pass
    # End of reset method
    return None

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        self.context = {}
        try:
            # If an initial_value attribute was used during initialization,
            # re-create the bins using that value.
            if getattr(self, 'initial_value', None) is not None:
                # Determine number of bins either from a stored count or from the existing bins list.
                num_bins = getattr(self, 'num_bins', None)
                if num_bins is None:
                    if hasattr(self, 'bins'):
                        num_bins = len(self.bins)
                    else:
                        num_bins = 0
                self.bins = [self.initial_value] * num_bins
            # If no initial_value, fall back to the make_bins method if present.
            elif hasattr(self, 'make_bins') and callable(self.make_bins):
                self.bins = self.make_bins()
            # If neither mechanism is available, create an empty bins list.
            else:
                self.bins = []
        except Exception as exc:
            # Ensure the histogram remains in a consistent state.
            self.bins = []
            raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    # Optional header
    if header is not None:
        if isinstance(header, (list, tuple)):
            header_line = separator.join(str(h) for h in header)
        else:
            header_line = str(header)
        lines.append(header_line)

    # Iterate over the graph points
    for point in self:
        try:
            # Attempt to extract coordinates and values
            if hasattr(point, "coordinate") and hasattr(point, "value"):
                coords = point.coordinate
                values = point.value
            elif isinstance(point, tuple):
                # Expect (coords, values) or a flat tuple
                if len(point) == 2:
                    coords, values = point
                else:
                    coords, values = point[0], tuple(point[1:])
            else:
                # Fallback: if point is iterable, split first part as coords
                try:
                    coords, values = point
                except Exception:
                    coords = point
                    values = ()
        except Exception:
            # Skip points that cannot be interpreted
            continue

        # Convert coordinates to string list
        if isinstance(coords, (list, tuple)):
            coord_parts = [str(c) for c in coords]
        else:
            coord_parts = [str(coords)]

        # Convert values to string list, treating non-string iterables as parts
        if isinstance(values, (list, tuple)):
            value_parts = [str(v) for v in values]
        else:
            # Strings are considered a single value, not split
            value_parts = [str(values)]

        # Form the CSV line
        line = separator.join(coord_parts + value_parts)
        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError(
            f"coord_name must be a string, got {type(coord_name).__name__}"
        )
    # Primary source: a dedicated error-indices mapping if it exists
    try:
        err_map = getattr(self, "_err_indices", None)
        if isinstance(err_map, dict):
            return list(err_map.get(coord_name, []))
    except Exception:
        # ignore any issues accessing _err_indices
        pass

    # Fallback: look into coordinate variable metadata
    try:
        coords = getattr(self, "coords", {})
        if isinstance(coords, dict):
            coord_obj = coords.get(coord_name)
            if coord_obj is not None:
                # Common pattern: an attribute `error_indices`
                if hasattr(coord_obj, "error_indices"):
                    return list(coord_obj.error_indices)
                # Or a simple dict entry
                if isinstance(coord_obj, dict) and "error_indices" in coord_obj:
                    return list(coord_obj["error_indices"])
    except Exception:
        # ignore any issues in the fallback path
        pass

    # Default: no error indices found
    return []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        # Attempt to fetch the error index mapping from this instance.
        err_map = getattr(self, "_err_indices", {})
        # Return a list of indices (empty if not found or converted from other sequence types).
        indices = err_map.get(coord_name, [])
        if isinstance(indices, (list, tuple, np.ndarray)):
            return list(indices)
        return []
    except Exception:
        # In any unexpected failure, return an empty list to avoid breaking callers.
        return []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the internal mapping of error indices if it exists
    try:
        err_dict = getattr(self, "_error_indices", {})
    except Exception:
        return []

    if not isinstance(err_dict, dict):
        return []

    # Get indices for the requested coordinate
    indices = err_dict.get(coord_name)
    if indices is None:
        return []

    # Normalize to a sorted list of unique indices
    try:
        import numpy as _np  # local import to avoid global dependencies
        indices = _np.unique(indices).tolist()
    except Exception:
        try:
            indices = sorted(set(indices))
        except Exception:
            indices = []

    return indices

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # First try to obtain precomputed error indices stored on the object
    for attr in ('_err_indices', 'err_indices'):
        err_map = getattr(self, attr, None)
        if isinstance(err_map, dict):
            return err_map.get(coord_name, [])
    # If no mapping, attempt to locate an error variable that follows a naming convention
    err_var_name = f'{coord_name}_err'
    # Look for the error variable in the object's attributes or variable dictionary
    err_var = getattr(self, err_var_name, None)
    if err_var is None:
        err_dict = getattr(self, '_variables', None)
        if isinstance(err_dict, dict):
            err_var = err_dict.get(err_var_name)
    # If an error variable is found, compute indices of non‑zero (or non‑nan) errors
    if err_var is not None:
        try:
            # Support both plain arrays and objects with a .values attribute (e.g., DataArray)
            if hasattr(err_var, 'values'):
                arr = err_var.values
            else:
                arr = err_var
            return [i for i, val in enumerate(arr) if val != 0]
        except Exception:
            # Gracefully handle any conversion or iteration errors
            return []
    # Fallback: no error indices available
    return []

def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        if not isinstance(context, dict):
            raise TypeError("context must be a dictionary")

        # Preserve existing values in context.value
        if 'value' not in context:
            context['value'] = {}
        # Simple assumption: any attribute that doesn't start with '_' and
        # is not a callable is considered a graph value.
        for attr_name in dir(self):
            if attr_name.startswith('_'):
                continue
            try:
                attr_val = getattr(self, attr_name)
            except Exception:
                continue
            if callable(attr_val):
                continue
            context['value'][attr_name] = attr_val

        # Handle error fields
        error_prefix = 'error_'
        # Preserve existing error subcontext
        if 'error' not in context:
            context['error'] = {}
        # Determine coordinate mapping: first 3 error prefixes map to x, y, z
        coord_map = {'x': 'x', 'y': 'y', 'z': 'z'}
        # Build a list of all attributes in order as they appear in __dict__
        attr_keys = [k for k in self.__dict__ if not k.startswith('_')]
        # Simple heuristic: first three non-error attributes are x, y, z
        coord_keys = attr_keys[:3]
        coord_names = {}
        for idx, key in enumerate(coord_keys):
            if idx == 0:
                coord_names[key] = 'x'
            elif idx == 1:
                coord_names[key] = 'y'
            elif idx == 2:
                coord_names[key] = 'z'
        # Iterate expected error fields
        for attr_name in dir(self):
            if not attr_name.startswith(error_prefix):
                continue
            # Strip prefix
            remainder = attr_name[len(error_prefix):]
            # Split into possible coordinate part and suffix
            parts = remainder.split('_', 1)
            if len(parts) == 2:
                coord_part, suffix = parts
            else:
                coord_part = parts[0]
                suffix = ''
            # Determine coordinate letter
            coord = coord_names.get(coord_part, None)
            if coord is None:
                # Fallback: try to match first 3 graph fields
                try:
                    idx = attr_keys.index(coord_part)
                    coord = 'x' if idx == 0 else 'y' if idx == 1 else 'z'
                except ValueError:
                    coord = 'x'  # default
            # Build key for error entry
            key = f"{coord}_{suffix}" if suffix else coord
            # Append index placeholder (using 0; real index logic is domain specific)
            context['error'].setdefault(key, {})
            context['error'][key]['index'] = 0
        # No return value needed; context modified in place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    bins_arr = np.asarray(bins)

    # Determine widths for each dimension
    if isinstance(edges, tuple):
        widths = [np.diff(e) for e in edges]
    else:
        # 1‑D case
        widths = [np.diff(edges)]

    # Validate shape consistency
    try:
        ndim = len(widths)
        exp_shape = tuple(len(w) for w in widths)
        if bins_arr.shape != exp_shape:
            raise ValueError(
                f"Shape of bins {bins_arr.shape} does not match "
                f"edge widths {exp_shape}"
            )
    except Exception as exc:
        raise ValueError(f"Error validating dimensions: {exc}") from None

    # Compute weight grid (product of widths for each bin)
    if ndim == 1:
        weight_grid = widths[0]
    else:
        weight_grid = widths[0]
        for w in widths[1:]:
            weight_grid = np.multiply.outer(weight_grid, w)

    # Compute integral
    return np.sum(bins_arr * weight_grid)

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np
    bins = np.asarray(bins)

    # Handle 1‑D histogram
    if np.isscalar(edges):
        raise ValueError("edges must be an array or a sequence of arrays")
    edges = np.asarray(edges)

    if edges.ndim == 1:
        if bins.ndim != 1:
            raise ValueError("For 1‑D edges the histogram must also be 1‑D")
        widths = np.diff(edges)
        return np.sum(bins * widths)

    # Handle multi‑D histogram: edges should be a sequence (list/tuple) of arrays
    if isinstance(edges, (list, tuple)):
        ndim = bins.ndim
        if len(edges) != ndim:
            raise ValueError("Number of edge sequences must match histogram dimensions")
        weights = np.ones_like(bins, dtype=float)
        for i, e in enumerate(edges):
            e = np.asarray(e)
            diff = np.diff(e)
            # reshape diff so it can be broadcast over the corresponding axis
            shape = [1] * ndim
            shape[i] = len(diff)
            weights *= diff.reshape(shape)
        return np.sum(bins * weights)

    # Fallback: treat edges as a single array for bin widths of a 1‑D histogram
    if edges.ndim == 2 and edges.shape[1] == 2:
        # each row is [start, end] for a bin
        widths = edges[:, 1] - edges[:, 0]
        if bins.shape[0] != widths.size:
            raise ValueError("Number of bins does not match number of edges")
        return np.sum(bins.flatten() * widths)
    raise ValueError("Unsupported format for edges")

