    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference expects both arguments to be dictionaries")

    # interpret level: -1 or any negative means infinite recursion
    recurse_allowed = level != 0

    result = {}
    for key, value in d1.items():
        if key not in d2:
            # key missing in d2: include whole value
            result[key] = value
        else:
            value2 = d2[key]
            if (
                isinstance(value, dict)
                and isinstance(value2, dict)
                and recurse_allowed
            ):
                # recurse with decreased depth (if level > 0)
                sublevel = level - 1 if level > 0 else -1
                subdiff = difference(value, value2, sublevel)
                if subdiff:
                    result[key] = subdiff
            else:
                # values differ (including when non-dict)
                if value != value2:
                    result[key] = value

    return result

