        if isinstance(val1, dict) and isinstance(val2, dict):
            # Determine whether recursion is allowed
            if level == -1 or level > 1:
                # Recurse with updated depth
                next_level = level if level == -1 else level - 1
                subdiff = difference(val1, val2, next_level)
                if subdiff:
                    diff[key] = subdiff
