        raise TypeError("difference expects two dictionaries")

    def _diff(a, b, depth):
        # if depth is limited and reached zero, compare as values
        if depth == 0:
            return None if a == b else a

        if not isinstance(a, dict) or not isinstance(b, dict):
            return None if a == b else a

        diff = {}
        for k, va in a.items():
            if k not in b:
                diff[k] = va
            else:
                vb = b[k]
                if isinstance(va, dict) and isinstance(vb, dict):
                    # Recurse deeper; for infinite recursion keep depth negative
                    sub = _diff(va, vb, depth - 1 if depth > 0 else -1)
                    if sub:
                        diff[k] = sub
                else:
                    if va != vb:
                        diff[k] = va
        return diff if diff else None

    result = _diff(d1, d2, level)
    return result if result is not None else {}

