def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure weight is numeric
    try:
        weight = float(weight)
    except Exception:
        raise ValueError("weight must be a numeric scalar")

    # Helper to check bounds for a single dimension
    def _is_within_bounds(e, c):
        idx = np.searchsorted(e, c, side='right') - 1
        if idx < 0 or idx >= len(e) - 1:
            return None, None
        return idx, e

    # If edges is a sequence, treat as multidimensional histogram
    if isinstance(self.edges, (list, tuple)):
        # Convert coordinate to a flat list/array
        coord_arr = np.asarray(coord)
        if coord_arr.ndim == 0:
            coord_arr = coord_arr.reshape((1,))
        if coord_arr.shape[0] != len(self.edges):
            raise ValueError("coord dimensionality does not match histogram edges")
        indices = []
        for e, c in zip(self.edges, coord_arr):
            idx, _ = _is_within_bounds(e, c)
            if idx is None:
                return  # coordinate out of bounds, ignore
            indices.append(idx)
        # Add weight to the correct bin
        self.values[tuple(indices)] += weight
    else:
        # One-dimensional histogram
        e = self.edges
        idx, _ = _is_within_bounds(e, coord)
        if idx is None:
            return  # ignore out-of-bounds coordinate
        self.values[idx] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """

    # Defer import of re to avoid a top‑level import statement
    re = __import__('re')
    KEY_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')
    VALUE_REGEX = re.compile(r'^[a-zA-Z0-9_]+$')

    def _format_error(obj, msg):
        """Return an error dict using the string form of the object."""
        return {str(obj): msg}

    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append(_format_error(key, 'expected string or bytes-like object'))
        else:
            key_str = key.decode() if isinstance(key, bytes) else key
            if not KEY_REGEX.fullmatch(key_str):
                messages.append(_format_error(
                    key_str,
                    f"Label key '{key_str}' does not match the regex [{KEY_REGEX.pattern}]"))

        # Recursive check for the value(s)
        def _check_value(v):
            if isinstance(v, (list, tuple)):
                for item in v:
                    _check_value(item)
            else:
                if not isinstance(v, (str, bytes)):
                    messages.append(_format_error(v, 'expected string or bytes-like object'))
                else:
                    val_str = v.decode() if isinstance(v, bytes) else v
                    if not VALUE_REGEX.fullmatch(val_str):
                        messages.append(_format_error(
                            val_str,
                            f"Label value '{val_str}' does not match the regex [{VALUE_REGEX.pattern}]"))

        _check_value(value)

    if messages:
        raise ValidationError(messages)

