        # Minimal stub if Django is not available
        class ValidationError(Exception):
            def __init__(self, messages):
                self.messages = messages
                super().__init__(str(messages))

    # Simple regex that accepts letters, digits, underscore, dot, hyphen, and colon
    LABEL_REGEX = re.compile(r'^[A-Za-z0-9_.:-]+$')

    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not LABEL_REGEX.match(key):
                messages.append({key: f"Label key '{key}' does not match the regex [{LABEL_REGEX.pattern}]"})

        # Validate value type
        if isinstance(value, (str, bytes)):
            if not LABEL_REGEX.match(value):
                messages.append({value: f"Label value '{value}' does not match the regex [{LABEL_REGEX.pattern}]"})
        else:
            # For non-string values, report an error using the string representation
            messages.append({repr(value): 'expected string or bytes-like object'})

    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    errors = []

    # Regular expressions for label keys and values (example patterns)
    key_regex = re.compile(r'^[A-Za-z0-9._-]+$')
    value_regex = re.compile(r'^[A-Za-z0-9._-]+$')

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
            continue

        # Validate key pattern
        if not key_regex.match(key):
            errors.append(
                {key: f"Label key '{key}' does not match the regex [{key_regex.pattern}]"}
            )

        # Helper to validate a single value element
        def _validate_value(v):
            if isinstance(v, (str, bytes)):
                if not value_regex.match(v):
                    errors.append(
                        {v: f"Label value '{v}' does not match the regex [{value_regex.pattern}]"}
                    )
            else:
                errors.append({str(v): 'expected string or bytes-like object'})

        # Validate value: if list/tuple, iterate through elements, otherwise validate directly
        if isinstance(value, (list, tuple)):
            for element in value:
                _validate_value(element)
            # If the container itself is expected to be a string (application specific),
            # uncomment the following line to validate the container as a whole.
            # _validate_value(value)
        else:
            _validate_value(value)

    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    errors = []

    # Define patterns for keys and values.
    key_pattern = re.compile(r'^\w+$')
    value_pattern = re.compile(r'^\w+$')

    if not isinstance(labels, dict):
        raise ValidationError(
            ["Labels must be a dictionary, got %r" % type(labels).__name__]
        )

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            try:
                if key_pattern.search(key) is None:
                    errors.append(
                        {key: "Label key '%s' does not match the regex [%s]" % (key, key_pattern.pattern)}
                    )
            except Exception:
                errors.append({key: "expected string or bytes-like object"})

        # Validate value
        # Accept only strings; lists are treated as invalid whole item.
        if not isinstance(value, str):
            errors.append({str(value): "expected string or bytes-like object"})
        else:
            try:
                if value_pattern.search(value) is None:
                    errors.append(
                        {value: "Label value '%s' does not match the regex [%s]"
                         % (value, value_pattern.pattern)}
                    )
            except Exception:
                errors.append({value: "expected string or bytes-like object"})

    if errors:
        raise ValidationError(errors)

def _get_resource_name_regex():
    """Build or return the regular expressions that are used to validate
    the name of the Krake resources.

    Returns:
        (re.Pattern): the compiled regular expressions, to validate
        the resource name.
    """
    try:
        if not hasattr(_get_resource_name_regex, "_pattern"):
            _get_resource_name_regex._pattern = re.compile(
                r'^[A-Za-z](?:[A-Za-z0-9_-]*[A-Za-z0-9])?$'
            )
        return _get_resource_name_regex._pattern
    except re.error as exc:
        raise ValueError("Failed to compile resource name regex") from exc

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise ValueError('manifest_dict must be a dictionary')
    result = {}
    # Keys that should keep their original value when at the top level
    # (common identifying fields in a Kubernetes manifest)
    _IDENTIFYING_FIELDS = {'apiVersion', 'kind'}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            # Recurse into nested dictionaries
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        elif isinstance(value, list):
            # Process each element of the list
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    # Primitive list items are replaced with None
                    new_list.append(None)
            result[key] = new_list
        else:
            # Primitive values: keep if we are at the top level and the key is an
            # identifying field, otherwise replace with None
            if first_level and key in _IDENTIFYING_FIELDS:
                result[key] = value
            else:
                result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dict")

    # Recursive builder
    def _build(d):
        out = {}
        for k, v in d.items():
            if isinstance(v, dict):
                out[k] = _build(v)
            elif isinstance(v, list):
                new_list = []
                for item in v:
                    if isinstance(item, dict):
                        new_list.append(_build(item))
                    else:
                        new_list.append(None)
                out[k] = new_list
            else:
                out[k] = None
        return out

    result = _build(manifest_dict)

    if first_level:
        # Copy identifying fields
        for id_key in ("kind", "apiVersion"):
            if id_key in manifest_dict:
                result[id_key] = manifest_dict[id_key]
        # Handle metadata specially
        if "metadata" in manifest_dict and isinstance(manifest_dict["metadata"], dict):
            meta_vals = {}
            for sub_key in ("name", "namespace"):
                meta_vals[sub_key] = manifest_dict["metadata"].get(sub_key)
            result["metadata"] = meta_vals

    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError(f"Expected a dict for manifest_dict, got {type(manifest_dict)!r}")

    # Set of keys whose values should be preserved when first_level is True.
    IDENTIFYING_KEYS = {"apiVersion", "kind", "name", "namespace"}

    def _process_node(node, is_first):
        if isinstance(node, dict):
            result = {}
            for key, value in node.items():
                if isinstance(value, (dict, list)):
                    result[key] = _process_node(value, is_first)
                else:
                    if is_first and key in IDENTIFYING_KEYS:
                        result[key] = value
                    else:
                        result[key] = None
            return result
        elif isinstance(node, list):
            # Replace each element appropriately
            return [
                _process_node(item, is_first) if isinstance(item, (dict, list)) else None
                for item in node
            ]
        else:
            # Primitive value: keep only if first_level and key is identifying
            return node if is_first else None

    return _process_node(manifest_dict, first_level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema
    """
    if not isinstance(manifest_dict, dict):
        # If input is not a dict, return empty dict to avoid crashes
        return {}

    # Fields that should be copied verbatim at the top level of the observer schema
    identify_fields = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        # Copy identifying fields unchanged when creating the top‑level schema
        if first_level and key in identify_fields:
            result[key] = value
            continue

        # Handle nested dictionaries recursively
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
            continue

        # Handle lists by creating a list of processed elements
        if isinstance(value, list):
            processed_list = []
            for item in value:
                if isinstance(item, dict):
                    processed_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    processed_list.append(None)
            result[key] = processed_list
            continue

        # Replace non‑dict, non‑list values with ``None``
        result[key] = None

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Recursively update a partial ``last_applied_manifest`` list from a
    partial Kubernetes response.

    Args:
        last_applied_manifest (list): The list that will be updated in-place.
        observer_schema (list): A list that describes the expected structure of
            each element in ``response``.  Each item in this list is expected
            to be a dict that may contain a ``type`` key (``'dict'`` or
            ``'list'``) and a ``fields`` key for nested structures.
        response (list): A list of elements returned by the Kubernetes API.
            Each element may be a primitive value, a dict, or another list.

    The function iterates over ``response`` and ensures that each element of
    ``last_applied_manifest`` is populated with the current value.  When an
    element is a ``dict`` or a ``list`` it calls the appropriate helper
    (``update_last_applied_manifest_dict_from_resp`` or this function
    recursively) to update nested structures.

    The function returns ``None`` and mutates ``last_applied_manifest`` in
    place; callers should be prepared for it to be extended (e.g., ``append``)
    when ``response`` contains more items than the current length of
    ``last_applied_manifest``.
    """
    if response is None:
        return

    if not isinstance(response, list):
        raise TypeError(
            f"Expected response to be list, got {type(response).__name__}"
        )

    # Ensure destination list has at least as many elements as the source
    required_len = len(response)
    while len(last_applied_manifest) < required_len:
        last_applied_manifest.append(None)

    for idx, resp_item in enumerate(response):
        # Determine corresponding schema, if available
        schema_item = None
        if idx < len(observer_schema):
            schema_item = observer_schema[idx]
        # If the destination element is None, create appropriate container
        if last_applied_manifest[idx] is None:
            if isinstance(resp_item, dict):
                last_applied_manifest[idx] = {}
            elif isinstance(resp_item, list):
                last_applied_manifest[idx] = []
            else:
                last_applied_manifest[idx] = resp_item
                continue  # Primitive value filled, go to next element

        # If element is a dict, recurse into dict helper
        if isinstance(resp_item, dict):
            if not isinstance(last_applied_manifest[idx], dict):
                raise TypeError(
                    f"Expected dict at index {idx} in last_applied_manifest, "
                    f"got {type(last_applied_manifest[idx]).__name__}"
                )
            # Extract fields from the schema if provided
            child_schema = None
            if isinstance(schema_item, dict):
                child_schema = schema_item.get("fields", [])
            # Delegate to dict helper (assumed to exist in scope)
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], child_schema, resp_item
            )
        # If element is a list, recurse into this list helper
        elif isinstance(resp_item, list):
            if not isinstance(last_applied_manifest[idx], list):
                raise TypeError(
                    f"Expected list at index {idx} in last_applied_manifest, "
                    f"got {type(last_applied_manifest[idx]).__name__}"
                )
            # Extract fields from the schema if provided
            child_schema = None
            if isinstance(schema_item, dict):
                child_schema = schema_item.get("fields", [])
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[idx], child_schema, resp_item
            )
        else:
            # Primitive types: simply overwrite
            last_applied_manifest[idx] = resp_item
    return None

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.
        observer_schema (dict): partial ``observer_schema`` describing the
            structure of the expected manifest.
        response (dict): partial response from the Kubernetes API.

    This function goes through all observed fields and initializes their value
    in ``last_applied_manifest`` if they are not yet present, recursing into
    nested dictionaries or lists as necessary.
    """
    if not isinstance(last_applied_manifest, dict) or not isinstance(response, dict):
        # nothing to update if data types are unexpected
        return

    # If observer_schema is a dict keyed by field name, use it to guide recursion.
    schema_lookup = observer_schema if isinstance(observer_schema, dict) else {}

    for key, value in response.items():
        # Skip internal Kubernetes response metadata if any
        if key in ("metadata", "status", "apiVersion", "kind"):
            continue

        # If the key is not present in the last applied manifest, copy it over
        if key not in last_applied_manifest:
            # Ensure we copy the reference to a mutable structure if needed
            if isinstance(value, (dict, list)):
                last_applied_manifest[key] = type(value)()
                # Recursively populate the new structure
                if isinstance(value, dict):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], schema_lookup.get(key, {}), value
                    )
                else:  # list
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[key], schema_lookup.get(key, []), value
                    )
            else:
                last_applied_manifest[key] = value
            continue

        # If the key exists but is a nested structure, recurse
        existing = last_applied_manifest[key]
        if isinstance(value, dict) and isinstance(existing, dict):
            update_last_applied_manifest_dict_from_resp(
                existing, schema_lookup.get(key, {}), value
            )
        elif isinstance(value, list) and isinstance(existing, list):
            update_last_applied_manifest_list_from_resp(
                existing, schema_lookup.get(key, []), value
            )
        # otherwise, leave the existing value intact (do not overwrite)
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Recursive helper for dictionary fields. Mirrors the logic above for dicts.
    """
    if not isinstance(last_applied_manifest, dict) or not isinstance(response, dict):
        return

    schema_lookup = observer_schema if isinstance(observer_schema, dict) else {}

    for key, value in response.items():
        if key in ("metadata", "status", "apiVersion", "kind"):
