        if key not in last_applied_manifest:
            if isinstance(value, (dict, list)):
                last_applied_manifest[key] = type(value)()
                if isinstance(value, dict):
                    update_last_applied_manifest_dict_from_resp(
                        last_applied_manifest[key], schema_lookup.get(key, {}), value
                    )
                else:
                    update_last_applied_manifest_list_from_resp(
                        last_applied_manifest[key], schema_lookup.get(key, []), value
                    )
            else:
                last_applied_manifest[key] = value
            continue

        existing = last_applied_manifest[key]
        if isinstance(value, dict) and isinstance(existing, dict):
            update_last_applied_manifest_dict_from_resp(
                existing, schema_lookup.get(key, {}), value
            )
        elif isinstance(value, list) and isinstance(existing, list):
            update_last_applied_manifest_list_from_resp(
                existing, schema_lookup.get(key, []), value
            )
    return last_applied_manifest

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated.
        observer_schema (dict or list): partial ``observer_schema`` indicating
            which fields to observe.  It can be a list of field names or a
            nested dictionary mirroring the expected structure of the manifest.
        response (dict): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.  If nested
    structures are encountered, the function recurses to handle them.
    """

    # Helper that recursively updates values based on schema and response
    def _update(dest, schema, resp):
        if isinstance(dest, dict) and isinstance(resp, dict):
            # If a schema dict is provided, walk its keys
            if isinstance(schema, dict):
                for key, sub_schema in schema.items():
                    if key not in dest and key in resp:
                        dest[key] = resp[key]
                    elif key in dest and key in resp:
                        _update(dest[key], sub_schema, resp[key])
            else:  # No schema: copy missing keys from response
                for key, value in resp.items():
                    if key not in dest:
                        dest[key] = value
        elif isinstance(dest, list) and isinstance(resp, list):
            # schema is expected to be a list describing the element schema
            elem_schema = schema[0] if isinstance(schema, list) and schema else {}
            for idx, r_item in enumerate(resp):
                if idx < len(dest):
                    _update(dest[idx], elem_schema, r_item)
                else:
                    dest.append(r_item.copy() if isinstance(r_item, dict) else r_item)
        else:
            # If the types do not match, replace the destination value
            # with the response value.  This branch is rarely hit in normal
            # operation but provides defensive handling.
            return

    # Normalize observer_schema to a dict of keys if it is a list
    if isinstance(observer_schema, list):
        schema = {key: None for key in observer_schema}
    else:
        schema = observer_schema if isinstance(observer_schema, dict) else {}

    # Ensure the top-level structures are dictionaries; otherwise raise
    if not isinstance(last_applied_manifest, dict):
        raise TypeError("last_applied_manifest must be a dict")
    if not isinstance(response, dict):
        raise TypeError("response must be a dict")

    _update(last_applied_manifest, schema, response)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.
    """
    if not isinstance(observer_schema, (list, tuple)):
        # nothing to observe
        return
    # Ensure ``last_applied_manifest`` has at least as many elements as the schema
    while len(last_applied_manifest) < len(observer_schema):
        last_applied_manifest.append(None)

    for idx, schema_item in enumerate(observer_schema):
        # Don't update if we've already got a value
        try:
            existing = last_applied_manifest[idx]
        except IndexError:
            existing = None
        if existing is not None:
            continue

        # Get the response value for this index (if present)
        resp_value = response[idx] if idx < len(response) else None

        # If the schema item is a dict, a nested dictionary is expected
        if isinstance(schema_item, dict):
            # initialise the nested dict if missing
            if resp_value is None or not isinstance(resp_value, dict):
                last_applied_manifest[idx] = {}
                # nothing else to do
                continue
            # ensure the nested dict exists
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = {}
            # recurse into dict
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], schema_item, resp_value
            )
        # If the schema item is a list, a list of nested objects is expected
        elif isinstance(schema_item, (list, tuple)):
            if resp_value is None or not isinstance(resp_value, list):
                last_applied_manifest[idx] = []
                continue
            # ensure the nested list exists
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = []
            # Make sure the nested list is long enough
            while len(last_applied_manifest[idx]) < len(resp_value):
                last_applied_manifest[idx].append(None)
            # Recursively update each element of the list
            for e_idx, elem_schema in enumerate(schema_item):
                if e_idx >= len(resp_value):
                    # No response for this element; skip
                    continue
                if not isinstance(elem_schema, (dict, list, tuple)):
                    # Simple element – copy if missing
                    if last_applied_manifest[idx][e_idx] is None:
                        last_applied_manifest[idx][e_idx] = resp_value[e_idx]
                else:
                    # Nested dict or list inside the list
                    if last_applied_manifest[idx][e_idx] is None:
                        if isinstance(elem_schema, dict):
                            last_applied_manifest[idx][e_idx] = {}
                        else:
                            last_applied_manifest[idx][e_idx] = []
                    # Recursive call
                    if isinstance(elem_schema, dict):
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[idx][e_idx],
                            elem_schema,
                            resp_value[e_idx],
                        )
                    else:
                        # It is a list of dicts or lists
                        update_last_applied_manifest_list_from_resp(
                            last_applied_manifest[idx][e_idx],
                            elem_schema,
                            resp_value[e_idx],
                        )
        # If the schema item is a simple type (e.g., string or primitive),
        # copy the value if it's missing
        else:
            if resp_value is not None:
                last_applied_manifest[idx] = resp_value
    # Note: The function mutates ``last_applied_manifest`` in place and returns
    # nothing (None).

def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Recursively update a list of fields in a partial last_applied_manifest.

    This function walks through the elements described by
    ``observer_schema`` and copies the corresponding values from
    ``response`` into ``last_applied_manifest`` where they are missing.
    Nested structures are handled by delegating to the appropriate
    helper functions for lists and dictionaries.  The update is performed
    in place and the original lists are mutated.

