        if manifest is None:
            return
        manifest_list = getattr(manifest, 'manifest', [])
        # Retrieve the current observers mapping (default to empty dict if not present)
        observers = getattr(app.spec, 'observers', {})
        if not isinstance(observers, dict):
            observers = {}
        # Iterate over each resource in the manifest
        for resource in manifest_list:
            if not isinstance(resource, dict):
                continue
            kind = resource.get('kind')
            metadata = resource.get('metadata', {})
            name = metadata.get('name')
            if not kind or not name:
                continue
            # Build a unique key for the observer (using kind/name)
            key = f"{kind}/{name}"
            # If this resource has no custom observer schema, set a default empty one
            if key not in observers:
                observers[key] = {}
        # Attach the updated observers back to the application spec
        app.spec.observers = observers
    except Exception:
        # Silently ignore any unexpected errors to avoid breaking the rest of the process
        pass

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
