    observer_schemas = getattr(spec, "observer_schemas", None)
    if observer_schemas is None:
        observer_schemas = {}
        setattr(spec, "observer_schemas", observer_schemas)

    # If the manifest is a list of resource dictionaries, iterate over it
    if isinstance(manifest, list):
        resources = manifest
    # Some projects use a dict keyed by kind or name; handle that
    elif isinstance(manifest, dict):
        resources = manifest.values()
    else:
        # Unknown format – nothing to do
        return

    for res in resources:
        try:
            kind = res.get("kind")
            if not kind or kind in observer_schemas:
                continue

            # Build a very permissive default schema that watches all fields
            # of the resource.  This can be refined later if needed.
            default_schema = {
                "apiVersion": res.get("apiVersion"),
                "kind": kind,
                # Observe everything under metadata and spec (and status if present)
                "metadata": {
                    # by default, watch name, namespace and any labels/annotations
                    "watch": ["name", "namespace", "labels", "annotations"]
                },
                "spec": {
                    "watch": True  # wildcard: observe any change under spec
                },
                # Optional status block – usually not monitored
                **({"status": {"watch": False}} if "status" in res else {})
            }
            observer_schemas[kind] = default_schema
        except Exception:
            # Skip any resource that causes problems – we don't want to
            # abort the whole generation process.
            continue
    # The function mutates the app object; nothing to return.

