    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        # Safely retrieve the manifest dict from the application
        manifest = getattr(app, "spec", None)
        if manifest is None:
            return
        manifest = getattr(manifest, "manifest", None) if hasattr(manifest, "manifest") else None
        if not isinstance(manifest, dict):
            return

        # Use a dedicated attribute to store the observer schemas. If it does not
        # exist, create an empty dictionary to hold the defaults.
        observer_schema = getattr(app, "observer_schema", None)
        if observer_schema is None:
            observer_schema = {}

        # Iterate over every resource defined in the manifest. For each one that
        # does not already have a custom observer schema, create a minimal
        # default schema. The exact shape of the schema is highly application
        # dependent; here we simply mimic the typical Krake representation
        # which expects a "spec" object that contains the fields to watch.
        for resource_name, resource_def in manifest.items():
            if resource_name in observer_schema:
                # Skip resources that already have a custom observer schema
                continue

            # Build a very simple placeholder observer schema.  If the
            # resource definition already contains a spec field, expose it;
            # otherwise, expose an empty dict.
            default_spec = {}
            if isinstance(resource_def, dict) and "spec" in resource_def:
                default_spec = resource_def.get("spec", {})
            observer_schema[resource_name] = {"spec": default_spec}

        # Persist the generated schemas back onto the application object.
        setattr(app, "observer_schema", observer_schema)
    except Exception:
        # Any exception (e.g., missing attributes) is silently ignored to
        # keep the method fail‑safe.
        pass

