def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not path:
        return False
    try:
        # Resolve to absolute path
        path = os.path.abspath(path)
        # Must be a directory
        if not os.path.isdir(path):
            return False
        # Basic OCFL structure checks: require a `.ocfl` directory and an `objects` directory
        ocfl_dir = os.path.join(path, '.ocfl')
        objects_dir = os.path.join(path, 'objects')
        if not os.path.isdir(ocfl_dir):
            return False
        if not os.path.isdir(objects_dir):
            return False
        return True
    except Exception:
        # Any exception during validation results in a False status
        return False

