    if extract_spec_version:
        type_val = inventory.get("type")
        allowed_versions = getattr(self, "allowed_spec_versions", ())
        if isinstance(type_val, str) and type_val in allowed_versions:
            spec_version = type_val
        else:
            spec_version = getattr(self, "spec_version", None)
    else:
        spec_version = getattr(self, "spec_version", None)
    if spec_version is None:
        raise ValueError("specification version could not be determined")
    # Store for later use
    self._spec_version = spec_version
    # Run main validation logic
    try:
        return self._run_validation(inventory, spec_version)
    except Exception as exc:
        # Wrap in a more descriptive exception
        raise ValueError(f"Inventory validation failed: {exc}") from exc

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Ensure inventory is a mapping
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dict")

        # Determine spec_version
        spec_version = getattr(self, "spec_version", None)
        if extract_spec_version:
            type_value = inventory.get("type")
            if isinstance(type_value, str):
                # Try to extract a simple version string (first run of digits)
                cleaned = type_value.strip()
                digits_start = None
                digits_end = None
                for i, ch in enumerate(cleaned):
                    if ch.isdigit():
                        digits_start = i
                        break
                if digits_start is not None:
                    # Find the end of the digits (or dot separators)
                    for j in range(digits_start, len(cleaned)):
                        if not (cleaned[j].isdigit() or cleaned[j] == "."):
                            digits_end = j
                            break
                    if digits_end is None:
                        digits_end = len(cleaned)
                    spec_version = cleaned[digits_start:digits_end]
        # Update spec_version on self
        setattr(self, "spec_version", spec_version)

        # Basic validation: required fields
        required = getattr(self, "required_fields", [])
        for f in required:
            if f not in inventory:
                raise ValueError(f"Missing required field '{f}' in inventory")

        # Validate field types if validators are provided
        field_validators = getattr(self, "field_validators", {})
        for field, validator in field_validators.items():
            if field in inventory:
                try:
                    validator(inventory[field], field)
                except Exception as exc:
                    raise ValueError(f"Invalid value for field '{field}': {exc}") from exc

        # Version‑specific validation hook
        if hasattr(self, "_validate_by_version"):
            self._validate_by_version(inventory, spec_version)

        # If all checks pass, return the inventory unchanged
        return inventory

    except Exception as e:
        # Wrap any exception in a generic validation error
        raise ValueError(f"Inventory validation failed: {e}") from e

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if inventory is None:
            raise ValueError("inventory cannot be None")
        if not isinstance(inventory, dict):
            raise TypeError(f"inventory must be a dict, got {type(inventory).__name__}")

        # Determine the specification version to use
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise AttributeError("A 'spec_version' attribute must be defined on the instance")

        if extract_spec_version:
            type_value = inventory.get("type")
            if isinstance(type_value, str):
                # Direct match to a supported version
                if type_value in getattr(self, "supported_versions", []):
                    spec_version = type_value
                else:
                    # Try to extract from a compound string, e.g. "type: v1"
                    parts = type_value.split(":")
                    if len(parts) == 2 and parts[1] in getattr(self, "supported_versions", []):
                        spec_version = parts[1]

        # Validate that we have a recognized spec_version
        if spec_version not in getattr(self, "supported_versions", []):
            raise ValueError(f"Unsupported spec_version: {spec_version!r}")

        # Basic presence checks for required fields (if defined)
        required_fields = getattr(self, "required_fields", {}).get(spec_version, [])
        for key in required_fields:
            if key not in inventory:
                raise ValueError(f"Missing required key '{key}' for spec_version {spec_version!r}")

        # Optional type checks for each field (if defined)
        field_types = getattr(self, "field_types", {}).get(spec_version, {})
        for key, value in inventory.items():
            expected_type = field_types.get(key)
            if expected_type and not isinstance(value, expected_type):
                raise TypeError(
                    f"Field '{key}' expected type {expected_type.__name__} "
                    f"but got {type(value).__name__}"
                )

        # If all checks pass, return True or the cleaned inventory
        return True

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")

    # Try to extract the spec version if requested
    if extract_spec_version:
        spec_type = None
        if isinstance(inventory, dict):
            spec_type = inventory.get('type')
        elif isinstance(inventory, list) and inventory:
            first = inventory[0]
            if isinstance(first, dict):
                spec_type = first.get('type')

        if spec_type and hasattr(self, 'allowed_spec_versions') and spec_type in self.allowed_spec_versions:
            # Apply the extracted version
            self.spec_version = spec_type

    # Assume inventory is a list of dicts or a dict containing an 'items' list
    if isinstance(inventory, dict):
        items = inventory.get('items', [])
    else:
        items = inventory

    if not isinstance(items, list):
        raise ValueError(f"Inventory items expected to be a list, got {type(items).__name__}")

    # Validate each individual item using a helper (if available)
    for idx, item in enumerate(items):
        try:
            if hasattr(self, '_validate_item'):
                self._validate_item(item, idx)
        except Exception as exc:
            raise ValueError(f"Invalid inventory item at index {idx}: {exc}") from exc

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Determine the set of digests that are expected by the manifest.
    if manifest_files is None:
        expected = set()
    else:
        if isinstance(manifest_files, dict):
            # In a mapping, the keys are assumed to be the digests.
            expected = set(manifest_files.keys())
        else:
            expected = set()
            for item in manifest_files:
                # Accept a dictionary with a 'digest' entry.
                if isinstance(item, dict) and 'digest' in item:
                    expected.add(item['digest'])
                # Accept a tuple/list where the digest is the second element.
                elif isinstance(item, (list, tuple)) and len(item) > 1:
                    expected.add(item[1])
                # Accept a raw digest string.
                elif isinstance(item, str):
                    expected.add(item)
    # Convert the provided digests_used into a set.
    try:
        used = set(digests_used if digests_used is not None else [])
    except TypeError:
        # digests_used was not iterable; treat it as a single digest value.
        used = {digests_used}
    # Check that every expected digest is present in the used set.
    missing = expected - used
    if missing:
        raise ValueError(f"Missing required digests: {', '.join(sorted(missing))}")
    # Optionally warn about digests that were used but not needed.
    unexpected = used - expected
    if unexpected:
        raise ValueError(f"Unexpected digests used but not required: {', '.join(sorted(unexpected))}")

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")

    if digests_used is None:
        digests_used = set()
    else:
        digests_used = set(digests_used)

    # Determine the set of digests required by the manifest.
    if isinstance(manifest_files, dict):
        digests_in_manifest = set(manifest_files.keys())
    else:
        try:
            digests_in_manifest = {item["digest"] for item in manifest_files}
        except (TypeError, KeyError):
            digests_in_manifest = set(manifest_files)

    missing = digests_in_manifest - digests_used
    if missing:
        raise ValueError(f"Missing digests present in manifest but not used: "
                         f"{', '.join(sorted(missing))}")

    unused = digests_used - digests_in_manifest
    if unused:
        # Unused digests are not an error but can be logged or ignored.
        pass

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalize the collection of used digests to a set for fast lookup
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used should be a collection (set, list, or tuple) of digests")
    used = set(digests_used)

    missing = []

    for entry in manifest_files:
        # Resolve the digest from either a dict key or an attribute
        try:
            if isinstance(entry, dict):
                digest = entry.get('digest')
                needed_flag = entry.get('needed', True)
            else:
                digest = getattr(entry, 'digest', None)
                # Default to True if 'needed' attribute is missing
                needed_flag = getattr(entry, 'needed', True)
        except AttributeError:
            # Skip entries that do not provide a digest or needed flag
            continue

        if digest is None:
            # Skip entries with no digest
            continue

        # If the entry is marked as needed but not present in the used set, remember it
        if needed_flag and digest not in used:
            missing.append((digest, entry))

    if missing:
        # Build a helpful error message
        details = ", ".join(f"{d} (entry: {e})" for d, e in missing)
        raise ValueError(f"Missing required digests: {details}")

def check_digests_present_and_used(self, manifest_files, digests_used):
        """
        Check all digests in manifest that are needed are present and used.
        """
        if manifest_files is None or digests_used is None:
            raise ValueError("Both manifest_files and digests_used must be provided")
        # Normalise inputs to sets
        expected = set()
        try:
            # assume manifest_files may be mapping of filename->digest
            for v in manifest_files.values():
                expected.add(v)
        except AttributeError:
            # fallback: treat manifest_files as iterable of digests
            expected.update(manifest_files)
        used = set(digests_used)
        missing = used - expected
        unused = expected - used
        errors = []
        if missing:
            errors.append(f"Missing digests used but not found in manifest: {', '.join(sorted(missing))}")
        if unused:
            errors.append(f"Unused digests present in manifest: {', '.join(sorted(unused))}")
        if errors:
            raise ValueError("; ".join(errors))
        return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.
    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if prior is None:
        raise ValueError("prior must be provided and not None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Version comparison (if a version attribute exists)
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is not None and prior_version is not None:
        try:
            # allow comparison of integers, tuples, strings, etc.
            if prior_version > self_version:
                raise ValueError(f"Prior version {prior_version} is newer than current version {self_version}")
        except TypeError:
            # Incomparable types – skip version check
            pass

    # Components to compare: adjust names as appropriate for the inventory
    components = ["species", "processes", "parameters"]
    for comp in components:
        curr_comp = getattr(self, comp, None)
        prior_comp = getattr(prior, comp, None)

        # Skip missing components
        if curr_comp is None or prior_comp is None:
            continue

        # Extract name sets from dicts or iterables
        if isinstance(curr_comp, dict):
            curr_names = set(curr_comp.keys())
        else:
            try:
                curr_names = {item.name for item in curr_comp}
            except AttributeError:
                curr_names = set(curr_comp)

        if isinstance(prior_comp, dict):
            prior_names = set(prior_comp.keys())
        else:
            try:
                prior_names = {item.name for item in prior_comp}
            except AttributeError:
                prior_names = set(prior_comp)

        # Ensure every current item exists in the prior inventory
        missing_names = curr_names - prior_names
        if missing_names:
            raise ValueError(
                f"Prior inventory is missing {comp} entries required by the current inventory: {missing_names}"
            )

    # If no checks raise exceptions, validation passes
    return

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency."""
    # Ensure prior is of the expected type
    if not isinstance(prior, InventoryValidator):
        raise TypeError(f"'prior' must be an instance of InventoryValidator, got {type(prior).__name__}")

    # Retrieve the version attributes; raise informative error if missing
    try:
        self_version = self.inventory_version
        prior_version = prior.inventory_version
    except AttributeError as exc:
        raise AttributeError("Both inventory objects must expose an 'inventory_version' attribute") from exc

    # Prior must be older than the current inventory
    if prior_version >= self_version:
        raise ValueError(f"Provided prior inventory has version {prior_version}, "
                         f"which is not older than the current inventory version {self_version}.")

    # Retrieve the actual inventory data structures (allowing for a few common naming conventions)
    try:
        self_inventory = getattr(self, "inventory", getattr(self, "data", {}))
        prior_inventory = getattr(prior, "inventory", getattr(prior, "data", {}))
    except Exception as exc:
        raise AttributeError("Unable to retrieve inventory data from either the current or prior inventory") from exc

    # Both inventories must be mappings; if not, raise an error
    if not isinstance(self_inventory, dict):
        raise TypeError(f"Current inventory data must be a dict, got {type(self_inventory).__name__}")
    if not isinstance(prior_inventory, dict):
        raise TypeError(f"Prior inventory data must be a dict, got {type(prior_inventory).__name__}")

    # Ensure every key required by the current inventory exists in the prior inventory
    missing_in_prior = [key for key in self_inventory if key not in prior_inventory]
    if missing_in_prior:
        raise ValueError(f"The prior inventory is missing required keys: {missing_in_prior}")

    # Optionally, verify that all existing keys in the prior match the current
    # We allow the prior to provide more keys, but those shared keys must be identical
    for key in set(self_inventory).intersection(prior_inventory):
        if self_inventory[key] != prior_inventory[key]:
            raise ValueError(f"Mismatch for key '{key}': current = {self_inventory[key]}, prior = {prior_inventory[key]}")

    # If we reach this point, the prior is considered a valid prior version
    return True

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        errors = []

        # Type check
        try:
            # Use the same class or a subclass
            if not isinstance(prior, type(self)):
                raise TypeError(f"Prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")
        except Exception as exc:
            errors.append(str(exc))

        # Basic attribute consistency checks
        for attr in ('inventory_name', 'version'):
            self_attr = getattr(self, attr, None)
            prior_attr = getattr(prior, attr, None)
            if self_attr is None or prior_attr is None:
                errors.append(f"Attribute '{attr}' missing from one of the inventories")
                continue
            if attr == 'version' and prior_attr >= self_attr:
                errors.append(f"Prior version ({prior_attr}) must be less than current version ({self_attr})")
            if attr != 'version' and self_attr != prior_attr:
                errors.append(f"Attribute '{attr}' differs: current='{self_attr}', prior='{prior_attr}'")

        # Compare inventory data if available
        try:
            self_data = getattr(self, 'inventory_data', {})
            prior_data = getattr(prior, 'inventory_data', {})
            if not isinstance(self_data, dict) or not isinstance(prior_data, dict):
                errors.append("Inventory data must be dict-like objects")
            else:
                # Every entry in the prior should exist in the current inventory unchanged
                for key, old_value in prior_data.items():
                    if key not in self_data:
                        errors.append(f"Key '{key}' from prior inventory missing in current inventory")
                    else:
                        curr_value = self_data[key]
                        if curr_value != old_value:
                            errors.append(f"Value mismatch for key '{key}': current='{curr_value}' vs prior='{old_value}'")
        except Exception as exc:
            errors.append(str(exc))

        if errors:
            raise ValueError("Inventory prior validation errors: " + "; ".join(errors))
        return None

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError(
            f"prior must be an InventoryValidator instance, got {type(prior)!r}"
        )

    # Basic set checks
    if set(self.species) != set(prior.species):
        raise ValueError(
            "Species set mismatch between current inventory and prior version.\n"
            f"Current: {sorted(self.species)}\nPrior: {sorted(prior.species)}"
        )

    if set(self.parameters) != set(prior.parameters):
        raise ValueError(
            "Parameter set mismatch between current inventory and prior version.\n"
            f"Current: {sorted(self.parameters)}\nPrior: {sorted(prior.parameters)}"
        )

    # Optional mapping consistency checks if available
    for attr in ("species_map", "parameter_map"):
        self_map = getattr(self, attr, None)
        prior_map = getattr(prior, attr, None)
        if self_map is not None or prior_map is not None:
            if self_map != prior_map:
                raise ValueError(
                    f"Mismatch in {attr} between current inventory and prior version.\n"
                    f"Current: {self_map}\nPrior: {prior_map}"
                )
    # If all checks pass, nothing is returned (indicating success).

def validate_as_prior_version(self, prior):
        """
        Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        if prior is None:
            raise ValueError("Prior inventory cannot be None")
        # species check
        if not hasattr(prior, "species") or not hasattr(self, "species"):
            raise TypeError("'prior' and 'self' must both expose a 'species' attribute")
        missing_species = set(prior.species) - set(self.species)
        if missing_species:
            raise ValueError(
                "Prior contains species not present in current inventory: "
                f"{sorted(missing_species)}"
            )
        # parameters check
        if not hasattr(prior, "parameters") or not hasattr(self, "parameters"):
            raise TypeError("'prior' and 'self' must both expose a 'parameters' attribute")
        missing_parameters = set(prior.parameters) - set(self.parameters)
        if missing_parameters:
            raise ValueError(
                "Prior contains parameters not present in current inventory: "
                f"{sorted(missing_parameters)}"
            )
        # stoichiometry matrix shape consistency
        if hasattr(prior, "stoichiometry_matrix") and hasattr(self, "stoichiometry_matrix"):
            ps = prior.stoichiometry_matrix
            ss = self.stoichiometry_matrix
            if ps.cols != ss.cols:
                raise ValueError(
                    f"Stoichiometry matrix column count mismatch (prior={ps.cols}, "
                    f"current={ss.cols})"
                )
            if ps.rows > ss.rows:
                raise ValueError(
                    f"Prior has more reactions ({ps.rows}) than current inventory ({ss.rows})"
                )
        # propensities matrix shape consistency
        if hasattr(prior, "propensities") and hasattr(self, "propensities"):
            pp = prior.propensities
            cp = self.propensities
            if pp.cols != cp.cols:
                raise ValueError(
                    f"Propensities matrix column count mismatch (prior={pp.cols}, "
                    f"current={cp.cols})"
                )
            if pp.rows > cp.rows:
                raise ValueError(
                    f"Prior has more propensity functions ({pp.rows}) than current inventory ({cp.rows})"
                )
        # If all checks pass, the prior is considered valid
        return

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to path data")

    if version not in inventory:
        # No data for this version; return empty map
        return {}

    ver_data = inventory[version]
    if not isinstance(ver_data, dict):
        # Unexpected format; cannot process
        return {}

    path_map = {}
    for logical_path, content in ver_data.items():
        try:
            if isinstance(content, (list, set, tuple)):
                content_set = set(content)
            elif isinstance(content, dict):
                # If content is a dict, take its keys as file identifiers
                content_set = set(content.keys())
            else:
                # Assume singular content identifier
                content_set = {content}
        except Exception:
            # Skip any problematic entries
            continue

        path_map[logical_path] = content_set

    return path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory cannot be None")
    if version is None:
        raise ValueError("version must not be None")
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    logical_path_map = {}

    for logical_path, data in inventory.items():
        # Skip entries that are not relevant
        if data is None:
            continue

        # Case 1: data is a mapping of version -> list of content files
        if isinstance(data, dict):
            if version in data:
                content_files = set(data[version])
                if content_files:
                    logical_path_map[logical_path] = content_files
            else:
                # If the version is not explicitly present, we may want to
                # inherit from the latest available version before the given
                # one.  Without concrete specifications we simply skip.
                continue

        # Case 2: data is a list of entries describing content files
        elif isinstance(data, list):
            accumulated = set()
            for entry in data:
                if isinstance(entry, dict):
                    # Expect keys: 'version', 'content_files' (list/tuple/set)
                    if entry.get('version') == version:
                        files = entry.get('content_files')
                        if files:
                            accumulated.update(files)
                    # In case of duplicate files from later versions, we
                    # intentionally keep them in the result if needed.
                elif isinstance(entry, str):
                    # A simple string entry is assumed to be a content file
                    # belonging to the current version.
                    accumulated.add(entry)
                else:
                    # Unsupported entry type; ignore or raise?
                    continue
            if accumulated:
                logical_path_map[logical_path] = accumulated

        # Case 3: data is a single string or other hashable content file
        else:
            logical_path_map[logical_path] = {data}

    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to parse a version string into a comparable key
    def _version_key(v):
        try:
            # Remove common version suffixes and split by dots
            parts = [p for p in v.replace('a', '').replace('b','').replace('rc','').split('.')]
            return tuple(int(p) for p in parts)
        except Exception:
            # Fallback to the raw string if parsing fails
            return v

    # Validate inventory contains the requested version
    if version not in inventory:
        # Return empty mapping if the version does not exist
        return {}

    # Gather logical paths and their content files for the requested version
    logical_map = {}
    current_state = inventory.get(version, {})
    for logical_path, content_file in current_state.items():
        logical_map.setdefault(logical_path, set()).add(content_file)

    # Include duplicate references from later versions
    try:
        current_key = _version_key(version)
    except Exception:
        current_key = version

    # Sort inventory keys to find later versions
    sorted_versions = sorted(inventory.keys(), key=_version_key)
    for v in sorted_versions:
        if v == version:
            continue
        # Determine if this version is later than the requested one
        try:
            if _version_key(v) <= current_key:
                continue
        except Exception:
            # If comparison fails, skip to avoid errors
            continue

        later_state = inventory.get(v, {})
        for logical_path, content_file in later_state.items():
            if logical_path in logical_map:
                logical_map[logical_path].add(content_file)

    return logical_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    import collections

    def _split_version(v):
        parts = []
        cur = ""
        for ch in v:
            if ch.isdigit():
                if cur and not cur.isdigit():
                    parts.append(cur)
                    cur = ""
                cur += ch
            else:
                if cur and cur.isdigit():
                    parts.append(cur)
                    cur = ""
                cur += ch
        if cur:
            parts.append(cur)
        return parts

    def _cmp(v1, v2):
        p1 = _split_version(v1)
        p2 = _split_version(v2)
        for a, b in zip(p1, p2):
            if a.isdigit() and b.isdigit():
                ia, ib = int(a), int(b)
                if ia != ib:
                    return ia - ib
            else:
                if a != b:
                    return 1 if a > b else -1
        return len(p1) - len(p2)

    if not isinstance(inventory, collections.abc.Mapping):
        raise TypeError("inventory must be a mapping (e.g., dict)")
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    result = {}
    for logical_path, ver_map in inventory.items():
        if not isinstance(ver_map, collections.abc.Mapping):
            continue
        files = set()
        for ver, files_set in ver_map.items():
            if not isinstance(files_set, collections.abc.Iterable):
                continue
            try:
                if _cmp(ver, version) >= 0:
                    files.update(files_set)
            except Exception:
                # If the version cannot be compared, skip any comparison
                pass
        result[logical_path] = files
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for a specific version.

    Parameters
    ----------
    inventory : dict
        Mapping of logical_path to a list of entries. Each entry is expected
        to be a mapping containing at least ``version`` and ``content_file``.
    version : str or object
        The version to build the map for. Entries with a matching ``version``
        are included. If ``inventory`` is not a dictionary, an empty mapping
        is returned.

    Returns
    -------
    dict
        A mapping of logical_path -> set of content_file paths that belong to
        the requested version.
    """
    if not isinstance(inventory, dict):
        # If the inventory is not a dictionary we do not know how to
        # interpret it, so return an empty mapping rather than raising.
        return {}
    path_map = {}
    for logical_path, entries in inventory.items():
        try:
            files = set()
            if isinstance(entries, (list, tuple)):
                for entry in entries:
                    if not isinstance(entry, dict):
                        continue
                    if entry.get("version") == version:
                        content_file = entry.get("content_file")
                        if content_file:
                            files.add(content_file)
            else:
                # If entries is a single dict mapping version to list of files
                if isinstance(entries, dict):
                    for ver_key, files_list in entries.items():
                        if ver_key == version:
                            for f in files_list:
                                files.add(f)
            if files:
                path_map[logical_path] = files
        except Exception:
            # Skip problematic entries to avoid crashing the entire process.
            continue
    return path_map

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("The fixity block must be a dictionary")

        # The block is expected to contain a 'files' entry mapping file names to
        # dictionaries of hash algorithms and hex digests.
        if 'files' not in fixity:
            raise ValueError("The fixity block must contain a 'files' key")

        files_block = fixity['files']
        if not isinstance(files_block, dict):
            raise ValueError("The 'files' entry must be a dictionary")

        # Ensure all referenced files are present in the manifest.
        for fname, sigs in files_block.items():
            if fname not in manifest_files:
                raise ValueError(f"Fixity references unknown file {fname!r}")

            if not isinstance(sigs, dict):
                raise ValueError(f"The signatures for file {fname!r} must be a dictionary")

            for algo, digest in sigs.items():
                if algo not in ('md5', 'sha1', 'sha256', 'sha512'):
                    raise ValueError(
                        f"Unsupported hash algorithm {algo!r} for file {fname!r}"
                    )
                if not isinstance(digest, str):
                    raise ValueError(
                        f"The digest value for {algo!r} in file {fname!r} must be a string"
                    )
                if not all(c in '0123456789abcdefABCDEF' for c in digest):
                    raise ValueError(
                        f"Digest for {algo!r} in file {fname!r} must be hexadecimal"
                    )

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.

    :param dict fixity: The fixity block to validate.
    :param iterable manifest_files: Collection of file paths expected in the archive.
    :raises ValueError: If the structure is invalid or a referenced file is missing.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dict, got %r" % type(fixity).__name__)

    # Required keys in the fixity block
    required_keys = {'file'}
    missing = required_keys.difference(fixity.keys())
    if missing:
        raise ValueError("Missing required key(s) in fixity block: %s" % ', '.join(missing))

    # Ensure that no key is not a string
    for key in fixity:
        if not isinstance(key, str):
            raise ValueError("All keys in fixity block must be strings, got key of type %r" % type(key).__name__)

    # Extract the file references; allow either a single string or a list/tuple
    files = fixity['file']
    if isinstance(files, (list, tuple)):
        file_list = list(files)
    else:
        file_list = [files]

    # Validate each referenced file
    for f in file_list:
        if not isinstance(f, str) or not f:
            raise ValueError("File reference in fixity block must be a non-empty string, got %r" % f)
        if f not in manifest_files:
            raise ValueError("File '%s' referenced in fixity block is not present in the manifest" % f)

    # Optional: validate checksum algorithm and value if present
    if 'algorithm' in fixity and not isinstance(fixity['algorithm'], str):
        raise ValueError("Fixity algorithm must be a string, got %r" % type(fixity['algorithm']).__name__)

    if 'checksum' in fixity and not isinstance(fixity['checksum'], str):
        raise ValueError("Fixity checksum must be a string, got %r" % type(fixity['checksum']).__name__)

    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        # Common expected keys in a fixity block
        required_keys = {'algorithm', 'files', 'paths'}
        present_keys = set(fixity.keys())

        # Check for an algorithm definition
        if 'algorithm' not in present_keys:
            raise ValueError("Fixity block must contain an 'algorithm' entry")
        if not isinstance(fixity['algorithm'], str):
            raise ValueError("'algorithm' must be a string")

        # Determine which key contains the file references
        file_key = None
        for k in ('files', 'paths'):
            if k in present_keys:
                file_key = k
                break

        if file_key is None:
            raise ValueError("Fixity block must contain at least one of 'files' or 'paths' keys")

        # Normalize the manifest files list to a set for fast lookup
        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError("manifest_files must be a list, tuple, or set")
        manifest_set = set(manifest_files)

        # Extract file references from the fixity block
        file_refs = fixity[file_key]
        if isinstance(file_refs, dict):
            # Keys should be file paths, values are checksums
            referenced_files = file_refs.keys()
        elif isinstance(file_refs, list):
            referenced_files = file_refs
        else:
            raise ValueError(f"'{file_key}' must be a list or dict of file references")

        # Validate each referenced file
        for f in referenced_files:
            if not isinstance(f, str):
                raise ValueError(f"File reference '{f}' is not a string")
            if f not in manifest_set:
                raise ValueError(f"File '{f}' referenced in fixity block is not present in the manifest")

        # Optionally, check that there are no extraneous keys beyond the expected ones
        unexpected_keys = present_keys - required_keys
        if unexpected_keys:
            # This is a warning; you might choose to ignore or raise an error
            pass  # Do nothing, just allow for extensibility

        return True  # Validation succeeded. (Return value can be omitted if not needed)

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if not isinstance(fixity, dict):
        raise ValueError(f"Fixity block must be a dict, got {type(fixity).__name__}")
    # Required 'files' key
    files_block = fixity.get('files')
    if files_block is None:
