    return None

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # The fixity block must be a dictionary
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")
        # only known keys are allowed in the block
        allowed_keys = {"data", "algorithm"}
        unexpected_keys = set(fixity) - allowed_keys
        if unexpected_keys:
            raise ValueError(
                f"Invalid keys in fixity block: {', '.join(sorted(unexpected_keys))}"
            )
        # The mandatory 'data' key must be present
        if "data" not in fixity:
            raise ValueError("Fixity block missing required 'data' key")
        data = fixity["data"]
        if not isinstance(data, list):
            raise ValueError("'data' in fixity block must be a list")
        # Normalize the list of manifest files
        if manifest_files is None:
            manifest_files_set = set()
        else:
            manifest_files_set = set(manifest_files)
        # Validate each entry of the fixity data
        for idx, entry in enumerate(data):
            if not isinstance(entry, dict):
                raise ValueError(
                    f"Entry {idx} in fixity data is not a dictionary"
                )
            # Each entry must have 'file' and 'hash' keys
            for key in ("file", "hash"):
                if key not in entry:
                    raise ValueError(
                        f"Entry {idx} missing required key '{key}'"
                    )
            file_name = entry["file"]
            if file_name not in manifest_files_set:
                raise ValueError(
                    f"Fixity references unknown file '{file_name}' not in manifest"
                )
            if not isinstance(entry["hash"], str):
                raise ValueError(
                    f"Hash for file '{file_name}' must be a string"
                )
        # Optional: validate the algorithm field if present
        if "algorithm" in fixity and not isinstance(fixity["algorithm"], str):
            raise ValueError("'algorithm' must be a string")
        return True

def files_list(path):
    """
    Return the files in `path`.

    If `path` is a file, return a single-element list containing the
    absolute path. If `path` is a directory, return a sorted list of
    absolute paths to the regular files contained directly in that
    directory (non-recursive). If `path` does not exist, raise
    FileNotFoundError.
    """
    try:
        # Resolve to absolute path for consistency
        abs_path = os.path.abspath(path)
    except Exception as e:
        raise FileNotFoundError(f"Cannot resolve path '{path}': {e}")

    if not os.path.exists(abs_path):
        raise FileNotFoundError(abs_path)

    if os.path.isfile(abs_path):
        return [abs_path]

    if os.path.isdir(abs_path):
        try:
            files = []
            for entry in os.listdir(abs_path):
                full_entry = os.path.join(abs_path, entry)
                if os.path.isfile(full_entry):
                    files.append(full_entry)
            return sorted(files)
        except Exception as e:
            # If directory listing fails, raise a generic OSError
            raise OSError(f"Failed to list directory '{abs_path}': {e}")

    # In case path exists but is neither a file nor a directory
    raise OSError(f"Unsupported path type: '{abs_path}'")

