def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from the XML basename to a list of file paths that share that basename.
    """
    import os
    from collections import defaultdict

    if not isinstance(folder, str):
        raise TypeError(f"Expected a string path, got {type(folder)!r}")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder does not exist: {folder}")

    # First pass: collect all XML basenames
    xml_basenames = set()
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                if filename.lower().endswith('.xml'):
                    basename = os.path.splitext(filename)[0]
                    xml_basenames.add(basename)
    except Exception as exc:
        raise RuntimeError(f"Error while scanning for XML files in {folder}") from exc

    # Second pass: group all files that belong to those basenames
    package_files = defaultdict(list)
    try:
        for root, _, files in os.walk(folder):
            for filename in files:
                basename, _ = os.path.splitext(filename)
                if basename in xml_basenames:
                    package_files[basename].append(os.path.join(root, filename))
    except Exception as exc:
        raise RuntimeError(f"Error while grouping files in {folder}") from exc

    # Convert defaultdict to plain dict
    return dict(package_files)

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        return {}

    # Collect files grouped by their base name (without extension)
    base_dict = defaultdict(list)
    try:
        for root, _, files in os.walk(folder):
            for fname in files:
                # Skip hidden files
                if fname.startswith('.'):
                    continue
                full_path = os.path.join(root, fname)
                base_name, ext = os.path.splitext(fname)
                base_dict[base_name].append(full_path)
    except OSError:
        return {}

    # Filter to keep only groups that contain an XML file (our package definition)
    filtered = {k: v for k, v in base_dict.items() if any(f.lower().endswith('.xml') for f in v)}

    return filtered

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo para o arquivo

    Returns
    -------
    dict
        dicionário contendo o tipo identificado (`asset` ou `rendition`)
        e o caminho absoluto do arquivo analisado.
    """
    import os
    import xml.etree.ElementTree as ET

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Arquivo não encontrado: {file_path}")

    # 1. Tentar inferir a partir do nome do arquivo
    filename = os.path.basename(file_path)
    lname = filename.lower()
    if 'asset' in lname:
        return {"type": "asset", "path": file_path}
    if 'rendition' in lname:
        return {"type": "rendition", "path": file_path}

    # 2. Caso contrário, analisar o conteúdo XML
    try:
        tree = ET.parse(file_path)
        root = tree.getroot()
        tag = root.tag.lower()
        if tag == 'asset':
            return {"type": "asset", "path": file_path}
        if tag == 'rendition':
            return {"type": "rendition", "path": file_path}
        # Procurar em todos os nós
        for elem in root.iter():
            etag = elem.tag.lower()
            if etag == 'asset':
                return {"type": "asset", "path": file_path}
            if etag == 'rendition':
                return {"type": "rendition", "path": file_path}
    except ET.ParseError:
        # Se não for XML ou falhar o parse, iremos checar outros indicadores
        pass
    except Exception as e:
        raise RuntimeError(f"Erro ao analisar o arquivo {file_path}: {e}")

    # 3. Se nenhum critério for satisfeito, levantar exceção
    raise ValueError(f"Tipo de pacotice não identificado para {file_path}")

def add_asset(self, basename, file_path):
    """
    Add an asset mapping for the given basename to the specified file path.
    Returns a dictionary mapping various extensions to the file path.
    """
    # Validate inputs
    if not isinstance(basename, str) or not basename.strip():
        raise ValueError("basename must be a non-empty string")
    if not isinstance(file_path, str):
        raise ValueError("file_path must be a string")
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    # Build mapping for common image extensions
    mapping = {}
    for ext in ('.tiff', '.jpg', '.png'):
        key = f"{basename}{ext}"
        mapping[key] = file_path
    return mapping

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os
    data_by_basename = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for info in z.infolist():
                if info.is_dir():
                    continue
                # read the file content
                try:
                    content = z.read(info.filename)
                except Exception:
                    continue
                # Determine basename from XML file if exists
                # Use the part of the filename before the last extension
                base_name = os.path.splitext(os.path.basename(info.filename))[0]
                # Only consider entries that have an XML counterpart
                # If the current entry is xml, ensure it is the key base
                if info.filename.lower().endswith('.xml'):
                    key = base_name
                else:
                    # Check if an xml exists with this base in the same directory
                    xml_path = os.path.join(os.path.dirname(info.filename), base_name + '.xml')
                    try:
                        # If xml exists inside the zip, we can use base as key
                        z.getinfo(xml_path)
                        key = base_name
                    except KeyError:
                        # Skip files that do not have an xml counterpart
                        continue
                group = data_by_basename.setdefault(key, {})
                group[info.filename] = content
    except FileNotFoundError:
        return {}
    except zipfile.BadZipFile:
        return {}
    except Exception:
        return {}
    return data_by_basename

