    if not isinstance(content, str):
        raise TypeError("Expected a string for content, got %s" % type(content).__name__)
    try:
        import re
        # Replace any attribute starting with w: followed by a name and a double-quoted value
        # e.g., w:st="value" -> w-st="value"
        pattern = re.compile(r'\bw:([a-zA-Z0-9_:-]+)="')
