def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    try:
        if hasattr(issue, 'text'):
            content = issue.text
        else:
            content = str(issue)
    except Exception:
        return (None, None)

    if not content:
        return (None, None)

    # Normalize text
    text = content.strip().lower()
    # remove surrounding arxiv style markers if any
    text = text.replace('(','').replace(')','').replace('.','')

    # Extract the main number or range
    number_match = re.search(r'\d+(?:-\d+)?', text)
    number = number_match.group() if number_match else None

    # Extract supplemental part after keywords
    suppl_match = re.search(
        r'(?:suppl|sup|spe|supp|supl)\.?[\s-]*?(\d+(?:-\d+)?)',
        text,
        flags=re.I
    )
    suppl = suppl_match.group(1) if suppl_match else None

    return (number, suppl)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    # Validate indentation level
    try:
        indent = int(indent)
        if indent < 0:
            indent = 0
    except Exception:
        indent = 0
    # Header for debugging, if requested
    header = ''
    if debug:
        header = f"{self.__class__.__name__} at {hex(id(self))}"
    # Attempt pretty printing
    try:
        if isinstance(self, (dict, list, tuple)):
            import json
            # Use JSON serialization for common containers
            pretty_str = json.dumps(self, indent=indent, default=str, sort_keys=True)
        else:
            import pprint
            # Fallback to pprint for arbitrary objects
            pretty_str = pprint.pformat(self, indent=indent)
    except Exception:
        # Fallback to simple str representation
        pretty_str = str(self)
    # Combine header and body
    if header:
        return f"{header}\n{pretty_str}"
    return pretty_str

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.

    Parameters
    ----------
    indent : int, optional
        Number of spaces to prepend to the representation. Defaults to 0.
    debug : bool, optional
        If True, include a pretty‑printed view of the object's __dict__.

    Returns
    -------
    str
        The formatted representation.
    """
    try:
        indent_level = int(indent)
        if indent_level < 0:
            raise ValueError
    except Exception:
        return "Invalid indent value"

    prefix = ' ' * indent_level

    if debug:
        try:
            from pprint import pformat
            try:
                data = vars(self)
            except Exception:
                data = {"repr": repr(self)}
            return prefix + pformat(data, indent=4)
        except Exception:
            # Fall back to normal representation if pprint fails
            pass

    try:
        return prefix + repr(self)
    except Exception:
        return prefix + str(self)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        import pprint
        if debug:
            try:
                attrs = {k: repr(v) for k, v in self.__dict__.items() if not k.startswith('_')}
            except Exception:
                attrs = {}
            return f"<{self.__class__.__name__} {attrs}>"
        return pprint.pformat(self, width=78, indent=indent, compact=False)
    except Exception as exc:
        return f"<error pretty: {exc}>"

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def is_same_expr(a, b):
        """Check structural equality of two expressions."""
        return a == b

    def simplify_expr(expr):
        """Recursively simplify an expression using absorption laws."""
        if isinstance(expr, tuple):
            op = expr[0]
            if op == 'NOT':
                # Simplify inner expression
                inner = simplify_expr(expr[1])
                return ('NOT', inner)
            if op in ('AND', 'OR'):
                left = simplify_expr(expr[1])
                right = simplify_expr(expr[2])

                # Apply absorption
                # A & (A | B) -> A
                if op == 'AND' and isinstance(right, tuple) and right[0] == 'OR':
                    if is_same_expr(left, right[1]) or is_same_expr(left, right[2]):
                        return left
                # A | (A & B) -> A
                if op == 'OR' and isinstance(right, tuple) and right[0] == 'AND':
                    if is_same_expr(left, right[1]) or is_same_expr(left, right[2]):
                        return left

                # Negative absorption
                # A & (~A | B) -> A & B
                if op == 'AND' and isinstance(right, tuple) and right[0] == 'OR':
                    not_left = ('NOT', left)
                    # Check if either branch is ~A
                    if is_same_expr(right[1], not_left):
                        # A & ( ~A | B ) => A & B
                        return ('AND', left, right[2]) if is_same_expr(right[1], not_left) else ('AND', left, right[1])
                    if is_same_expr(right[2], not_left):
                        return ('AND', left, right[1])

                # A | (~A & B) -> A | B
                if op == 'OR' and isinstance(right, tuple) and right[0] == 'AND':
                    not_left = ('NOT', left)
                    if is_same_expr(right[1], not_left):
                        return ('OR', left, right[2])
                    if is_same_expr(right[2], not_left):
                        return ('OR', left, right[1])

                # If no rule applied, return simplified subtree
                return (op, left, right)
        # For atomic expressions (strings, numbers, etc.) just return
        return expr

    # Simplify each expression in the input list
    simplified_args = [simplify_expr(arg) for arg in args]
    return simplified_args

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    def decorator(func):
        if not callable(func):
            raise TypeError("Handler must be callable")
        if not hasattr(self, "_handlers"):
            self._handlers = {}
        self._handlers.setdefault(hook, []).append(func)
        return func
    return decorator

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    if hook is None:
        raise TypeError("hook must be provided")
    # Ensure registry dict exists
    if not hasattr(self, "_registry"):
        self._registry = {}

    def decorator(fn):
        if not callable(fn):
            raise ValueError("decorated object must be callable")
        self._registry.setdefault(hook, []).append(fn)
        return fn

    return decorator

def base_config(user, etcd_host="localhost", etcd_port=2379):
    """Creates a configuration with some simple parameters, which have a default value
    that can be set.

    Args:
