    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    PY3 = sys.version_info[0] >= 3

    try:
        unicode_type
    except NameError:
        unicode_type = str

    def inner(*args, **kwargs):
        value = namefunc(*args, **kwargs)
        if PY3:
            return value
        # Python 2 branch: ensure a bytestring (str) result
        if isinstance(value, unicode_type):
            try:
