def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        from pathlib import Path

        # Locate version.py in the same directory as this module
        current_dir = Path(__file__).resolve().parent
        version_file = current_dir / "version.py"

        if not version_file.exists():
            return "unknown"

        namespace = {}
        with open(version_file, "r", encoding="utf-8") as f:
            exec(f.read(), namespace)

        # Look for common version variables
        for key in ("__version__", "VERSION", "version"):
            if key in namespace:
                return str(namespace[key]).strip()

        return "unknown"
    except Exception:
        return "unknown"

