    try:
        import os
        # Attempt to read a version defined in a local version.py
        version_file = os.path.join(os.path.dirname(__file__), 'version.py')
        with open(version_file, 'r') as f:
            for line in f:
                if '=' in line:
                    left, right = line.split('=', 1)
                    if '__version__' in left or 'VERSION' in left:
                        # Strip whitespace and surrounding quotes
                        return right.strip().strip('"\'')
        # Fallback to an environment variable if present
        return os.environ.get('PROJECT_VERSION', 'unknown')
    except Exception:
        return 'unknown'

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
        # Attempt to read the version from an environment variable first
        import os
        env_ver = os.getenv("MY_PACKAGE_VERSION")
        if env_ver:
            return env_ver.strip()

        # Try to get the version from the distribution metadata
        try:
            from importlib.metadata import version, PackageNotFoundError  # Python 3.8+
        except ImportError:
            try:
                from importlib_metadata import version, PackageNotFoundError  # type: ignore
            except ImportError:
                raise  # re-raise to be caught by outer except

        return version("my_package")

    except Exception:
        # If any method fails, return a sensible default
        return "unknown"

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if style is None:
        raise ValueError('style must be provided')
    if not isinstance(style, str):
        raise TypeError('style must be a string')
    style = style.lower()

    # Normalize pieces into a list of (name, version) tuples
    if pieces is None:
        items = []
    elif isinstance(pieces, dict):
        items = list(pieces.items())
    else:
        try:
            items = [tuple(p) for p in pieces]
        except Exception as exc:
            raise TypeError('pieces must be a dict or an iterable of pairs') from exc

    # Rendering logic for supported styles
    if style == 'text':
        return '\n'.join(f'{name}: {version}' for name, version in items)
    elif style == 'json':
        import json
        return json.dumps(
            [{'name': name, 'version': version} for name, version in items],
            indent=2
        )
    elif style == 'yaml':
        try:
            import yaml
        except ImportError as exc:
            raise ImportError('PyYAML is required for yaml style rendering') from exc
        return yaml.safe_dump(
            [{'name': name, 'version': version} for name, version in items],
            sort_keys=False
        )
    elif style == 'xml':
        parts = ['<?xml version="1.0" encoding="UTF-8"?>', '<versions>']
        for name, version in items:
            parts.append(f'  <component name="{name}">')
            parts.append(f'    <version>{version}</version>')
            parts.append('  </component>')
        parts.append('</versions>')
        return '\n'.join(parts)
    else:
        raise ValueError(f'Unsupported style: {style}')

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate that pieces is iterable
    try:
        iter(pieces)
    except TypeError:
        raise TypeError('pieces must be an iterable of strings or objects convertible to strings')

    # Convert all pieces to string
    texts = [str(p) for p in pieces]

    # Helper to escape HTML special characters
    def _escape(text):
        # Simple manual escaping to avoid external imports
        return (text.replace("&", "&amp;")
                     .replace("<", "&lt;")
                     .replace(">", "&gt;")
                     .replace('"', "&quot;")
                     .replace("'", "&#x27;"))

    # Render according to the requested style
    if style == 'plain':
        return '\n'.join(texts)
    elif style == 'html':
        return '\n'.join(f"<p>{_escape(t)}</p>" for t in texts)
    elif style == 'markdown':
        # Simple markdown: each piece as a paragraph, headings preserved
        return '\n\n'.join(t for t in texts)
    elif style == 'json':
        import json
        return json.dumps(texts)
    else:
        raise ValueError(f'Unsupported style: {style}')

