def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Ensure pieces is iterable
    try:
        pieces_iter = list(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable of version components")

    # Convert all pieces to clean strings, ignoring None
    parts = [str(p) for p in pieces_iter if p is not None]
    if not parts:
        return ""

    # Normalise style to lowercase for comparison
    style = style.lower() if isinstance(style, str) else ""

    # Define rendering logic
    if style == "full" or style == "":
        return ".".join(parts)
    elif style == "short":
        return parts[0]
    elif style == "major":
        return parts[0]
    elif style == "minor":
        return ".".join(parts[:2]) if len(parts) >= 2 else ".".join(parts)
    elif style == "patch":
        return ".".join(parts[:3]) if len(parts) >= 3 else ".".join(parts)
    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles are: full, short, major, minor, patch.")

