    if style == "string":
        return ".".join(str(p) for p in seq)
    elif style == "tuple":
        return tuple(seq)
    elif style == "list":
        return list(seq)
    elif style == "dict":
        return {i: p for i, p in enumerate(seq)}
    else:
        raise ValueError(f"Unrecognized style: {style}")

