            raise TypeError("args must be a string or iterable of strings") from exc

    full_cmd = cmd_list + args_list

    if verbose:
        print("Running:", " ".join(str(part) for part in full_cmd))

    # Determine stderr handling.
    stderr_mode = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
