def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Initialize counters
    num_objects = 0
    good_objects = 0
    warnings = []

    # Obtain the root(s) of the hierarchy
    roots = getattr(self, "storage_root", None)
    if roots is None:
        return 0, 0
    if isinstance(roots, (list, tuple)):
        stack = list(roots)
    else:
        stack = [roots]

    while stack:
        obj = stack.pop()
        num_objects += 1
        ok = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                # Some objects expose a .validate() method that returns bool
                res = getattr(obj, "validate", lambda: True)()
                if not res:
                    ok = False
                    if show_warnings:
                        warnings.append(f"Validation failed for object {obj!r}")
            except Exception as e:
                ok = False
                if show_warnings:
                    warnings.append(f"Validation exception for {obj!r}: {e}")

        # Check digests if requested
        if check_digests:
            try:
                current = getattr(obj, "digest", None) or getattr(obj, "get_digest", lambda: None)()
                expected = getattr(obj, "expected_digest", None)
                if expected is None:
                    # If there is no expected digest stored, assume current is fine
                    expected = current
                if current != expected:
                    ok = False
                    if show_warnings:
                        warnings.append(f"Digest mismatch for object {obj!r}")
            except Exception as e:
                ok = False
                if show_warnings:
                    warnings.append(f"Digest check exception for {obj!r}: {e}")

        if ok:
            good_objects += 1

        # Enqueue child objects for traversal
        children = None
        try:
            children = getattr(obj, "children", None)
        except Exception:
            pass
        if isinstance(children, (list, tuple)):
            stack.extend(children)
        else:
            # Try a potential method
            try:
                children_method = getattr(obj, "get_children", None)
                if callable(children_method):
                    children = children_method()
                    if isinstance(children, (list, tuple)):
                        stack.extend(children)
            except Exception:
                pass

    # Emit warnings if requested
    if show_warnings and warnings:
        for w in warnings:
            print(w)

    return num_objects, good_objects

