    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    def _flatten(start_obj):
        """Recursively yield start_obj and all of its descendants."""
        yield start_obj
        # Common patterns: a 'children' attribute or a 'get_children()' method
        children = None
        if hasattr(start_obj, 'children') and start_obj.children is not None:
            children = start_obj.children
        elif hasattr(start_obj, 'get_children') and callable(start_obj.get_children):
            try:
                children = start_obj.get_children()
            except Exception:
                children = None
        if isinstance(children, (list, tuple)):
            for child in children:
                for sub in _flatten(child):
                    yield sub
        elif isinstance(children, (set,)):
            for child in children:
                for sub in _flatten(child):
                    yield sub
        # If children is a dict-like structure
        elif isinstance(children, dict):
            for child in children.values():
                for sub in _flatten(child):
                    yield sub

    num_objects = 0
    good_objects = 0

    # Determine root objects: attempt to use 'root' attribute or method
    roots = None
    if hasattr(self, 'root') and self.root is not None:
        roots = [self.root]
    elif hasattr(self, 'get_root') and callable(self.get_root):
        try:
            roots = [self.get_root()]
        except Exception:
            roots = None

    if roots is None:
        # No explicit root; attempt to use all attributes that look like objects
        roots = []
        for attr_name in dir(self):
            if attr_name.startswith('_'):
                continue
            attr = getattr(self, attr_name)
            # Heuristic: if attribute has a validate() method, treat as object
            if hasattr(attr, 'validate') or hasattr(attr, 'check_digest'):
                roots.append(attr)

    for root in roots:
        for obj in _flatten(root):
            num_objects += 1
            valid = True
            # Validate the object itself if requested
            if validate_objects:
                try:
                    if hasattr(obj, 'validate') and callable(obj.validate):
                        obj.validate()
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Validation error for {getattr(obj, 'id', obj)}: {e}")
            # Check digests if requested
            if valid and check_digests:
                try:
                    if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                        if not obj.check_digest():
                            valid = False
                            if show_warnings:
                                print(f"Digest mismatch for {getattr(obj, 'id', obj)}")
                except Exception as e:
                    valid = False
                    if show_warnings:
                        print(f"Digest check error for {getattr(obj, 'id', obj)}: {e}")
            if valid:
                good_objects += 1

    return num_objects, good_objects

