def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os, json

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Determine base directory and inventory file name
    base_dir = getattr(self, "base_dir", ".")
    inv_file = getattr(self, "inventory_filename", "inventory.json")

    # Load root inventory (must exist)
    root_inv_path = os.path.join(base_dir, inv_file)
    try:
        with open(root_inv_path, "r", encoding="utf-8") as f:
            root_inv = json.load(f)
    except FileNotFoundError as exc:
        raise FileNotFoundError(f"Root inventory file not found: {root_inv_path}") from exc
    except Exception as exc:
        raise ValueError(f"Cannot parse root inventory {root_inv_path!r}: {exc}") from exc

    if not isinstance(root_inv, dict):
        raise ValueError(f"Root inventory {root_inv_path!r} must be a mapping (dict)")

    # Store differences for later validation
    self._different_digests = {}
    seen_files = set(root_inv.keys())

    for idx, vdir in enumerate(version_dirs, start=1):
        inv_path = os.path.join(base_dir, vdir, inv_file)
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Inventory file not found for version directory {vdir!r}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Cannot read inventory {inv_path!r}: {exc}") from exc

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory {inv_path!r} must be a dict mapping filenames to digests")

        # Inventory must contain all previously seen files
        missing = seen_files - inv.keys()
        if missing:
            raise ValueError(f"Inventory for {vdir!r} is missing files: {', '.join(sorted(missing))}")

        # Record any digest differences from the root inventory
        for fname, digest in inv.items():
            root_digest = root_inv.get(fname)
            if root_digest is not None and digest != root_digest:
                self._different_digests.setdefault(fname, []).append(digest)

        # Update seen files for the next iteration
        seen_files.update(inv.keys())

    return self._different_digests

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic validation of input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError('version_dirs must be a list or tuple of directory names')
    for vd in version_dirs:
        if not isinstance(vd, str):
            raise TypeError('All items in version_dirs must be strings')

    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise AttributeError('root_inventory must be defined as a dictionary before validation')

    # Prepare container for digests that differ from the root
    self.differing_digests = getattr(self, 'differing_digests', {})

    cumulative_inventory = {}
    for vd in version_dirs:
        inv_path = os.path.join(vd, 'inventory.json')
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f'Inventory file not found in version directory {vd!r}')

        try:
            with open(inv_path, 'r', encoding='utf-8') as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f'Failed to load inventory from {inv_path!r}: {exc}')

        if not isinstance(inv, dict):
            raise ValueError(f'Inventory in {inv_path!r} must be a mapping of file to digest')

        # Verify each entry against the root inventory
        for path, digest in inv.items():
            if path not in self.root_inventory:
                raise ValueError(f'Path {path!r} in {vd!r} not present in root inventory')
            if digest != self.root_inventory[path]:
                self.differing_digests.setdefault(path, []).append((vd, digest))

        # Update cumulative inventory for subsequent checks
        cumulative_inventory.update(inv)

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os, json
    # Validate input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError('version_dirs must be a sequence of directory names')
    if not version_dirs:
        return
    # Root inventory must exist on the instance
    try:
        root_inventory = self.root_inventory
    except AttributeError:
        raise AttributeError("Instance must have a 'root_inventory' attribute")
    if not isinstance(root_inventory, dict):
        raise TypeError("'root_inventory' must be a dict mapping keys to digests")

    # Record of digests that differ from the root inventory
    differing = {}
    # Keep a cumulative inventory that should be present at each step
    cumulative = root_inventory.copy()

    # Process each version directory in order
    for idx, vdir in enumerate(version_dirs, start=1):
        # Inventory file name is assumed to be 'inventory' inside the version dir
        inv_path = os.path.join(vdir, "inventory")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"No inventory file found in version directory {vdir!r}")

        # Load inventory data; it should be a JSON mapping of key to digest
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv_data = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from {inv_path!r}: {exc}") from exc

        if not isinstance(inv_data, dict):
            raise ValueError(f"Inventory at {inv_path!r} must be a mapping of keys to digests")

        # Verify that the inventory contains all root items up to this point
        missing = [k for k in cumulative if k not in inv_data or inv_data[k] != cumulative[k]]
        if missing:
            raise ValueError(f"Inventory in {vdir!r} is missing or mismatched keys: {missing}")

        # Record any differences between this inventory and the root inventory
        for key, root_digest in root_inventory.items():
            if key not in inv_data:
                continue  # missing key handled above
            if inv_data[key] != root_digest:
                differing.setdefault(key, []).append((root_digest, inv_data[key]))

        # Store the inventory for this version
        if not hasattr(self, "inventories"):
            self.inventories = {}
        self.inventories[vdir] = inv_data

        # Update the cumulative inventory for the next iteration
        cumulative = inv_data

    # Save the record of differing digests for later validation checks
    self.different_digests = differing
    return None

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # Ensure path exists
    if not os.path.exists(path):
        return "not found"
    # If it is a file, return 'file'
    if os.path.isfile(path):
        return "file"
    # If it is a directory, inspect contents
    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except Exception as exc:
            return f"access error: {exc}"
        # Directly look for Namaste files in this directory
        for name in entries:
            full = os.path.join(path, name)
            if os.path.isfile(full) and name.startswith("0="):
                return "object"
        # Otherwise look in subdirectories for a Namaste file
        for name in entries:
            sub = os.path.join(path, name)
            if os.path.isdir(sub):
                try:
                    sub_entries = os.listdir(sub)
                except Exception:
                    continue
                for sub_name in sub_entries:
                    sub_full = os.path.join(sub, sub_name)
                    if os.path.isfile(sub_full) and sub_name.startswith("0="):
                        return "root"
        # If no Namaste file found, not an OCFL path
        return "unknown type"
    # Not a file or directory
    return "not a regular file or directory"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    import re
    try:
        if not os.path.exists(path):
            return f"error: path '{path}' does not exist"
        if os.path.isfile(path):
            return 'file'
        if os.path.isdir(path):
            try:
                entries = os.listdir(path)
            except OSError as e:
                return f"error: cannot list directory '{path}': {e}"
            for name in entries:
                if os.path.isfile(os.path.join(path, name)):
                    if re.match(r'^0=.*', name):
                        return 'object'
            return 'root'
        return f"error: path '{path}' is neither file nor directory"
    except Exception as e:
        return f"error: unexpected issue with path '{path}': {e}"

