def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments.
    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a sequence")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict")

    parsed_namespaces = {}
    parsed_args_union = set()

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(list(unparsed_arguments))
        except Exception:
            # If a subparser fails, skip it
            continue
        parsed_namespaces[name] = namespace
        parsed_args_unmatched = set(remaining)
        parsed_args = set(unparsed_arguments) - parsed_args_unmatched
        parsed_args_union.update(parsed_args)

    remaining_args = [arg for arg in unparsed_arguments if arg not in parsed_args_union]
    return parsed_namespaces, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    from collections import Counter

    # Ensure we have a list to index
    unparsed = list(unparsed_arguments)
    parsed_namespaces = {}
    consumed_by = {}

    for name, parser in subparsers.items():
        try:
            namespace, remaining = parser.parse_known_args(unparsed)
        except Exception:
            # Skip this subparser if parsing fails
            continue

        # Determine which tokens were consumed by this subparser
        remaining_counts = Counter(remaining)
        consumed = []
        for token in unparsed:
            if remaining_counts.get(token, 0):
                remaining_counts[token] -= 1
            else:
                consumed.append(token)

        parsed_namespaces[name] = namespace
        consumed_by[name] = consumed

    # Tokens that any subparser claimed
    all_consumed = []
    for tokens in consumed_by.values():
        all_consumed.extend(tokens)

    claimed_counts = Counter(all_consumed)
    unclaimed = []
    for token in unparsed:
        if claimed_counts.get(token, 0):
            claimed_counts[token] -= 1
        else:
            unclaimed.append(token)

    return parsed_namespaces, unclaimed

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    """
    def is_mapping_node(node):
        # A simple heuristic to detect ── a ruamel.yaml MappingNode
        return (
            hasattr(node, "tag") and
            node.tag.startswith("tag:yaml.org,2002:map") and
            hasattr(node, "value") and
            isinstance(node.value, list) and
            all(isinstance(pair, tuple) and len(pair) == 2 for pair in node.value)
        )

    def merge_mapping_nodes(node_a, node_b):
        """
        Recursively merge two MappingNode instances and return a new MappingNode.
        The merging strategy is:
          * For keys that appear in both nodes:
              - If both values are MappingNodes, merge them recursively.
              - Otherwise, prefer the value from node_b (the later one).
          * Keys that appear only in one node are simply carried over.
        """
        pairs_a = node_a.value
        pairs_b = node_b.value

        # Build lookup dicts for quick access
        map_a = {key.value: (key, val) for key, val in pairs_a}
        map_b = {key.value: (key, val) for key, val in pairs_b}

        merged_pairs = []

        # Process keys from node_a
        for key_str, (key_node, val_node) in map_a.items():
            if key_str in map_b:
                val_node_b = map_b[key_str][1]
                if is_mapping_node(val_node) and is_mapping_node(val_node_b):
                    merged_val = merge_mapping_nodes(val_node, val_node_b)
                else:
                    merged_val = val_node_b
                # Use key_node from node_a for consistency
                merged_pairs.append((key_node, merged_val))
            else:
                merged_pairs.append((key_node, val_node))

        # Add remaining keys from node_b that were not in node_a
        for key_str, (key_node, val_node) in map_b.items():
            if key_str not in map_a:
                merged_pairs.append((key_node, val_node))

        # Construct a new MappingNode with the same tag as node_a
        return type(node_a)(tag=node_a.tag, value=merged_pairs)

    # Main merge logic for top-level list of tuples
    result = {}
    for key_node, value_node in nodes:
        key_str = key_node.value if hasattr(key_node, "value") else str(key_node)
        if key_str not in result:
            result[key_str] = (key_node, value_node)
        else:
            _, existing_value = result[key_str]
            if is_mapping_node(existing_value) and is_mapping_node(value_node):
                merged_value = merge_mapping_nodes(existing_value, value_node)
                result[key_str] = (key_node, merged_value)
            else:
                # Non-mapping or differing types: last wins
                result[key_str] = (key_node, value_node)

    # Preserve the order of first occurrences by iterating over the original list
    merged_list = []
    seen_keys = set()
    for key_node, _ in nodes:
        key_str = key_node.value if hasattr(key_node, "value") else str(key_node)
        if key_str not in seen_keys:
            merged_list.append(result[key_str])
            seen_keys.add(key_str)

    return merged_list

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    def merge_values(v1, v2):
        # Merge two values – mapping nodes are merged recursively,
        # otherwise the second value wins.
        from ruamel.yaml.nodes import MappingNode
        if isinstance(v1, MappingNode) and isinstance(v2, MappingNode):
            # Build a dict from the first mapping
            key_to_pair = {k.value: (k, val) for k, val in v1.value}
            # Merge entries from the second mapping
            for k2, val2 in v2.value:
                key = k2.value
                if key in key_to_pair:
                    _, existing_val = key_to_pair[key]
                    merged_val = merge_values(existing_val, val2)
                    key_to_pair[key] = (key_to_pair[key][0], merged_val)
                else:
                    key_to_pair[key] = (k2, val2)
            # Reconstruct the list preserving order from v1, then new entries
            merged_list = []
            seen = set()
            for k, val in v1.value:
                key = k.value
                merged_k, merged_val = key_to_pair[key]
                merged_list.append((merged_k, merged_val))
                seen.add(key)
            for key, (k, val) in key_to_pair.items():
                if key not in seen:
                    merged_list.append((k, val))
            return MappingNode(tag=v1.tag, value=merged_list)
        else:
            return v2

    result = []
    key_index = {}
    for key_node, val_node in nodes:
        key = key_node.value
        if key in key_index:
            idx = key_index[key]
            existing_key_node, existing_val_node = result[idx]
            merged_val = merge_values(existing_val_node, val_node)
            result[idx] = (existing_key_node, merged_val)
        else:
            result.append((key_node, val_node))
            key_index[key] = len(result) - 1
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two MappingNode objects in place.
    def _merge_mapping_nodes(dest, src):
        dest_pairs = dest.value  # list of (key_node, value_node)
        # Build index map of existing keys to (index, value_node)
        dest_map = {}
        for idx, (k, v) in enumerate(dest_pairs):
            dest_map[k.value] = (idx, v)
        # Merge entries from src
        for k_src, v_src in src.value:
            k_val = k_src.value
            if k_val in dest_map:
                idx, v_dest = dest_map[k_val]
                if isinstance(v_dest, MappingNode) and isinstance(v_src, MappingNode):
                    # Recursively merge nested MappingNodes
                    _merge_mapping_nodes(v_dest, v_src)
                else:
                    # Replace with src entry (keep src key node to preserve value)
                    dest_pairs[idx] = (k_src, v_src)
                    dest_map[k_val] = (idx, v_src)
            else:
                # New entry, append
                dest_pairs.append((k_src, v_src))
                dest_map[k_val] = (len(dest_pairs) - 1, v_src)

    result = {}
    for key_node, val_node in nodes:
        key_val = key_node.value
        if key_val in result:
            existing_key, existing_val = result[key_val]
            # Merge if both values are MappingNode, else replace
            if isinstance(existing_val, MappingNode) and isinstance(val_node, MappingNode):
                _merge_mapping_nodes(existing_val, val_node)
            else:
                result[key_val] = (key_node, val_node)
        else:
            result[key_val] = (key_node, val_node)
    return list(result.values())

