def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Validate inputs
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError("unparsed_arguments must be a sequence")
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict")

    args = list(unparsed_arguments)
    parsed = {}
    consumed_indices = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f"Parser for subparser '{name}' does not support parse_known_args")

        try:
            ns, unknown = parser.parse_known_args(args)
        except Exception as exc:
            raise ValueError(f"Error parsing arguments for subparser '{name}': {exc}") from exc

        parsed[name] = ns

        # Mark any argument occurrence that this parser consumed
        for idx, arg in enumerate(args):
            if arg not in unknown:
                consumed_indices.add(idx)

    remaining = [args[i] for i in range(len(args)) if i not in consumed_indices]
    return parsed, remaining

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if response is None:
        raise ValueError("The 'response' argument cannot be None.")
    if not isinstance(response, (list, tuple)):
        raise TypeError("The 'response' argument must be a list or tuple.")
    if not isinstance(max_results, int):
        raise TypeError("The 'max_results' argument must be an integer.")
    if max_results <= 0:
        raise ValueError("The 'max_results' argument must be a positive integer.")

    # Generator that yields slices of the response
    try:
        for start in range(0, len(response), max_results):
            yield response[start:start + max_results]
    except Exception as exc:
        # Re‑raise as a generic exception with context
        raise RuntimeError("Error while paging through the response.") from exc

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate inputs
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def generator():
        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]
    return generator()

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if response is None:
        raise ValueError("response cannot be None")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be greater than 0")
    try:
        iterator = iter(response)
    except TypeError:
        raise TypeError("response must be an iterable (e.g., list)")
    chunk = []
    for item in iterator:
        chunk.append(item)
        if len(chunk) == max_results:
            yield chunk
            chunk = []
    if chunk:
        yield chunk

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            continue  # ignore non-dict entries
        for k, v in d.items():
            if k in result:
                try:
                    result[k] += v
                except TypeError:
                    raise TypeError(
                        f"Cannot sum values for key {k!r}: {result[k]!r} + {v!r}"
                    )
            else:
                result[k] = v
    return result

