    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            continue
        for key, value in d.items():
            try:
                result[key] = result.get(key, 0) + value
            except TypeError:
                # In case values are not additive, raise a clear exception
                raise TypeError(f"Values for key '{key}' must be additive (support '+'), got {value!r}")
    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """

    result = {}
    if not dicts:
        return result
    for d in dicts:
        if not isinstance(d, dict):
            continue
        for k, v in d.items():
            try:
                result[k] = result.get(k, 0) + v
            except Exception:
                # If values are not numeric, store as list of values
                if k not in result:
                    result[k] = [v]
                else:
                    if isinstance(result[k], list):
                        result[k].append(v)
                    else:
                        result[k] = [result[k], v]
    return result

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not hasattr(dicts, "__iter__"):
        raise TypeError("Expected an iterable of dictionaries.")
    result = {}
    for d in dicts:
        if d is None:
            continue
        if not isinstance(d, dict):
            raise TypeError(f"Expected dictionary, got {type(d).__name__}.")
        for key, value in d.items():
            try:
                result[key] = result.get(key, 0) + value
            except TypeError:
                # If values are not numeric or cannot be added,
                # fall back to first encountered value
                if key not in result:
                    result[key] = value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        raise TypeError('url must be a string')

    if not isinstance(url_args, dict):
        raise TypeError('url_args must be a mapping/dict')

    # Iterate over all key/value pairs and replace placeholders in the URL.
    # Placeholders are expected to be in the form '{key}'.
    result = url
    for key, value in url_args.items():
        # Ensure the key is a string.
        key_str = str(key)
        # Encode the value for URL safety. Treat None as empty string.
        if value is None:
            encoded_val = ''
        else:
            encoded_val = urllib.parse.quote_plus(str(value))
        placeholder = '{' + key_str + '}'
        result = result.replace(placeholder, encoded_val)

    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # If url is not a string, return it unchanged
    if not isinstance(url, str):
        return url

    # Ensure url_args is a mapping; otherwise treat as empty
    if not isinstance(url_args, dict):
        url_args = {}

    replaced_url = url
    for key, value in url_args.items():
        # Skip if value is None
        if value is None:
            continue
        val_str = str(value)
        # Replace common placeholder patterns
        replaced_url = replaced_url.replace(f'{{{key}}}', val_str)
        replaced_url = replaced_url.replace(f':{key}', val_str)
        replaced_url = replaced_url.replace(f'<{key}>', val_str)

    return replaced_url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return url

    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    import re

    pattern = re.compile(r'\{([a-zA-Z0-9_]+)\}|\:([a-zA-Z0-9_]+)')

    def replace(match):
        var = match.group(1) or match.group(2)
        if var not in url_args:
            raise KeyError(f"Missing value for URL argument: {var}")
        value = url_args[var]
        if value is None:
            value = ''
        return str(value)

    try:
        return pattern.sub(replace, url)
    except re.error as exc:
        raise ValueError(f"Invalid URL pattern: {exc}") from exc

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        return url

    if not url_args:
        return url

    # Pattern for placeholders like {key} or <key>
    pattern = re.compile(r'{([^{}]+)}|<([^<>]+)>')

    def _replacer(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            try:
                return str(url_args[key])
            except Exception:
                # If conversion fails, leave the placeholder unchanged
                return match.group(0)
        return match.group(0)

    try:
        return pattern.sub(_replacer, url)
    except Exception as e:
        # In case of unexpected errors, return the original URL
        return url

