def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    if not hasattr(parser, "_actions"):
        raise TypeError(f"Expected an argparse.ArgumentParser, got {type(parser)!r}")
    flags = []
    for action in parser._actions:
        # action.option_strings contains optional flag strings (e.g., ["-h", "--help"])
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)
    return " ".join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    # Basic validation: parser should have the attributes we expect
    if parser is None:
        raise ValueError("parser argument cannot be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance with _actions attribute")
    try:
        actions = parser._actions
    except Exception as ex:
        raise TypeError("Failed to access parser actions") from ex

    flags = set()
    for action in actions:
        # Each action may expose `option_strings`, which is a list of flag names
        try:
            option_strings = getattr(action, "option_strings", [])
        except Exception:
            continue  # skip actions that can't expose option_strings
        for flag in option_strings:
            if isinstance(flag, str) and flag.startswith("-"):
                flags.add(flag)

    # Return flags sorted for deterministic output
    return " ".join(sorted(flags))

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Ensure the parser has the expected internal structure
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance")
    flags = []
    seen = set()
    for action in parser._actions:
        for opt in action.option_strings:
            if opt not in seen:
                flags.append(opt)
                seen.add(opt)
    return " ".join(flags)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    try:
        actions = parser._actions
    except AttributeError:
        return ''
    flags = []
    for action in actions:
        # action.option_strings is a list of the option flags for this action
        for opt in getattr(action, "option_strings", []):
            # Skip positional arguments which have no option strings
            if opt:
                flags.append(opt)
    # Remove duplicates and sort for consistency
    unique_flags = sorted(set(flags))
    return ' '.join(unique_flags) if unique_flags else ''

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string."""
    try:
        if parser is None:
            raise ValueError("parser argument cannot be None")
        import argparse
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError("parser must be an argparse.ArgumentParser instance")
        # Collect all option strings from the parser's actions
        flags = []
        for action in parser._actions:
            # Skip actions that have no option strings (e.g., positional arguments)
            opt_strs = getattr(action, "option_strings", [])
            if opt_strs:
                flags.extend(opt_strs)
        return " ".join(flags)
    except Exception as e:
        # Reraise with an informative message
        raise RuntimeError(f"Failed to parse flags from argument parser: {e}") from e

def was_processed(processed, path_name, verbose):
    """
    Check if a file or directory has already been processed.

    To prevent recursion, expand the path name to an absolute path
    call this function with a set that will store all the entries and
    the entry to test. If the entry is already in the set, report the issue
    and return ``True``. Otherwise, add the entry to the set and return
    ``False`` to allow the path to be processed.

    Args:
        processed: Set to store processed pathnames
        path_name: Path to a directory or file
        verbose: True if verbose output is requested

    Returns:
        True if it's already in the set. False if not.
    """
    if processed is None:
        raise ValueError('processed must be a set, got None')
    if not hasattr(processed, 'add'):
        raise TypeError('processed must be a set or set-like collection')
    try:
        abs_path = os.path.abspath(str(path_name))
    except Exception as e:
        if verbose:
            print(f'[was_processed] Failed to resolve path: {path_name!r} ({e})')
        return False
    if abs_path in processed:
        if verbose:
            print(f'[was_processed] Already processed: {abs_path}')
        return True
    try:
        processed.add(abs_path)
    except Exception as e:
        if verbose:
            print(f'[was_processed] Could not add path to processed set: {abs_path!r} ({e})')
        return False
    return False

def vertex3tuple(vertices):
        """
        return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

            polygon with vertices ABCD
            Will return
            DAB, ABC, BCD, CDA -> returns 3tuples
            #A    B    C    D  -> of vertices
        """
        if vertices is None:
            raise TypeError("vertices cannot be None")
        try:
            n = len(vertices)
        except Exception:
            raise TypeError("vertices must be a sequence with a defined length")
        if n < 3:
            raise ValueError("At least three vertices are required to form 3-tuples")
        return [(vertices[i-1], vertices[i], vertices[(i+1) % n]) for i in range(n)]

def vertex3tuple(vertices):
    '''
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    '''
    try:
        if vertices is None:
            raise ValueError('vertices parameter cannot be None')
        n = len(vertices)
    except TypeError:
        raise TypeError('vertices must be a sequence type with length')

    if n < 3:
        raise ValueError('vertices must contain at least 3 points')

    result = []
    for i in range(n):
        prev = vertices[i-1]
        curr = vertices[i]
        nxt = vertices[(i+1) % n]
        result.append((prev, curr, nxt))

    return result

def vertex3tuple(vertices):
        """
        return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::
            polygon with vertices ABCD
            Will return
            DAB, ABC, BCD, CDA -> returns 3tuples
            #A    B    C    D  -> of vertices
        """
        try:
            verts = list(vertices)
            n = len(verts)
            if n < 3:
                raise ValueError("A polygon must have at least 3 vertices")
            result = []
            for i in range(n):
                # prev, current, next (wrap around)
                result.append((verts[i - 1], verts[i], verts[(i + 1) % n]))
            return result
        except Exception as e:
            raise e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, (list, tuple)) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list or tuple")
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            n, remainder = divmod(n, base)
            digits.append(alphabet[remainder])
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def int_to_string(number, alphabet, padding=None):
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
