        raise ValueError("number must be non-negative")

    if not isinstance(alphabet, list) or not alphabet:
        raise ValueError("alphabet must be a non-empty list")
    if not all(isinstance(ch, str) and len(ch) == 1 for ch in alphabet):
        raise ValueError("alphabet must contain single-character strings only")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two distinct symbols")

    # Build the base representation
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        result = ''.join(reversed(digits))

    # Apply optional padding with the zero symbol (alphabet[0])
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("padding must be a non-negative integer or None")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return result

