def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Input validation
    if not isinstance(number, int):
        raise ValueError(f"number must be an integer, got {type(number).__name__}")
    if number < 0:
        raise ValueError(f"number must be non‑negative, got {number}")

    if not isinstance(alphabet, (list, tuple)):
        raise ValueError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) < 2:
        raise ValueError(f"alphabet must contain at least two symbols, got {len(alphabet)}")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet contains duplicate symbols")
    for sym in alphabet:
        if not isinstance(sym, str):
            raise ValueError(f"alphabet elements must be strings, got {type(sym).__name__}")

    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError(f"padding must be a non‑negative integer or None, got {padding}")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            digit_index = n % base
            digits.append(alphabet[digit_index])
            n //= base
        # digits are collected least‑significant first, reverse them
        result = ''.join(reversed(digits))

    # Apply padding if requested
    if padding is not None:
        pad_len = padding - len(result)
        if pad_len > 0:
            result = alphabet[0] * pad_len + result

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters")
    # Convert number to digits in the given base
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()
    result = "".join(digits)
    # Pad with leading alphabet[0] if required
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError(f"padding must be int or None, got {type(padding).__name__}")
        if padding < 0:
            raise ValueError("padding must be non‑negative")
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result
    return result

