    which contains 'desc' files for each package. Each .tar.gz archive corresponds
    to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: URL of the .tar.gz archive to download.
        destination_path: The path on disk where to extract archive.

    Returns:
        A Path object pointing to the directory where the archive has been extracted.
    """
    if not isinstance(destination_path, Path):
        raise TypeError("destination_path must be a pathlib.Path instance")

    # Ensure the destination directory exists and is empty
    if destination_path.exists():
        if not destination_path.is_dir():
            raise ValueError(f"Destination path {destination_path} exists and is not a directory.")
        if any(destination_path.iterdir()):
            raise RuntimeError(f"Destination directory {destination_path} must be empty before extraction.")
    else:
        destination_path.mkdir(parents=True, exist_ok=True)

    # Download the archive
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise RuntimeError(f"Failed to download archive from {url}: {exc}") from exc

    # Write the downloaded content to a temporary file
    fd, tmp_path = tempfile.mkstemp(suffix=".tar.gz")
    os.close(fd)  # Close the raw file descriptor; we will open via a file handle
    try:
        with open(tmp_path, "wb") as tmp_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    tmp_file.write(chunk)

        # Extract the archive
        try:
            with tarfile.open(tmp_path, "r:gz") as tar:
                tar.extractall(path=str(destination_path))
        except tarfile.TarError as exc:
            raise RuntimeError(f"Failed to extract archive: {exc}") from exc
    finally:
        try:
            os.remove(tmp_path)
        except OSError:
            pass

    return destination_path

