    if isinstance(s, bytes):
        try:
            s = s.decode('utf-8')
        except Exception as exc:  # pragma: no cover
            raise ValueError('Unable to decode bytes to UTF-8') from exc
    import shlex
    import sys
    # Determine the posix flag based on the platform argument
    if platform == 'this':
        posix = not sys.platform.lower().startswith('win')
    elif platform in (1, 'posix'):
        posix = True
    elif platform in (0, 'win', 'windows'):
        posix = False
    else:
        raise ValueError('unknown platform: %r' % platform)
    # Use shlex with the appropriate posix flag
    return shlex.split(s, posix=posix)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using shlex with
    platform-specific options.  The `platform` argument can be:
        'this' - auto-detect from the current OS (Windows: 0, others: 1)
        1       - POSIX style, equivalent to shlex.split(s, posix=True)
        0       - Windows/CMD style, equivalent to shlex.split(s, posix=False)
    Any other value raises ValueError.
    """
    import sys
    import shlex

    # Auto-detect platform if requested
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1

    # Ensure we work with text
    if not isinstance(s, str):
        try:
            s = s.decode('utf-8')
        except Exception:
            # If decoding fails we simply raise a TypeError
            raise TypeError('Input must be a string or bytes encoded in UTF-8')

    try:
        if platform == 1:
            return shlex.split(s, posix=True)
        elif platform == 0:
            return shlex.split(s, posix=False)
        else:
            raise ValueError('Unsupported platform value: {}'.format(platform))
    except ValueError as exc:
        # shlex.split may raise ValueError for malformed input
        raise ValueError('Failed to split the command string: {}'.format(exc))

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Create a temporary directory for extraction
    try:
        temp_res = subprocess.run(
            ["mktemp", "-d", "-p", str(tmp_path)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=True,
        )
        tmp_dir = temp_res.stdout.decode().strip()
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Failed to create temporary directory from {tmp_path}: {exc.stderr.decode().strip()}"
        )

    # Determine extraction command based on archive extension
    if archive_path.endswith(".tar.gz") or archive_path.endswith(".tgz"):
        cmd = ["tar", "-xzf", archive_path, "-C", tmp_dir]
    elif archive_path.endswith(".tar.bz2") or archive_path.endswith(".tbz2"):
        cmd = ["tar", "-xjf", archive_path, "-C", tmp_dir]
    elif archive_path.endswith(".zip"):
        cmd = ["unzip", "-q", archive_path, "-d", tmp_dir]
    else:
        raise ValueError(f"Unsupported archive format for {archive_path!r}")

    # Perform extraction
    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Extraction failed for {archive_path!r}: {exc.stderr.decode().strip()}"
        )

    # Determine the repository root directory
    repo_root = tmp_dir
    if filename:
