def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None

    if not isinstance(frequency, str):
        raise ValueError('frequency must be a string, None, or "always"')

    fp = frequency.strip().lower()
    if not fp:
        raise ValueError('empty frequency string')

    # split into number and unit parts
    parts = fp.split(None, 1)  # split on any whitespace
    if len(parts) != 2:
        raise ValueError(f'cannot parse frequency: "{frequency}"')

    num_str, unit_str = parts
    try:
        # allow integer or float
        if '.' in num_str:
            num = float(num_str)
        else:
            num = int(num_str)
    except ValueError:
        raise ValueError(f'invalid number in frequency: "{num_str}"')

    # normalize unit (strip trailing "s" if plural)
    unit = unit_str.rstrip('s').lower()

    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
        'sec': 'seconds',
        's': 'seconds',
    }

    if unit not in unit_map:
        raise ValueError(f'unknown or unsupported unit "{unit_str}"')

    kwargs = {unit_map[unit]: num}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        # Resolve all address types for the given host
        infos = socket.getaddrinfo(host, None, 0, 0, 0, socket.AI_PASSIVE)
    except socket.gaierror:
        # If we can't resolve, assume it's not local
        return False

    for info in infos:
        family, _, _, _, sockaddr = info
        try:
            if family == socket.AF_INET:
                ip_addr = sockaddr[0]
                # IPv4 loopback: 127.0.0.0/8
                if ip_addr.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip_addr = sockaddr[0]
                # IPv6 loopback: ::1 (may include zone index)
                if ip_addr == "::1" or ip_addr.split("%", 1)[0] == "::1":
                    return True
        except Exception:
            # Ignore malformed address info
            continue
    return False

