def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    try:
        # Direct localhost string
        if str(host).lower() == "localhost":
            return True

        # Check IPv4 loopback
        try:
            packed = socket.inet_aton(host)
            return packed[0] == 127
        except (OSError, TypeError):
            pass

        # Check IPv6 loopback
        try:
            packed6 = socket.inet_pton(socket.AF_INET6, host)
            return packed6 == b"\x00"*15 + b"\x01"
        except (OSError, AttributeError, TypeError):
            pass

    except Exception:
        pass
    return False

def is_local(host):
    """
    Checks if the host is the localhost.

    :param host: The hostname or IP address (can be in brackets).
    :return: True if the host is the localhost, False otherwise.
    """
    # Normalise the host string
    if not isinstance(host, str):
        return False
    host_str = host.strip()
    if not host_str:
        return False

    # Handle brackets around IPv6 addresses, e.g. "[::1]"
    if host_str.startswith('[') and host_str.endswith(']'):
        host_str = host_str[1:-1].strip()

    # Direct match for canonical hostname
    if host_str.lower() == 'localhost':
        return True

    # Try to resolve the host
    try:
        # Get both IPv4 and IPv6 addresses for the host
        for res in socket.getaddrinfo(host_str, None, socket.AF_UNSPEC, 0, 0, 0):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET and addr == '127.0.0.1':
                return True
            if family == socket.AF_INET6 and addr == '::1':
                return True
    except (socket.gaierror, socket.error):
        # If resolution fails, assume not local
        return False

    return False

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    Example:
        ['foo.txt', 'pp:root/somedir'] -> ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        raise TypeError("find_paths cannot be None")
    if not isinstance(find_paths, (list, tuple)):
        raise TypeError(f"find_paths must be a list or tuple, got {type(find_paths)}")
    result = []
    for item in find_paths:
        if not isinstance(item, str):
            raise TypeError(f"Each find_path must be a string, got {type(item)}")
        # Patterns are identified by presence of ':' (e.g., 'pp:root/somedir')
        if ':' in item:
            result.append(item)
        else:
            # Convert fragment into a glob pattern
            result.append(f"sh:**/*{item}*/**")
    return result

