    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError(f"config_filename must be a string, got {type(config_filename).__name__}")
    if not isinstance(rendered_config, (str, bytes)):
        raise TypeError(f"rendered_config must be a string or bytes, got {type(rendered_config).__name__}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an int, got {type(mode).__name__}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite).__name__}")

    target_path = os.path.expanduser(config_filename)

    # If file exists and overwriting is disallowed, abort
    if not overwrite and os.path.isfile(target_path):
        raise FileExistsError(f"File '{target_path}' already exists and overwrite is False")

    # Create directory hierarchy if needed
    dir_name = os.path.dirname(target_path)
    if dir_name:
        try:
            os.makedirs(dir_name, exist_ok=True)
        except OSError as exc:
            # If directory exists but may not be a directory, re-raise
            if not os.path.isdir(dir_name):
                raise
            # otherwise ignore creation error
            pass

    # Write the configuration
    try:
        open_mode = 'wb' if isinstance(rendered_config, bytes) else 'w'
        with open(target_path, open_mode, encoding='utf-8' if open_mode == 'w' else None) as f:
            f.write(rendered_config)
        os.chmod(target_path, mode)
    except OSError as e:
        # Clean up in case of partial write
        if os.path.exists(target_path):
            try:
                os.remove(target_path)
            except OSError:
                pass
        raise e

    return target_path

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract name and default from various possible matcher representations
    if hasattr(matcher, "name"):
        name = matcher.name
        default_present = hasattr(matcher, "default")
        default = getattr(matcher, "default", None) if default_present else None
    elif hasattr(matcher, "groupdict"):
        attrs = matcher.groupdict()
        if "name" not in attrs:
            raise AttributeError("Matcher groupdict must contain a 'name' key")
        name = attrs["name"]
        default_present = "default" in attrs
        default = attrs.get("default")
    elif isinstance(matcher, dict):
        if "name" not in matcher:
            raise KeyError("Matcher dict must contain a 'name' key")
        name = matcher["name"]
        default_present = "default" in matcher
        default = matcher.get("default")
    else:
        raise TypeError("Matcher must be an object with a 'name' attribute, a regex match object, or a dict containing 'name'")

    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")

    value = os.environ.get(name)
    if value is not None:
        return value
    if default_present:
        return default
    raise KeyError(f"Environment variable '{name}' is not set and no default was provided")

def _resolve_string(matcher):
