    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Extract the variable name and the optional default value from the matcher
    if isinstance(matcher, dict):
        name = matcher.get('name')
        default = matcher.get('default', None)
    else:
        name = getattr(matcher, 'name', None)
        default = getattr(matcher, 'default', None)

    if name is None:
        raise ValueError('Matcher must contain a name')

    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise EnvironmentError(f'Environment variable {name} not set')
    return value

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional
    default value. If the variable is not defined in environment and no default
    value is provided, an Error is raised.
    """
    # Determine how to extract the variable name and optional default from the matcher.
    # The matcher might be a regex match object or a dict-like object.
    if hasattr(matcher, "groupdict"):  # regex match
        groups = matcher.groupdict()
        name = groups.get("name")
        default = groups.get("default")
    elif isinstance(matcher, dict):
        name = matcher.get("name")
        default = matcher.get("default")
    elif hasattr(matcher, "__getitem__"):
        # Fallback: index-based tuple/list
        try:
            name = matcher[0]
        except Exception:
            raise ValueError("Unable to extract variable name from matcher.")
        try:
            default = matcher[1]
        except Exception:
            default = None
    else:
        raise ValueError("Unsupported matcher type: %r" % matcher)

    if name is None:
        raise ValueError("Variable name missing in matcher")

    # Look up the name in the environment
    try:
        return os.environ[name]
    except KeyError:
        if default is not None:
            return default
        # No default value, raise a clear error
        raise KeyError(f"Environment variable '{name}' not found and no default provided")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # If we already have a compiled pattern, simply return it
    if isinstance(pattern, re.Pattern):
