def get_pattern(pattern, strip=True):
    """
    This method converts the given string to a regex pattern.

    :param pattern: The pattern to compile, either a string or a compiled regex.
    :type pattern: str or re.Pattern
    :param strip: Whether to strip leading and trailing whitespace from the string.
    :type strip: bool
    :return: The compiled regex pattern or the original pattern if already compiled.
    :rtype: re.Pattern
    """
    if pattern is None:
        return None

    # If pattern is already a compiled regex, just return it
    if hasattr(pattern, "pattern") and hasattr(pattern, "match"):
        # Already a compiled pattern
        return pattern

    # Ensure we have a string to compile
    if not isinstance(pattern, (str, bytes, bytearray)):
        raise TypeError(f"Pattern must be a string or compiled regex, got {type(pattern).__name__}")

    # Decode bytes if necessary
    if isinstance(pattern, (bytes, bytearray)):
        try:
            pattern = pattern.decode()
        except Exception as exc:
            raise ValueError("Failed to decode byte pattern") from exc

    # Strip whitespace if requested
    if strip:
        pattern = pattern.strip()

    # Compile the pattern, raising re.error if invalid
    try:
        return re.compile(pattern)
    except re.error as exc:
        raise re.error(f"Invalid regex pattern: {pattern}") from exc

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize command and arguments to list form
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        cmd_list = list(commands)
    if args is None:
        arg_list = []
    elif isinstance(args, str):
        arg_list = [args]
    else:
        arg_list = list(args)

    full_cmd = cmd_list + arg_list

    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")

    stderr_target = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
