def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    elif isinstance(commands, str):
        import shlex
        cmd_list = shlex.split(commands)
    else:
        raise TypeError("commands must be a list/tuple or string")
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")
    cmd = cmd_list + list(args)

    # Verbosity
    if verbose:
        print(f"Executing: {' '.join(shlex.quote(c) for c in cmd)}")
        if cwd:
            print(f"Working directory: {cwd}")

    # Configure stderr
    stderr_option = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            text=True,
        )
    except Exception as exc:
        raise RuntimeError(f"Failed to run command {cmd!r}: {exc}") from exc

    # Raise an error if the command failed
    if result.returncode != 0:
        err_msg = f"Command {cmd!r} exited with code {result.returncode}"
        if not hide_stderr and result.stderr:
            err_msg += f"\nstderr:\n{result.stderr}"
        raise subprocess.CalledProcessError(result.returncode, cmd, output=result.stdout, stderr=result.stderr)

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Ensure commands is an iterable of command parts or strings
    if isinstance(commands, str):
        commands = [commands]
    if not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or an iterable of strings/lists")
    # Prepare arguments list
    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of strings")
    # Collect results
    results = []
    for cmd in commands:
        # Convert each command to a list of parts
        if isinstance(cmd, (list, tuple)):
            command_parts = list(cmd)
        else:
            # Treat as a single string command
            command_parts = [cmd]
        # Append extra arguments
        command_parts += list(args)
        if verbose:
            print(f"Running command: {' '.join(command_parts)}")
        # Determine stderr handling
        stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        try:
            result = subprocess.run(
                command_parts,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True,
                check=False,
            )
        except FileNotFoundError as e:
            raise RuntimeError(f"Command not found: {' '.join(command_parts)}") from e
        except Exception as e:
            raise RuntimeError(f"Failed to execute command: {' '.join(command_parts)}: {e}") from e
        # Raise if command failed
        if result.returncode != 0:
            message = f"Command '{' '.join(command_parts)}' exited with {result.returncode}"
            if not hide_stderr and result.stderr:
                message += f"\nStderr:\n{result.stderr}"
            if result.stdout:
                message += f"\nStdout:\n{result.stdout}"
            raise subprocess.CalledProcessError(result.returncode, command_parts, output=result.stdout, stderr=result.stderr)
        results.append(result)
    return results if len(results) > 1 else results[0]

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize the commands argument
    if isinstance(commands, str):
        # single command string
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of commands")

    # Normalize the args argument
    # args can be:
    #   - None: no args
    #   - list/tuple of lists or tuples of args (one per command)
    #   - single list/tuple of args applied to all commands
    #   - single string applied to all commands
    if args is None:
        args_list = [ [] for _ in cmd_list ]
    elif isinstance(args, (str, list, tuple)):
        # check if args corresponds to each command
        if isinstance(args, (list, tuple)) and all(isinstance(a, (list, tuple)) for a in args):
            if len(args) != len(cmd_list):
                raise ValueError("Length of args list must match length of commands list")
            args_list = args
        else:
            # treat args as a single argument list for all commands
            args_list = [ []
                          for _ in cmd_list ],  # placeholder, will replace below
            if isinstance(args, str):
                common = shlex.split(args)
            else:
                common = list(args)
            args_list = [common for _ in cmd_list]
    else:
        raise TypeError("args must be None, a string, or a list/tuple")

    # Build full command lists
    full_cmds = []
    for cmd, arg in zip(cmd_list, args_list):
        if isinstance(cmd, str):
            base = shlex.split(cmd)
        elif isinstance(cmd, (list, tuple)):
            base = list(cmd)
        else:
            raise TypeError("Each command must be a string or a list/tuple of strings")

        if not isinstance(arg, (list, tuple)):
            raise TypeError("Each set of args must be a list or tuple")
        full_cmd = base + list(arg)
        full_cmds.append(full_cmd)

    # Prepare to run commands
    results = []
    for full_cmd in full_cmds:
        if verbose:
            print("Running command:", " ".join(shlex.quote(part) for part in full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=False
            )
        except OSError as e:
            raise RuntimeError(f"Failed to execute command '{full_cmd}': {e}") from e

        # Raise if command returned non-zero, if desired
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode, full_cmd,
                output=result.stdout,
                stderr=result.stderr
            )

        results.append(result)

    # Return single result or list based on input size
    return results[0] if len(results) == 1 else results

