def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or list
        shape of the array to create
    dtype : numpy.dtype or compatible
        data-type of the array to create

    Returns
    -------
    ndarray
        A new array with the specified shape and dtype.
    """
    # Validate that shape is a tuple/list of integers
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of integers")
    shape_tuple = tuple(shape)
    for i, dim in enumerate(shape_tuple):
        if not isinstance(dim, int):
            raise TypeError(f"shape element {i} is not an integer")
        if dim < 0:
            raise ValueError(f"shape element {i} is negative")

    # Convert dtype to a numpy dtype object, raising an error if invalid
    try:
        np_dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError("dtype must be a valid numpy dtype") from exc

    # Try to create the array, handling possible memory errors gracefully
    try:
        return np.empty(shape_tuple, dtype=np_dtype)
    except MemoryError as mem_exc:
        raise MemoryError(f"Unable to allocate array of shape {shape_tuple} with dtype {np_dtype}") from mem_exc

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple or int
        shape of the array to create
    dtype : `numpy.dtype` or convertible
        data-type of the array to create
    """
    # Ensure dtype is a numpy.dtype instance
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype {dtype!r}: {exc}") from exc

    # Normalise shape to a tuple of ints
    if isinstance(shape, int):
        shape_tuple = (shape,)
    else:
        try:
            shape_tuple = tuple(shape)
        except Exception as exc:
            raise TypeError(f"Shape must be an int or iterable of ints: {exc}") from exc

    # Validate that all dimensions are integers and >= 0
    for dim in shape_tuple:
        if not isinstance(dim, int):
            raise TypeError(f"Shape contains non-integer dimension: {dim!r}")
        if dim < 0:
            raise ValueError(f"Shape contains negative dimension: {dim!r}")

    try:
        result = np.empty(shape_tuple, dtype=dtype_obj)
    except Exception as exc:
        raise RuntimeError(f"Failed to create array with shape {shape_tuple} and dtype {dtype_obj}: {exc}") from exc

    return result

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    mean = 0.2
    sigma = 0.1
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise ValueError(f"Input x must be numeric or array-like but got {type(x)}") from e
    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = -0.5 * ((arr - mean) / sigma) ** 2
    return coeff * np.exp(exponent)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    import logging

    # Helper to resolve environment variables in configuration values
    def _resolve_env_vars(value):
        if isinstance(value, dict):
            return {k: _resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env_vars(v) for v in value]
        elif isinstance(value, str):
            return os.path.expandvars(value)
        else:
            return value

    results = {}
    error_records = []

    for filename in config_filenames:
        try:
            if not os.path.exists(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")
            ext = os.path.splitext(filename)[1].lower()
            with open(filename, 'r', encoding='utf-8') as fp:
                if ext == '.json':
                    config = json.load(fp)
                elif ext in {'.yaml', '.yml'}:
                    import yaml
                    config = yaml.safe_load(fp)
                elif ext == '.toml':
                    import toml
                    config = toml.load(fp)
                else:
                    raise ValueError(f"Unsupported configuration file extension: {ext}")
            if overrides:
                if isinstance(config, dict):
                    config.update(overrides)
                else:
                    raise TypeError("Configuration is not a dictionary; cannot apply overrides.")
            if resolve_env:
                config = _resolve_env_vars(config)
            results[filename] = config
        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(exc),
                args=None,
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            error_records.append(record)

    return results, tuple(error_records)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    try:
        import toml
    except ImportError:
        toml = None
    try:
        import yaml
    except ImportError:
        yaml = None

    configs = {}
    error_records = []
    logger = logging.getLogger(__name__)

    for filename in config_filenames:
        try:
            if not os.path.isfile(filename):
                raise FileNotFoundError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as fd:
                content = fd.read()

            if resolve_env:
                # Expand environment variables of the form $VAR or ${VAR}
                content = os.path.expandvars(content)

            # Determine parser based on file extension
            parsed = None
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.toml':
                if toml is None:
                    raise ImportError("Missing 'toml' package required to parse .toml files.")
                parsed = toml.loads(content)
            elif ext in {'.yml', '.yaml'}:
                if yaml is None:
                    raise ImportError("Missing 'yaml' package required to parse .yaml/.yml files.")
                parsed = yaml.safe_load(content)
            else:
                # Attempt JSON as a fallback
                parsed = json.loads(content)

            # Apply overrides if provided
            if overrides and isinstance(overrides, dict):
                # Perform a shallow merge; keys in overrides replace those in parsed
                if isinstance(parsed, dict):
                    parsed.update(overrides)
                else:
                    # If parsed is not a dict, we cannot apply overrides
                    pass

            configs[filename] = parsed

        except Exception as e:
            # Create a LogRecord to capture the error
            record = logging.makeLogRecord({
                'name': logger.name,
                'level': logging.ERROR,
                'pathname': filename,
                'lineno': 0,
                'msg': f'Error parsing configuration "{filename}": {e}',
                'args': (),
                'exc_info': None,
                'func': None,
                'sinfo': None
            })
            error_records.append(record)

    return configs, error_records

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
