                import yaml
                parsed = yaml.safe_load(raw)
            elif fname.lower().endswith('.toml'):
                import toml
                parsed = toml.loads(raw)
            else:
                # fall back: try json first then yaml then toml
                try:
                    import json
                    parsed = json.loads(raw)
                except Exception:
                    try:
                        import yaml
                        parsed = yaml.safe_load(raw)
                    except Exception:
                        try:
                            import toml
                            parsed = toml.loads(raw)
                        except Exception:
                            # as last resort use raw string
                            parsed = raw
            if not isinstance(parsed, dict):
                raise ValueError(f"Configuration in {fname} is not a mapping (dict)")
            if overrides:
                parsed.update(overrides)
            config_map[fname] = parsed
        except Exception as e:
            # create a LogRecord for the error
            record = logging.LogRecord(
                name="config_loader",
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            error_records.append(record)
