def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    try:
        import yaml
    except Exception:
        yaml = None
    try:
        import toml
    except Exception:
        toml = None

    logger_name = 'config_loader'
    parsed_configs = {}
    error_records = []

    def _resolve_env_recursively(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_recursively(v) for k, v in obj.items()}
        if isinstance(obj, list):
            return [_resolve_env_recursively(v) for v in obj]
        if isinstance(obj, str):
            return os.path.expandvars(obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                raw = f.read()
            config_data = None
            ext = os.path.splitext(filename)[1].lower()
            if ext == '.toml' and toml:
                config_data = toml.loads(raw)
            elif ext in {'.yml', '.yaml'} and yaml:
                config_data = yaml.safe_load(raw)
            elif ext == '.json':
                config_data = json.loads(raw)
            else:
                # fallback: try json then yaml
                try:
                    config_data = json.loads(raw)
                except Exception:
                    if yaml:
                        config_data = yaml.safe_load(raw)
                    else:
                        raise ValueError(f'Unsupported file extension and no parser available for {filename}')
            if config_data is None:
                config_data = {}
            if overrides:
                merged = dict(config_data)
                merged.update(overrides)
                config_data = merged
            if resolve_env:
                config_data = _resolve_env_recursively(config_data)
            parsed_configs[filename] = config_data
        except Exception as exc:
            record = logging.LogRecord(
                name=logger_name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Error parsing {filename}: {exc}',
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__))
            error_records.append(record)
    return (parsed_configs, error_records)

