        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple")

        # The class should expose a collection of protocol handlers.
        # Prefer a dedicated attribute; fall back to common names if absent.
        handler_mapping = getattr(
            cls, "HANDLERS", {}
        ) or getattr(cls, "PROTOCOL_HANDLERS", {}) \
            or getattr(cls, "PROTOCOLS", {})

        if not isinstance(handler_mapping, dict):
            raise TypeError("Handler mapping must be a dict")

        result = {}
        if protocol_version is None:
            for ver, handler_cls in handler_mapping.items():
                if isinstance(ver, tuple):
                    # If the handler defines a SUPPORTED flag,
                    # use it to filter; otherwise include all.
                    if getattr(handler_cls, "SUPPORTED", True):
                        result[ver] = handler_cls
        else:
            handler_cls = handler_mapping.get(protocol_version)
            if handler_cls and getattr(handler_cls, "SUPPORTED", True):
                result[protocol_version] = handler_cls
        return result

