        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """

        # Retrieve the mapping defined by the subclass.  The library
        # convention is to store it in a class attribute called
        # PROTOCOL_HANDLERS.  If the attribute is missing we fall back
        # to an empty dictionary safely.
        handlers = getattr(cls, "PROTOCOL_HANDLERS", {})

        # Normalise handlers to a dict with 2‑item tuples as keys.
        # Keys that are not 2‑item tuples are ignored silently.
        valid_handlers = {
            k: v for k, v in handlers.items()
            if isinstance(k, tuple) and len(k) == 2 and all(isinstance(i, int) for i in k)
        }

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            if len(protocol_version) != 2 or not all(isinstance(i, int) for i in protocol_version):
                raise TypeError(
                    f"protocol_version must be a tuple of two integers, got {protocol_version}"
                )
            handler = valid_handlers.get(protocol_version)
            return {protocol_version: handler} if handler is not None else {}

        # Return a copy of all supported handlers; callers should not modify
        # the returned dictionary to avoid side effects.
        return dict(valid_handlers)

