def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is already a list or tuple, return it unchanged along with its type.
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq))
    # Attempt to get an iterator; raise a meaningful error if not iterable.
    try:
        iterator = iter(seq)
    except TypeError:
        raise TypeError(f"Object of type {type(seq).__name__} is not iterable")
    # Consume the iterator, respecting bufsize if provided.
    if bufsize is not None:
        seq_list = []
        for i, element in enumerate(iterator):
            if i >= bufsize:
                break
            seq_list.append(element)
        return (seq_list, list)
    return (list(iterator), list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    # Handle simple string and bytes types: turn into list of chars/bytes
    if isinstance(seq, (str, bytes, bytearray)):
        return (list(seq), type(seq))

    # If seq is already a sequence type that we want to use directly
    if isinstance(seq, (list, tuple, set)):
        return (seq, type(seq))

    # Try to ensure seq is iterable; if not, just return it as-is
    try:
        iterator = iter(seq)
    except TypeError:
        return (seq, type(seq))

    # Collect items from the iterator into a list, optionally using a buffer size
    if bufsize is None:
        sequence = list(iterator)
    else:
        from itertools import islice
        sequence = []
        it = iterator
        while True:
            chunk = list(islice(it, bufsize))
            if not chunk:
                break
            sequence.extend(chunk)

    return (sequence, type(seq))

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise ValueError("seq cannot be None")

    # Handle strings, bytes and bytearray as sequences of characters/bytes
    if isinstance(seq, (str, bytes, bytearray)):
        return (list(seq), list)

    # If seq is already a list, tuple, set or frozenset, use it directly
    if isinstance(seq, (list, tuple, set, frozenset)):
        return (seq, type(seq))

    # For any other iterable, convert to list
    try:
        seq_list = list(seq)
        return (seq_list, list)
    except TypeError:
        # Non‑iterable input: return it as a single element in a list
        return ([seq], list)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type)."""

    # Identify if the input is already a sequence type (list or tuple).
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq).__name__)

    # Strings and bytes are treated as scalar sequences and are returned as
    # is.  Bytes are decoded to text for consistency.
    if isinstance(seq, str):
        return (seq, "string")
    if isinstance(seq, bytes):
        try:
            return (seq.decode("utf-8"), "bytes")
        except Exception:
            return (seq, "bytes")

    # For all other iterables (generators, iterators, etc.), attempt to
    # materialise the sequence into a list.  The optional ``bufsize`` can
    # be used to read in chunks when dealing with very large iterables,
    # but if ``bufsize`` is None a simple ``list(seq)`` is used.
    try:
        iterator = iter(seq)
    except TypeError:
        raise ValueError("Argument 'seq' must be an iterable, string, or bytes-like object")

    # If a buffer size is supplied, build the list in pieces to avoid
    # excessive memory usage for large sequences.
    if bufsize is not None and bufsize > 0:
        result = []
        chunk = []
        for item in iterator:
            chunk.append(item)
            if len(chunk) >= bufsize:
                result.extend(chunk)
                chunk = []
        if chunk:
            result.extend(chunk)
        return (result, "iterable (chunked)")
    else:
        return (list(iterator), "iterable")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("Provided sequence is None")
    # Try interpreting a string or bytes as a file path first
    if isinstance(seq, (str, bytes)):
        try:
            mode = 'rb' if isinstance(seq, bytes) else 'r'
            with open(seq, mode) as handle:
                if bufsize is None:
                    content = handle.read()
                else:
                    # Read the first ``bufsize`` bytes/characters
                    content = handle.read(bufsize)
                    # Read the remaining content
                    remaining = handle.read()
                    content += remaining
            # If we read bytes, decode to a str
            if isinstance(content, bytes):
                try:
                    content = content.decode()
                except Exception:
                    content = content.decode('utf-8', 'ignore')
            sequence = content.strip()
            return (sequence, 'file')
        except (OSError, IOError, FileNotFoundError):
            # Not a valid path; treat the input as a literal string
            return (seq, 'str')
    # For other iterables (lists, tuples, generators) – join elements
    if hasattr(seq, "__iter__") and not isinstance(seq, (bytes, bytearray)):
        try:
            sequence = ''.join(map(str, seq))
            return (sequence, 'iter')
        except Exception:
            # If we cannot join, fall back to original object
            return (seq, type(seq).__name__)
    # Default: return the object itself with its type name
    return (seq, type(seq).__name__)

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Import numpy locally to avoid global dependencies
    try:
        import numpy as np  # noqa: F401
    except Exception:
        np = None

    # Helper to check numeric
    def _is_numeric(val):
        if np:
            return isinstance(val, (int, float, np.integer, np.floating))
        return isinstance(val, (int, float))

    # If no argument, simply return current scale
    if other is None:
        # Prefer attribute `_scale` if present, else try property `scale`
        return getattr(self, "_scale", getattr(self, "scale", None))

    # Validate that other is numeric
    if not _is_numeric(other):
        raise TypeError("Expected a numeric value for the target scale, got %r" % (other,))

    # Retrieve current scale
    current_scale = getattr(self, "_scale", getattr(self, "scale", None))
    if current_scale is None or _is_numeric(current_scale) and current_scale == 0:
        # Raise the specific exception expected by the docstring; fall back to ValueError if not defined
        try:
            raise LenaValueError("Cannot rescale graph with unknown or zero current scale.")
        except NameError:
            raise ValueError("Cannot rescale graph with unknown or zero current scale.")

    # Compute scaling factor
    factor = float(other) / float(current_scale)

    # Determine the last coordinate (assuming the graph stores coordinate names in a list or tuple)
    coord_names = getattr(self, "coord_names", None)
    if coord_names is not None and len(coord_names) > 0:
        last_coord = coord_names[-1]
    else:
        # Fallback: try to extract from field names that are coordinate-like (e.g., last key)
        fields = getattr(self, "fields", {})
        if isinstance(fields, dict) and fields:
            last_coord = list(fields.keys())[-1]
        else:
            last_coord = None

    # Rescale fields and errors for the last coordinate if applicable
    if last_coord is not None:
        # Rescale field values
        if hasattr(self, "fields"):
            try:
                self.fields[last_coord] = self.fields[last_coord] * factor
            except Exception:
                # In case fields are not subscriptable or contain non-numeric values
                pass
        # Rescale errors if present
        if hasattr(self, "errors"):
            try:
                self.errors[last_coord] = self.errors[last_coord] * factor
            except Exception:
                pass

    # Update the stored scale to the new value
    setattr(self, "_scale", other)

    # Typically a setter returns None; but for convenience return the new scale
    return other

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

        >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine bin contents and bin edges
    try:
        bins = hist.bins
    except AttributeError:
        try:
            bins = hist.data
        except AttributeError:
            bins = hist
    bins = list(bins)

    try:
        edges = hist.edges
    except AttributeError:
        edges = None

    if not isinstance(get_coordinate, str):
        raise TypeError("get_coordinate must be a string: 'left', 'right', or 'middle'")

    if make_value is None:
        # Default: return the bin content itself
        make_value = lambda bin_: bin_

    # Prepare coordinate selection
    def coordinate(left, right):
        if get_coordinate == "left":
            return left
        if get_coordinate == "right":
            return right
        if get_coordinate == "middle":
            return (left + right) / 2.0
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Determine coordinates for each bin
    points = []
    if edges:
        if len(edges) != len(bins) + 1:
            raise ValueError("Length of edges must be one greater than number of bins")
        for i, bin_val in enumerate(bins):
            left = edges[i]
            right = edges[i + 1]
            coord = coordinate(left, right)
            value = make_value(bin_val)
            if isinstance(value, tuple) or isinstance(value, list):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)
    else:
        # No edges provided: use bin indices
        for idx, bin_val in enumerate(bins):
            coord = idx
            value = make_value(bin_val)
            if isinstance(value, tuple) or isinstance(value, list):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)

    if not points:
        raise ValueError("Histogram contains no bins")

    # Verify field_names consistency
    dim = len(points[0])
    if len(field_names) != dim:
        raise ValueError(f"field_names length {len(field_names)} does not match "
                         f"graph dimensionality {dim}")

    # Determine scale
    if scale is True:
        try:
            scale = hist.scale
        except AttributeError:
            scale = None
    # If scale is iterable (e.g., string) keep as is; if None just leave.

    # Simple Graph placeholder: no external imports
    class Graph:
        def __init__(self, points, field_names, scale):
            self.points = points
            self.field_names = field_names
            self.scale = scale

    return Graph(points, field_names, scale)

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Extract edges from histogram
    try:
        if hasattr(hist, "edges"):
            edges = list(hist.edges)
        elif hasattr(hist, "bin_edges"):
            edges = list(hist.bin_edges)
        elif hasattr(hist, "axes") and hasattr(hist.axes[0], "edges"):
            edges = list(hist.axes[0].edges)
        elif isinstance(hist, dict) and "edges" in hist:
            edges = list(hist["edges"])
        else:
            raise AttributeError
    except Exception:
        raise TypeError("histogram object does not provide 'edges'")
    # Extract bin contents
    try:
        if hasattr(hist, "values"):
            values = list(hist.values)
        elif hasattr(hist, "bins"):
            values = list(hist.bins)
        elif isinstance(hist, dict) and "values" in hist:
            values = list(hist["values"])
        elif hasattr(hist, "__iter__"):
            values = list(hist)
        else:
            raise AttributeError
    except Exception:
        raise TypeError("histogram object does not provide bin values")
    if len(edges) - 1 != len(values):
        raise ValueError("Number of edges does not match number of bins")
    # Determine coordinates
    coords = []
    if get_coordinate == "left":
        coords = edges[:-1]
    elif get_coordinate == "right":
        coords = edges[1:]
    elif get_coordinate == "middle":
        coords = [(edges[i] + edges[i + 1]) / 2.0 for i in range(len(edges) - 1)]
    else:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")
    # Default make_value
    if make_value is None:
        def make_value(v):  # pragma: no cover
            return v
    data = []
    for c, val in zip(coords, values):
        out = make_value(val)
        # Normalise output to a tuple for consistency
        if isinstance(out, (list, tuple)):
            out_tuple = tuple(out)
        else:
            out_tuple = (out,)
        point = (c,) + out_tuple
        if len(point) != len(field_names):
            raise ValueError(
                f"Length of field_names ({len(field_names)}) does not match "
                f"the size of the value tuple ({len(point)})"
            )
        data.append(point)
    graph = {"field_names": field_names, "data": data}
    # Handle scale
    if scale is True:
        if hasattr(hist, "scale"):
            graph["scale"] = hist.scale
        else:
            graph["scale"] = None
    elif scale is not None:
        graph["scale"] = scale
    return graph

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid
    errors = []

    # 1. ProvidedBy check (skipped if tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"Candidate {candidate!r} does not provide interface {iface!r}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for {candidate!r} against {iface!r}: {exc}"
            )

    # Helper to get candidates attribute
    def get_candidate_attr(name):
        try:
            return getattr(candidate, name)
        except AttributeError:
            return None

    # 2 & 3. Iterate over interface attributes
    for name in dir(iface):
        if name.startswith("__") and name.endswith("__"):
            continue
        iface_attr = getattr(iface, name, None)
        if iface_attr is None:
            continue

        # Determine if it's a method by inspecting if it is callable and not a data descriptor
        if callable(iface_attr):
            cand_attr = get_candidate_attr(name)
            if cand_attr is None:
                errors.append(f"Missing method {name}")
                continue
            if not callable(cand_attr):
                errors.append(f"Attribute {name} is not callable")
                continue

            # Signature comparison (best effort)
            try:
                iface_sig = inspect.signature(iface_attr)
            except (ValueError, TypeError):
                iface_sig = None
            try:
                cand_sig = inspect.signature(cand_attr)
            except (ValueError, TypeError):
                cand_sig = None

            if iface_sig and cand_sig:
                # Basic check: same number of parameters
                iface_params = iface_sig.parameters
                cand_params = cand_sig.parameters
                if len(iface_params) != len(cand_params):
                    errors.append(
                        f"Signature mismatch for method {name}: "
                        f"expected {len(iface_params)} parameters, got {len(cand_params)}"
                    )
            # If signature cannot be retrieved, skip comparison
        else:
            # Non-callable attribute: check presence
            if get_candidate_attr(name) is None:
                errors.append(f"Missing attribute {name}")

    # 4. Return or raise
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))
    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError("iface must be a class or type")

    # Determine if candidate is a class or an instance
    if isinstance(candidate, type):
        # Check subclass relationship
        if not issubclass(candidate, iface):
            if tentative:
                return False
            raise TypeError(f"Candidate class {candidate.__name__} does not inherit from interface {iface.__name__}")
        candidate_obj = candidate
    else:
        # Check instance relationship
        if not isinstance(candidate, iface):
            if tentative:
                return False
            raise TypeError(f"Candidate instance {candidate!r} does not satisfy interface {iface.__name__}")
        candidate_obj = candidate.__class__

    # If the interface specifies abstract methods, ensure they're implemented
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        implemented = set(dir(candidate_obj))
        missing = abstract_methods - implemented
        if missing:
            if tentative:
                return False
            raise TypeError(
                f"Candidate {candidate_obj.__name__} is missing implementation of abstract methods: "
                f"{', '.join(sorted(missing))}"
            )

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a type, got {type(iface)}")
    try:
        # Determine the class to inspect
        cand_cls = candidate if isinstance(candidate, type) else type(candidate)
        # If candidate is a subclass of iface we are good
        if issubclass(cand_cls, iface):
            return True
        # Otherwise check for required abstract methods/attributes
        abstract_methods = getattr(iface, "__abstractmethods__", set())
        missing = [name for name in abstract_methods if not hasattr(cand_cls, name)]
        if missing:
            raise TypeError(
                f"candidate {cand_cls.__name__} does not implement required "
                f"methods for iface {iface.__name__}: missing {missing}"
            )
        return True
    except Exception as err:
        if tentative:
            return False
        else:
            raise

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    import inspect

    # Helper to collect required names from the interface.
    def _required_names(interface):
        # If the interface is an ABC, use its abstractmethods set.
        if hasattr(interface, "__abstractmethods__"):
            return set(interface.__abstractmethods__)
        # Otherwise, use all callable attributes defined on the interface.
        return {name for name, obj in inspect.getmembers(interface, inspect.isfunction)}

    required = _required_names(iface)

    # Quick check for subclassing if the interface is a class.
    try:
        if isinstance(iface, type) and isinstance(candidate, type) and issubclass(candidate, iface):
            return True
    except TypeError:
        # If either iface or candidate is not a class, ignore.
        pass

    missing = [name for name in required if not hasattr(candidate, name)]

    if missing:
        if tentative:
            return False
        raise TypeError("Candidate %r is missing required attributes for interface %r: %s"
                        % (candidate, iface, ", ".join(missing)))
    return True)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Basic type checks
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a class, got {type(iface).__name__}")
    if candidate is None:
        raise TypeError("candidate must not be None")

    # Resolve the class if an instance is passed
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick check: if candidate is already a subclass of iface
    if issubclass(candidate_cls, iface):
        return True

    # If iface defines abstract methods, check that candidate implements them
    abstract_methods = getattr(iface, "__abstractmethods__", set())
    if abstract_methods:
        missing = [m for m in abstract_methods if not hasattr(candidate_cls, m)]
        if missing:
            msg = (
                f"Candidate class '{candidate_cls.__name__}' does not implement "
                f"abstract methods required by '{iface.__name__}': {missing}"
            )
            if tentative:
                # In tentative mode we do not raise, just return False
                return False
            raise TypeError(msg)

    # Optional: verify presence of attributes listed in iface's __dict__ (methods, properties, etc.)
    # We skip private attributes and callables that are already satisfied by abstract check
    for name in dir(iface):
        if name.startswith("_"):
            continue
        if name in abstract_methods:
            continue
        # Skip if attribute is not defined on iface (e.g., dynamic attributes)
        if not hasattr(iface, name):
            continue
        if not hasattr(candidate_cls, name):
            if tentative:
                return False
            raise TypeError(
                f"Candidate class '{candidate_cls.__name__}' is missing attribute "
                f"'{name}' required by '{iface.__name__}'"
            )

    # All checks passed
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if not bases:
        raise TypeError("At least one base class must be provided")

    # Gather the metaclasses of all base classes
    metaclasses = [type(b) for b in bases]

    # Include the explicit metaclass if provided
    if explicit_mc is not None:
        # explicit_mc may be a tuple or list (for multiple metaclasses)
        if isinstance(explicit_mc, (tuple, list)):
            metaclasses.extend(explicit_mc)
        else:
            metaclasses.append(explicit_mc)

    # Remove duplicates while preserving order
    seen = set()
    unique_metaclasses = []
    for mc in metaclasses:
        if mc not in seen:
            seen.add(mc)
            unique_metaclasses.append(mc)

    # Find the most derived common metaclass
    most_derived = unique_metaclasses[0]
    for next_mc in unique_metaclasses[1:]:
        try:
            if issubclass(next_mc, most_derived):
                most_derived = next_mc
            elif not issubclass(most_derived, next_mc):
                raise TypeError(
                    f"Incompatible metaclasses {most_derived!r} and {next_mc!r}"
                )
            # else keep most_derived
        except TypeError as exc:
            # issubclass may raise if either is not a class
            raise TypeError(f"Invalid metaclass encountered: {exc}") from exc

    return most_derived

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Normalize bases to a list
    try:
        bases = list(bases)
    except TypeError:
        raise TypeError("bases must be an iterable of classes") from None

    # If no bases are provided, the default metaclass is 'type'
    if not bases:
        return type

    # Gather the metaclass of each base
    metaclasses = [type(base) for base in bases]

    # If an explicit metaclass has been supplied, check that it is a metaclass
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit __metaclass__ must be a class (metaclass)")
        metaclasses.append(explicit_mc)

    # Build the MRO lists for each metaclass
    mro_lists = [mc.mro() for mc in metaclasses]

    # Find the first metaclass that is common to all the MROs
    for candidate in mro_lists[0]:
        if all(candidate in mro for mro in mro_lists[1:]):
            return candidate

    # If no common metaclass could be found, use 'type' as a fallback
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise TypeError("At least one base class must be provided")

    # Collect the metaclasses of the bases
    metaclasses = []
    for base in bases:
        try:
            m = type(base)
            if m is not None:
                metaclasses.append(m)
        except Exception:
            continue

    if not metaclasses:
        metaclasses = [type]  # fallback to the default metaclass

    # Insert the explicit metaclass if present
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        metaclasses.insert(0, explicit_mc)

    # Determine the most specialized metaclass (intersection of all)
    candidate = metaclasses[0]
    for m in metaclasses[1:]:
        try:
            if issubclass(candidate, m):
                # candidate is more specialized; keep it
                pass
            elif issubclass(m, candidate):
                candidate = m
            else:
                raise TypeError
        except TypeError:
            raise TypeError(f"Metaclass conflict: {candidate} and {m}")

    return candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is supplied, honor it.
    if explicit_mc is not None:
        return explicit_mc

    # No bases supplied – default to the built‑in metaclass.
    if not bases:
        return type

    # Determine a common metaclass from the supplied bases.
    meta = None
    for base in bases:
        # Ensure the base is a type; otherwise it cannot participate in
        # metaclass resolution and we raise an informative error.
        try:
            cur_meta = type(base)
        except TypeError:
            raise TypeError(f"Base {base!r} is not a class")

        if meta is None:
            meta = cur_meta
        else:
            # Resolve compatibility: meta should be a subclass of cur_meta,
            # or vice versa. If neither is a subclass of the other, we
            # have a conflict.
            if issubclass(meta, cur_meta):
                meta = cur_meta  # cur_meta is more derived
            elif not issubclass(cur_meta, meta):
                raise TypeError(
                    f"metaclass conflict between {meta!r} and {cur_meta!r}"
                )

    return meta

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        return type
    # Collect metaclasses from bases
    metaclasses = []
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"bases must be types: {b!r}")
        metaclasses.append(type(b))
    # If an explicit metaclass is provided, ensure compatibility
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"explicit_metaclass must be a type, got {explicit_mc!r}")
        for m in metaclasses:
            if not issubclass(m, explicit_mc):
                raise TypeError(
                    f"metaclass conflict: {explicit_mc.__name__} is not a "
                    f"superclass of {m.__name__}"
                )
        return explicit_mc
    # Determine most derived common metaclass
    def find_common(metas):
        result = metas[0]
        for m in metas[1:]:
            if issubclass(m, result):
                result = m
            elif not issubclass(result, m):
                # Find closest common base in MROs
                for base in m.__mro__:
                    if base in result.__mro__:
                        result = base
                        break
                else:
                    # No common base found; fall back to type
                    result = type
        return result
    return find_common(metaclasses)

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    # If key is missing, decide what to return / raise
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)

    # Attempt to find and pop the key from the appropriate internal map
    for map_obj in (self._pb.IntMap,
                    self._pb.FloatMap,
                    self._pb.StringMap,
                    self._pb.BoolMap):
        if key in map_obj:
            return map_obj.pop(key)
    # In case the key is present in self but not in any sub-map (unlikely),
    # raise a KeyError to be consistent with dict behaviour
    raise KeyError(key)

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key in self:
        # Use the base dict pop to remove and return the value
        return super().pop(key)
    if default is not __marker:
        return default
    raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # If the dict is empty, raise a KeyError
    try:
        if len(self) == 0:
            raise KeyError('dict is empty')
    except Exception:
        raise KeyError('dict is empty')

    # Determine which attribute holds the frequency mapping
    freq_map = getattr(self, '_freq', None) \
               or getattr(self, '_frequency', None) \
               or getattr(self, 'frequency', None)
    if freq_map is None:
        raise AttributeError('Frequency map attribute not found')

    # Find the minimum frequency
    try:
        min_freq = min(freq_map.values())
    except Exception:
        raise KeyError('dict is empty')

    # Get a key with that minimum frequency
    candidate_key = None
    for key, f in freq_map.items():
        if f == min_freq:
            candidate_key = key
            break

    if candidate_key is None:
        raise KeyError('dict is empty')

    # Remove the key from the underlying storage
    value = self.pop(candidate_key)

    # Remove the key from the frequency map
    freq_map.pop(candidate_key, None)

    return (candidate_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the collection is not empty
    if not self:
        raise KeyError('dict is empty')
    # Find the key with the lowest frequency count
    min_key = None
    min_freq = None
    for key in self:
        freq = getattr(self, '_freq', {}).get(key, 0)
        if min_freq is None or freq < min_freq:
            min_freq = freq
            min_key = key
    if min_key is None:
        # Should not happen but guard against it
        raise KeyError('dict is empty')
    # Remove and return the key-value pair
    value = self.pop(min_key)
    # Update frequency tracking if applicable
    try:
        del getattr(self, '_freq')[min_key]
    except Exception:
        pass
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem() from an empty dict')
    # Attempt to use an internal frequency tracker if present
    freq_map = getattr(self, "_freq", None)
    if isinstance(freq_map, dict):
        # Find the minimum frequency value
        try:
            min_freq = min(freq_map.values())
        except ValueError:
            # Empty frequency map – fall back to normal popitem
            return dict.popitem(self)
        # Pick the first key that has this minimum frequency
        key = next(k for k, v in freq_map.items() if v == min_freq)
        # Retrieve the value, delete the key (to keep cache state consistent),
        # and return the pair.
        value = self[key]
        del self[key]
        return key, value
    # Without a frequency map, fall back to the default dict behaviour
    return dict.popitem(self)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the cache has at least one entry
    if not hasattr(self, '_cache') or not self._cache:
        raise KeyError('Cache is empty')
    # Determine the minimum frequency among all keys
    try:
        min_freq = min(self._freq.values())
    except Exception:
        # Fallback: pop an arbitrary key if frequency tracking is missing
        key = next(iter(self._cache))
        return key, self._cache.pop(key)
    # Retrieve the collection of keys that have this frequency
    freq_keys = self._freq_table.get(min_freq)
    if freq_keys is None:
        # If the table entry is missing, locate a key manually
        candidates = [k for k, f in self._freq.items() if f == min_freq]
        if not candidates:
            raise KeyError('No item to pop')
        key = candidates[0]
        # No need to update freq_keys structure because it was missing
    else:
        # Remove the first key (LRU within this frequency)
        key = next(iter(freq_keys))
        freq_keys.pop(key)
        if not freq_keys:
            # Clean up empty frequency bucket
            del self._freq_table[min_freq]
    # Remove key/value from main storage
    value = self._cache.pop(key)
    # Remove key from frequency mapping
    del self._freq[key]
    # Update minimum frequency pointer if needed
    if self._freq:
        try:
            self._minfreq = min(self._freq.values())
        except Exception:
            # In case min calculation fails, leave _minfreq untouched
            pass
    return (key, value)

