def fromutc(self, dt):
    """Given a timezone-aware datetime in a given timezone, calculates a timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous datetime object, we take this opportunity to determine whether the datetime is ambiguous and in a "fold" state (e.g. if it's the first occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    # Determine the target timezone from the instance
    target_tz = getattr(self, "tzinfo", None)
    if target_tz is None:
        raise AttributeError("Instance must have a 'tzinfo' attribute for conversion")
    # Convert to target timezone
    try:
        converted = dt.astimezone(target_tz)
    except Exception as exc:
        raise ValueError(f"Cannot convert datetime to target timezone: {exc}") from exc
    # Check for ambiguity if tzinfo provides is_ambiguous
    if hasattr(target_tz, "is_ambiguous") and target_tz.is_ambiguous(dt):
        # Resolve fold to the first occurrence
        if hasattr(dt, "fold"):
            return dt.replace(fold=0)
    return converted

def default_tzinfo(dt, tzinfo):
    """Sets the ``tzinfo`` parameter on naive datetimes only

    This is useful for example when you are provided a datetime that may have
    either an implicit or explicit time zone, such as when parsing a time zone
    string.
    """
    if dt is None:
        return dt
    try:
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=tzinfo)
    except AttributeError:
        # dt is not a datetime instance (probably a date), just return it
        pass
    return dt

