    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        data = json.loads(body_str)
        if "encrypted_magic_envelope" in data or "magic_envelope" in data:
            return True
    except Exception:
        pass

    # Public XML payload
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        xml = etree.fromstring(body_str.encode("utf-8"))
        if xml.tag in ("MAGIC_ENV", "Patron", "Legacy"):
            return True
    except Exception:
        pass

    # Legacy plain text indicator
    try:
        body = request.body
        if isinstance(body, bytes):
            body_str = body.decode("utf-8", errors="ignore")
        else:
            body_str = str(body)
        if "legacy-diaspora" in body_str.lower():
            return True
    except Exception:
        pass

    return False

