def find_tags(text: str, replacer: callable = None) -> Tuple[Set[str], str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    if not isinstance(text, str):
        raise TypeError(f"text must be str, got {type(text).__name__}")
    try:
        import re
    except ImportError as exc:
        raise RuntimeError("Regular expressions module required") from exc
    tags: Set[str] = set()
    output_lines = []
    in_code_block = False
    for line in text.splitlines(True):  # preserve line breaks
        stripped = line.lstrip()
        # Toggle fenced code blocks (e.g., ``` or ```python)
        if stripped.startswith("```"):
            in_code_block = not in_code_block
            output_lines.append(line)
            continue
        if in_code_block:
            output_lines.append(line)
            continue
        # Find tags that start with '#'
        tag_pattern = re.compile(r"#(?P<tag>[A-Za-z0-9_-]+)")
        if replacer:
            # Replace each matched tag with the replacer's output
            def _replace(match):
                tag_word = match.group("tag")
                tags.add(tag_word)
                try:
                    return replacer(tag_word)
                except Exception:
                    # Fallback to the original text if replacer fails
                    return match.group(0)
            new_line = tag_pattern.sub(_replace, line)
        else:
            # Collect tags without replacing
            for m in tag_pattern.finditer(line):
                tags.add(m.group("tag"))
            new_line = line
        output_lines.append(new_line)
    return tags, "".join(output_lines)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Find URLs and convert them to anchor tags with target=_blank.
    # We assume the caller has `re` imported or it's available in the module scope.
    _URL_RE = re.compile(r'\b(https?://[^\s]+)')
    def _replace(match):
        url = match.group(1)
        # Return a link with target="_blank" attribute to open in a new tab.
        return f'<a href="{url}" target="_blank">{url}</a>'
    return _URL_RE.sub(_replace, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    _URL_RE = re.compile(r'\b(?P<url>(?:https?://|www\.)[^\s]+)', re.IGNORECASE)
    def _replace(match):
        url = match.group('url')
        href = url
        if href.lower().startswith('www.'):
            href = 'http://' + href
        return f'<a href="{href}" target="_blank" rel="nofollow">{url}</a>'
    try:
        return _URL_RE.sub(_replace, text)
    except Exception:
        return text

