    def _replace(match):
        url = match.group('url')
        href = url if url.startswith(('http://', 'https://')) else 'http://' + url
        attrs = ' target="_blank" rel="noopener noreferrer"'
        return f'<a href="{href}"{attrs}>{url}</a>'
    return _URL_RE.sub(_replace, text)

