        return f'<a target="_blank" rel="noopener" href="{url}">{url}</a>'
    return url_pattern.sub(replace, text)

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        scheme = urllib.parse.urlsplit(url).scheme
        if scheme not in ('http', 'https'):
            return None
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        from urllib.request import Request, urlopen
        from urllib.parse import urlparse

        parsed = urlparse(url)
        if parsed.scheme not in ("http", "https", "ftp", "ftps"):
            # Unsupported scheme; cannot determine content type
            return None

        # Construct a HEAD request; if the library is older and doesn't support
        # the method flag, fall back to an empty GET request with no body
        try:
            req = Request(url, method="HEAD")
        except TypeError:
            req = Request(url)
            req.get_method = lambda: "HEAD"

        with urlopen(req, timeout=10) as resp:
            # For non-200 status codes we do not attempt to read headers
            if getattr(resp, "code", 200) >= 400:
                return None
            return resp.info().get("Content-Type") or resp.info().get("content-type")
    except Exception:
        # Swallow all exceptions and return None to indicate failure
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
        if scheme not in ('http', 'https', 'ftp', 'ftps'):
            return None
        req = urllib.request.Request(url, method='HEAD', headers={'Host': netloc})
        resp = urlopen(req)
    except Exception:
        return None
    try:
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type')
    finally:
        resp.close()

