def verify_relayable_signature(public_key, doc, signature):
    """Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Validate input
    if not public_key or not doc:
        return False

    # Attempt to import required libraries
    try:
        from lxml import etree
    except Exception:
        # lxml is needed for XML parsing
        return False

    try:
        import xmlsec
    except Exception:
        # xmlsec is needed for signature verification
        return False

    # Parse the XML document
    try:
        root = etree.fromstring(doc.encode('utf-8'))
    except Exception:
        return False

    # Namespace for XMLDSig
    ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}

    # Locate the Signature element
    sig_node = root.find('.//ds:Signature', namespaces=ns)
    if sig_node is None:
        return False

    # Load the public key
    key = None
    try:
        # Try treating the key as PEM string
        key = xmlsec.Key.from_memory(public_key.encode('utf-8'), xmlsec.KeyFormat.PEM, None)
    except Exception:
        try:
            # Try treating the key as a file path
            key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
        except Exception:
            return False

    # Create a signature context and assign the key
    ctx = xmlsec.SignatureContext()
    ctx.key = key

    # Verify the signature
    try:
        ctx.verify(sig_node)
        return True
    except xmlsec.VerificationError:
        return False
    except Exception:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Import required libraries locally
        from lxml import etree
        import xmlsec
    except ImportError as exc:
        # The necessary XML security libraries are not available
        return False

    if not public_key:
        return False

    # Parse the document string into an XML element tree
    try:
        if isinstance(doc, str):
            doc_tree = etree.fromstring(doc.encode('utf-8'))
        else:
            doc_tree = doc
    except Exception:
        return False

    # Locate the Signature element. If a separate signature string is given,
    # parse it; otherwise look for an embedded <Signature> element.
    try:
        if signature:
            if isinstance(signature, str):
                sig_el = etree.fromstring(signature.encode('utf-8'))
            else:
                sig_el = signature
        else:
            ns = {'ds': 'http://www.w3.org/2000/09/xmldsig#'}
            sig_el = doc_tree.find('.//ds:Signature', namespaces=ns)
            if sig_el is None:
                return False
    except Exception:
        return False

    # Create a signing context for verification
    try:
        ctx = xmlsec.SignatureContext()
        # Load the public key. Assume PEM format if header present, else raw
        if '-----BEGIN' in public_key:
            key = xmlsec.Key.from_memory(public_key.encode('utf-8'),
                                         xmlsec.KeyFormat.PEM,
                                         None)
        else:
            key = xmlsec.Key.from_memory(public_key.encode('utf-8'),
                                         xmlsec.KeyFormat.RAW,
                                         None)
        ctx.key = key
        # Verify the signature against the XML document
        ctx.verify(sig_el)
        return True
    except Exception:
        return False

