    # Try JSON first
    try:
        data = json.loads(document)
        return data
    except Exception:
        pass  # fall back to XRD

    # Attempt to parse XRD (XML)
    try:
        # ElementTree is assumed to be imported elsewhere
        root = ElementTree.fromstring(document)
    except Exception:
        # If parsing fails, return empty dict
        return {}

    result: Dict[str, Any] = {}

    # Subject element
    subject = root.findtext('Subject')
    if subject:
        result['subject'] = subject

    # Find all Link elements
    links = root.findall('Link')
    for link in links:
        rel = link.attrib.get('rel')
        href = link.attrib.get('href')
        if not rel or not href:
            continue

        rel_lower = rel.lower()
        if rel_lower == 'hcard':
            result['hcard_url'] = href
        elif rel_lower == 'self':
            result['self_url'] = href
        elif rel_lower == 'lrdd':
            result['lrdd_url'] = href
        else:
            # store other rels in a dict of lists
            result.setdefault('links', {}).setdefault(rel, []).append(href)

    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return {}
    links = {}
    # Known mapping from link rel to dictionary key
    rel_to_key = {
        "http://webfinger.net/rel/profile-page": "hcard_url",
        "profile": "hcard_url",
        "http://webfinger.net/rel/activitypub": "activity_pub_url",
        "http://webfinger.net/rel/server-hashtag": "hashtags_url",
        "lrdd": "lrdd",
    }
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        # Expect a list of link objects under "links"
        link_list = data.get("links") or []
        if isinstance(link_list, dict):
            # In some cases links may be a dict keyed by rel
            link_list = [link_list]
        for link in link_list:
            if not isinstance(link, dict):
                continue
            rel = link.get("rel")
            href = link.get("href")
            if not rel or not href:
                continue
            key = rel_to_key.get(rel) or rel
            links[key] = href
        return links
    except Exception:
        pass  # fall back to XML parsing

    # XML / XRD parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        # Handle namespaces by ignoring them
        for elem in root.findall(".//{*}Link"):
            rel = elem.attrib.get("rel") or elem.attrib.get("Rel")
            href = elem.attrib.get("href") or elem.attrib.get("Href")
            if not rel or not href:
                continue
            key = rel_to_key.get(rel) or rel
            links[key] = href
        return links
    except Exception:
        return {}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    if not document or not isinstance(document, str):
        return None

    doc = document.strip()

    # Try JSON parsing first
    try:
        return json.loads(doc)
    except json.JSONDecodeError:
        pass  # Fall back to XRD parsing

    # Attempt to parse as XML XRD
    try:
        root = ET.fromstring(doc)
    except ET.ParseError:
        return None

    def _localname(tag: str) -> str:
        return tag.split("}")[-1] if "}" in tag else tag

    result: Dict = {}
    for child in root:
        tag = _localname(child.tag)
        if tag == "Subject":
            result["subject"] = child.text or ""
        elif tag == "Link":
            link = {}
            for k, v in child.attrib.items():
                link[_localname(k)] = v
            result.setdefault("links", []).append(link)
        else:
            # Generic element: use lowercase tag name
            result[tag.lower()] = child.text or ""

    return result if result else None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    # Try to parse as JSON
    try:
        import json
        data = json.loads(document)
        if not isinstance(data, dict):
            raise ValueError
        result['subject'] = data.get('subject', '')
        result['aliases'] = data.get('aliases', [])
        for link in data.get('links', []):
            rel = link.get('rel')
            href = link.get('href')
            if not href:
                continue
            if rel == 'self':
                result['self_url'] = href
            elif rel in ('hcard', 'diaspora-hcard'):
                result['hcard_url'] = href
        return result
    except Exception:
        # Not a JSON document; fall back to XRD parsing
        pass

    # Attempt XRD parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
    except Exception:
        # Cannot parse document
        return None

    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

    subject_elem = root.find('xrd:Subject', ns)
    if subject_elem is not None and subject_elem.text:
        result['subject'] = subject_elem.text

    aliases = []
    for alias_elem in root.findall('xrd:Alias', ns):
        if alias_elem.text:
            aliases.append(alias_elem.text)
    if aliases:
        result['aliases'] = aliases

    for link in root.findall('xrd:Link', ns):
        rel = link.get('rel')
        href = link.get('href')
        if href is None:
            href = link.get('template')
        if not href:
            continue
        if rel == 'self':
            result['self_url'] = href
        elif rel in ('hcard', 'diaspora-hcard'):
            result['hcard_url'] = href

    return result if result else None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON format first
    try:
        data = json.loads(document)
        subject = data.get("subject")
        links = {}
        for link in data.get("links", []):
            rel = link.get("rel")
            href = link.get("href")
            if rel and href:
                links[rel] = href
        return {"subject": subject, "links": links}
    except Exception:
        # Fallback to XRD (XML) format
        try:
            root = ElementTree.fromstring(document)
        except Exception:
            return {}
        subject_el = root.find(".//Subject")
        subject = subject_el.text.strip() if subject_el is not None else None
        links = {}
        for link in root.findall(".//Link"):
            href = link.attrib.get("href")
            rel = link.attrib.get("rel")
            if rel and href:
                links[rel] = href
        return {"subject": subject, "links": links}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        host = handle.split('@', 1)[1]
    except Exception:
        return None
    import urllib.request, urllib.parse, urllib.error
    url = f"https://{host}/.well-known/webfinger?resource=acct:{urllib.parse.quote(handle)}"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            return resp.read().decode('utf-8')
    except (urllib.error.URLError, urllib.error.HTTPError, Exception):
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        # Validate handle format and extract host
        if not handle or "@" not in handle:
            return None

        # Build the resource string
        resource = handle if handle.lower().startswith("acct:") else f"acct:{handle}"
        host = handle.split("@", 1)[1]

        # Construct the WebFinger URL
        encoded_resource = urllib.parse.quote(resource, safe="")
        url = f"https://{host}/.well-known/webfinger?resource={encoded_resource}"

        # Attempt to fetch the document
        with urllib.request.urlopen(url, timeout=10) as response:
            raw = response.read()
            try:
                return raw.decode("utf-8")
            except UnicodeDecodeError:
                # Fallback decoding
                return raw.decode("utf-8", errors="replace")
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    # Extract host part from the handle, which should be in the form acct:user@host
    try:
        host = handle.split("@")[1]
    except Exception:
        return None

    # Build the WebFinger request URL
    try:
        url = "https://{host}/.well-known/webfinger?resource=acct:{resource}".format(
            host=host, resource=quote(handle)
        )
    except Exception:
        return None

    # Attempt to fetch the document; return None if any error occurs
    try:
        with closing(urllib2.urlopen(url)) as page:
            return page.read()
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if not handle or "@" not in handle:
            return None
        host = handle.split("@", 1)[1]
        encoded_handle = quote(handle, safe="")
        url = f"https://{host}/.well-known/webfinger?resource=acct:{encoded_handle}"
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                return None
            content_bytes = resp.read()
            content_type = resp.info().get("Content-Type", "")
            encoding = "utf-8"
            for part in content_type.split(";"):
                if part.strip().lower().startswith("charset="):
                    encoding = part.strip().split("=", 1)[1]
            return content_bytes.decode(encoding, errors="replace")
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
