def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    # Normalise settings_dirs to a list of directories
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            dirs = []

    found_files = []
    for dir_path in dirs:
        if not os.path.isdir(dir_path):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if not os.path.isfile(full_path):
                    continue
                # If spec_option is None or empty, match everything
                pattern = spec_option or '*'
                if fnmatch.fnmatch(entry, pattern):
                    found_files.append(full_path)
        except OSError:
            # Skip directories that can't be accessed
            continue

    return sorted(found_files)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os

    try:
        # Ensure settings_dirs is iterable
        if isinstance(settings_dirs, (str, bytes)):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)
    except Exception:
        return []

    def _matches(filename):
        """Check if filename matches spec_option (extension or list of extensions)."""
        if spec_option is None:
            return True
        if isinstance(spec_option, (list, tuple, set)):
            return any(filename.lower().endswith(ext.lower()) for ext in spec_option)
        return filename.lower().endswith(spec_option.lower())

    file_list = []
    for directory in dirs:
        try:
            for fname in os.listdir(directory):
                if _matches(fname):
                    full_path = os.path.join(directory, fname)
                    if os.path.isfile(full_path):
                        file_list.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(file_list)

