        return []

def list_of_file_names(settings_dirs, spec_option):
    """Return a list of fully qualified file names from the given directories.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        A directory path or an iterable of directory paths to search.
    spec_option : str
        File specification to filter results. It may be a file extension (e.g.
        ``'ini'``) or a glob pattern like ``'*.ini'``.

    Returns
    -------
    list of str
        Sorted list of fully qualified file paths that match the specification.
    """
    # Normalise input as a list of directories
    if isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    else:
        try:
            dirs = list(settings_dirs)
        except Exception:
            # If casting fails, treat the single value as a directory
            dirs = [settings_dirs]

    matched_files = []
    for directory in dirs:
        try:
            if not os.path.isdir(directory):
                continue
            # Use glob if spec_option contains wildcards, otherwise filter by extension
            if any(char in spec_option for char in ('*', '?', '[')):
                pattern = os.path.join(directory, spec_option)
                for path in glob.glob(pattern):
                    if os.path.isfile(path):
                        matched_files.append(os.path.abspath(path))
            else:
                # Treat spec_option as an extension
                pattern = os.path.join(directory, f"*.{spec_option}")
                for path in glob.glob(pattern):
                    if os.path.isfile(path):
                        matched_files.append(os.path.abspath(path))
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return sorted(set(matched_files))

def list_of_file_names(settings_dirs, spec_option='*'):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    files = []
    try:
        for directory in settings_dirs:
            if not isinstance(directory, (str, bytes)):
                continue
            try:
                for fname in os.listdir(directory):
                    if fnmatch.fnmatch(fname, spec_option):
                        files.append(os.path.join(directory, fname))
            except OSError:
                # Skip directories that can't be accessed
                continue
    except TypeError:
        # settings_dirs might not be iterable
        return []
    return sorted(files)

