def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Create a new dictionary that will contain all resolved groups.
    resolved = {}
    # Keep track of groups that have already been processed to avoid recursion loops.
    visited = set()

    def _resolve_group(name):
        """Recursively resolve a single group name."""
        if name in visited:
            raise ValueError(f'Circular include reference detected for group: {name}')
        visited.add(name)

        if name not in parser_dict:
            raise KeyError(f'Included group "{name}" not found in parser_dict')

        # Make a shallow copy so we don't mutate the original structures.
        group_dict = dict(parser_dict[name])

        # Resolve any nested includes in this group.
        nested_includes = group_dict.pop('include', None)
        if nested_includes:
            if not isinstance(nested_includes, (list, tuple)):
                raise TypeError(f'Include value for group "{name}" must be a list or tuple')
            for sub_name in nested_includes:
                _resolve_group(sub_name)

        # Merge the group's arguments into the resolved dict, preserving existing keys.
        for key, value in group_dict.items():
            if key in resolved and resolved[key] is not None:
                continue  # Existing key takes precedence.
            resolved[key] = value

    # First, handle any top‑level include directive.
    top_level_includes = parser_dict.pop('include', None)
    if top_level_includes:
        if not isinstance(top_level_includes, (list, tuple)):
            raise TypeError('Top‑level include must be a list or tuple')
        for inc_name in top_level_includes:
            _resolve_group(inc_name)

    # Process all remaining groups in the dictionary.
    for group_name in list(parser_dict.keys()):
        # Skip items that are not groups (e.g., simple arguments).
        if not isinstance(parser_dict[group_name], dict):
            continue
        _resolve_group(group_name)

    return resolved

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The ``parser_dict`` parameter is expected to contain an ``include`` key,
    whose value should be a dictionary mapping group names to either:

    * a file path (string) pointing to a JSON or YAML specification file.
    * a dictionary that should be merged directly.

    Each included file is parsed (JSON for ``.json`` files and YAML for
    ``.yaml``/``.yml`` if the optional :mod:`yaml` dependency is available).
    The parsed subsection is then recursively processed to resolve any
    nested ``include`` directives before being inserted into the top‑level
    ``parser_dict`` under its group name.

    The method returns the updated ``parser_dict``.  File‑not‑found errors,
    unsupported file extensions, or incorrect include specifications raise
    informative :class:`ValueError` or :class:`FileNotFoundError` exceptions.
    """
    # Local imports to avoid mandatory dependencies when the method is not used.
    import os
    import json
    try:
        import yaml  # type: ignore
    except ImportError:
        yaml = None

    include = parser_dict.pop('include', None)
    if include is None:
        return parser_dict

    if not isinstance(include, dict):
        raise ValueError("The 'include' directive must be a dictionary")

    for group, value in include.items():
        sub_dict = None
        if isinstance(value, str):
            # Interpret as a file path to a JSON or YAML spec.
            if not os.path.isfile(value):
                raise FileNotFoundError(f"Included file '{value}' does not exist")
            _, ext = os.path.splitext(value)
            with open(value, 'r', encoding='utf-8') as f:
                if ext.lower() in {'.yaml', '.yml'}:
                    if yaml is None:
                        raise ValueError(
                            f"YAML support required for '{value}', but 'yaml' package is not installed"
                        )
                    sub_dict = yaml.safe_load(f)
                elif ext.lower() == '.json':
                    sub_dict = json.load(f)
                else:
                    raise ValueError(
                        f"Unsupported file extension '{ext}' for include '{group}'"
                    )
        elif isinstance(value, dict):
            # Direct dictionary inclusion.
            sub_dict = value
        else:
            raise ValueError(
                f"Invalid include value for group '{group}': expected file path or dict, got {type(value).__name__}"
            )

        if sub_dict is None:
            continue

        # Resolve nested includes recursively.
        sub_dict = self._include_groups(sub_dict)

        # Insert or merge the group into the top-level dictionary.
        if group in parser_dict:
            raise ValueError(
                f"Duplicate group name '{group}' found when including from '{value}'"
            )
        parser_dict[group] = sub_dict

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    for key, value in list(parser_dict.items()):
        if isinstance(value, dict) and 'include' in value:
            include_spec = value.pop('include')
            if isinstance(include_spec, str):
                included = parser_dict.get(include_spec)
                if included is None:
                    raise KeyError(f"Include reference '{include_spec}' not found for key '{key}'")
                if not isinstance(included, dict):
                    raise TypeError(f"Included item '{include_spec}' must be a dict")
                value.update(included)
            elif isinstance(include_spec, dict):
                value.update(include_spec)
            else:
                raise TypeError("The 'include' value must be a string reference or a dict")
            parser_dict[key] = value

def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        # Handle only if 'include' key is present
        if 'include' not in parser_dict:
            return parser_dict

        # Import yaml inside the function to avoid a global import
        try:
            import yaml
        except ImportError as e:
            raise RuntimeError('pyyaml is required to parse include directives') from e

        includes = parser_dict.pop('include')
        if not isinstance(includes, (list, tuple)):
            includes = [includes]

        for inc in includes:
            # The include specification can be either a string (file path)
            # or a dict with a 'file' key.
            if isinstance(inc, str):
                inc_path = inc
            elif isinstance(inc, dict) and 'file' in inc:
                inc_path = inc['file']
            else:
                # Unsupported include format: skip
                continue

            try:
                with open(inc_path, 'r', encoding='utf-8') as f:
                    inc_dict = yaml.safe_load(f)
            except FileNotFoundError:
                raise FileNotFoundError(f'Included spec file not found: {inc_path}')
            except yaml.YAMLError as exc:
                raise ValueError(f'Error parsing included spec file {inc_path}: {exc}')

            if not isinstance(inc_dict, dict):
                # Ignore non-dict includes
                continue

            # Recursively resolve any nested includes in the included dict
            inc_dict = self._include_groups(inc_dict)

            # Merge included dict into the current parser_dict.
            # Keys from the included dict overwrite existing keys.
            parser_dict.update(inc_dict)

        return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    # Recursive helper that walks the nested structure
    def _resolve(subnode, root):
        if isinstance(subnode, dict):
            # Resolve an 'include' directive at this level
            if 'include' in subnode:
                inc_val = subnode.pop('include')
                # Normalise the include value to a list of group names
                if isinstance(inc_val, str):
                    inc_names = [inc_val]
                elif isinstance(inc_val, (list, tuple)):
                    inc_names = list(inc_val)
                else:
                    raise TypeError(
                        f'`include` directive must be a string or list, got {type(inc_val)}'
                    )
                # Merge each included group's definition into this dict
                for name in inc_names:
                    if name not in root:
                        raise KeyError(f'Include group "{name}" not found')
                    include_def = root[name]
                    if not isinstance(include_def, dict):
                        raise TypeError(
                            f'Include group "{name}" is not a dict (got {type(include_def)})'
                        )
                    # Merge, overwriting existing keys if they collide
                    subnode.update(include_def)
            # Recurse into all child nodes
            for child in subnode.values():
                _resolve(child, root)
        elif isinstance(subnode, list):
            for item in subnode:
                _resolve(item, root)

    _resolve(parser_dict, parser_dict)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Iterate over all arguments defined for this instance
    for arg in getattr(self, "args", []):
        # Only consider objects that are valid option specifications
        if not isinstance(arg, _BaseOpt):
            continue

        # Start with the option's intrinsic default (if any)
        val = None
        if not isinstance(arg.default, NoDefault):
            val = arg.default

        # Attempt to override the value with what's present in the spec
        # `spec` may be a dict-like object or an attribute container
        spec_val = None
        try:
            spec_val = getattr(self.spec, arg.name, None)
        except Exception:
            # If attributes are not available, fall back to dict access
            try:
                spec_val = self.spec.get(arg.name)
            except Exception:
                spec_val = None

        if spec_val not in (None, {}):
            val = spec_val

        # For dictionary options, merge nested defaults from the
        # corresponding scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested = arg.scheme.get_spec_defaults()
            if nested:
                if val is None:
                    val = {}
                # Ensure we do not overwrite non-dict defaults
                if isinstance(val, dict):
                    val.update(nested)
                else:
                    val = nested

        if val is not None:
            defaults[arg.name] = val

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}

    # Add values from the class default spec if it exists.
    try:
        default_spec = getattr(self, "_default_spec", None)
        if default_spec is not None:
            # Assume the default spec exposes a mapping interface or a 'get' method.
            if hasattr(default_spec, "get"):
                defaults.update(default_spec.get())
            elif isinstance(default_spec, dict):
                defaults.update(default_spec)
            else:
                # Fallback: try to introspect attributes that look like options.
                for key in dir(default_spec):
                    if key.startswith("_"):
                        continue
                    try:
                        val = getattr(default_spec, key)
                        if val is not None:
                            defaults[key] = val
                    except Exception:
                        continue
    except Exception as exc:
        # If we cannot extract defaults from _default_spec, ignore and continue.
        pass

    # Add values from the spec (current configuration) if it exists.
    try:
        spec = getattr(self, "spec", None)
        if spec is not None:
            if hasattr(spec, "get"):
                defaults.update(spec.get())
            elif isinstance(spec, dict):
                defaults.update(spec)
            else:
                for key in dir(spec):
                    if key.startswith("_"):
                        continue
                    try:
                        val = getattr(spec, key)
                        if val is not None:
                            defaults[key] = val
                    except Exception:
                        continue
    except Exception as exc:
        # If we cannot extract defaults from spec, ignore and continue.
        pass

    # Iterate over declared arguments to ensure we pick up any values that
    # might have been set directly on the instance.
    for arg in getattr(self, "args", []):
        # Skip objects that do not represent options.
        try:
            name = getattr(arg, "name", None)
        except Exception:
            continue
        if not name:
            continue
        # Prefer explicitly set attributes on the instance.
        if hasattr(self, name):
            val = getattr(self, name)
            if val is not None:
                defaults[name] = val
                continue
        # Next, try to resolve from spec again if it hasn't been set yet.
        try:
            if hasattr(self, "spec"):
                val = getattr(self.spec, name, None)
                if val is not None:
                    defaults[name] = val
        except Exception:
            continue

    return defaults

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources.

        The general precedence is:
        1. Values stored in the ``spec`` (if it supports item/attribute access)
        2. Defaults defined in the scheme
        3. Recursively resolved defaults for nested ``DictOption`` instances

        Returns:
            dict: Mapping from argument names to the resolved value.
        """
        defaults = {}
        for arg in self.args:
            if not isinstance(arg, _BaseOpt):
                continue

            # 1. Try spec first – it may be a mapping or an object with attributes
            spec_value = NoDefault
            if hasattr(self, "spec") and self.spec is not None:
                try:
                    if isinstance(self.spec, dict):
                        spec_value = self.spec.get(arg.name, NoDefault)
                    else:
                        spec_value = getattr(self.spec, arg.name, NoDefault)
                except Exception:
                    # If anything goes wrong, ignore and fall back to defaults
                    spec_value = NoDefault

            if spec_value is not NoDefault:
                defaults[arg.name] = spec_value
                continue

            # 2. Fallback to scheme default if set
            if not isinstance(arg.default, NoDefault):
                defaults[arg.name] = arg.default

            # 3. Recurse for nested DictOption if there is a nested scheme
            if isinstance(arg, DictOption) and arg.scheme:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    defaults[arg.name] = nested

        return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Get spec values from the instance; ignore errors
    try:
        spec_vals = getattr(self, "spec", {})
        if not isinstance(spec_vals, dict):
            spec_vals = {}
    except Exception:
        spec_vals = {}

    # Iterate over arguments defined in the scheme
    for opt in getattr(self, "args", []):
        if not hasattr(opt, "name"):
            continue  # Skip items that are not options

        # Prefer value from spec if present
        if opt.name in spec_vals:
            defaults[opt.name] = spec_vals[opt.name]
            continue

        # Fallback to the option's own default if it exists
        default_value = getattr(opt, "default", None)
        if not isinstance(default_value, NoDefault):
            defaults[opt.name] = default_value
            continue

        # If the option is a dict containing a nested scheme, recurse
        if getattr(opt, "scheme", None) is not None:
            try:
                nested = opt.scheme.get_spec_defaults()
                if nested:
                    defaults[opt.name] = nested
            except Exception:
                # Ignore failures from nested schemes
                pass

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Attempt to access the spec object, if it exists
    spec_obj = getattr(self, "spec", None)
    for arg in self.args:
        # Ensure we are dealing with a valid option object
        if not isinstance(arg, _BaseOpt):
            raise ValueError(f"Unexpected argument type: {type(arg)}")
        # Prefer the value from the spec if it is available
        if spec_obj and hasattr(spec_obj, "get"):
            try:
                val = spec_obj.get(arg.name)
                if val is not None:
                    defaults[arg.name] = val
                    continue
            except Exception as exc:
                # If the spec lookup fails, treat it as missing
                # and fall back to the option's own default.
                if not isinstance(exc, (KeyError, AttributeError)):
                    raise
        # Use the option's own default if defined
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default
        # For nested dict options, recursively gather defaults from their scheme
        if isinstance(arg, DictOption) and getattr(arg, "scheme", None):
            nested_defaults = arg.scheme.get_spec_defaults()
            if nested_defaults:
                defaults[arg.name] = nested_defaults
    return defaults

