    deprecation_map = getattr(self, "deprecated_args", {})
    if not isinstance(deprecation_map, dict):
        deprecation_map = {}

    # Process each source of arguments, emitting a warning for deprecated keys.
    for source_label, args in (("CLI", cli_args), ("answer file", answer_file_args)):
        for arg_name in list(args):  # use list to avoid potential mutation issues
            if arg_name in deprecation_map:
                new_name = deprecation_map[arg_name]
                # Emit a deprecation warning; stacklevel=2 to point to caller.
                try:
                    import warnings
                    warnings.warn(
                        f"Argument '{arg_name}' from {source_label} is deprecated; "
                        f"use '{new_name}' instead. The deprecated argument will "
