def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Clean up the command name
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")
        command_name = command_name.strip()

        # Dictionary based lookup
        specs_dict = None
        for attr in ("command_option_specs", "option_specs", "command_specs"):
            specs_dict = getattr(self, attr, None)
            if specs_dict is not None:
                break

        if isinstance(specs_dict, dict):
            # Direct match
            if command_name in specs_dict:
                return list(specs_dict[command_name]) if specs_dict[command_name] else []

            # Case‑insensitive lookup
            if command_name.lower() in specs_dict:
                return list(specs_dict[command_name.lower()]) if specs_dict[command_name.lower()] else []

        # List based lookup (e.g., list of tuples [(command, options), ...])
        specs_list = getattr(self, "command_option_list", None)
        if specs_list is None:
            specs_list = getattr(self, "option_list", None)

        if isinstance(specs_list, list):
            for item in specs_list:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    cmd, opts = item[0], item[1]
                    if isinstance(cmd, str) and cmd.strip().lower() == command_name.lower():
                        return list(opts) if opts else []

        # If no specification found, raise an informative error
        raise ValueError(f"Command options for '{command_name}' could not be found.")

