def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    # Collect names of options whose *required_when* condition is satisfied
    matched = []
    for opt in options_spec:
        name = opt.get('name')
        if not name:
            continue
        conds = opt.get('required_when')
        if not conds:
            continue

        # Normalise to iterable
        if isinstance(conds, (str, bytes)):
            conds = [conds]
        elif not isinstance(conds, (list, tuple)):
            conds = [conds]

        for cond in conds:
            try:
                # If cond is callable, invoke it with the args mapping
                if callable(cond):
                    if cond(args):
                        matched.append(name)
                        break
                else:
                    # Treat cond as a key that should be present in args
                    if cond in args and args.get(cond) not in (None, False):
                        matched.append(name)
                        break
            except Exception:
                # Ignore errors in condition evaluation
                continue
    return matched

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_when_args = []

    if not options_spec:
        return required_when_args

    # Ensure args is a mapping for eval usage; if not, treat as empty dict
    kwargs = args if isinstance(args, dict) else {}

    for opt in options_spec:
        # Each option spec is expected to be a dict-like object
        cond = None
        try:
            cond = opt.get('required_when')
        except Exception:
            # Not a dict-like spec; ignore
            continue

        if not cond:
            continue

        # Evaluate condition: if callable, call it; if string, eval; else interpret as bool
        satisfied = False
        try:
            if callable(cond):
                satisfied = bool(cond(kwargs))
            elif isinstance(cond, str):
                # eval in empty globals, args as locals
                satisfied = bool(eval(cond, {}, kwargs))
            else:
                satisfied = bool(cond)
        except Exception:
            # Fail silently for malformed conditions
            satisfied = False

        if satisfied:
            # Determine the argument name to return
            name = None
            try:
                name = opt.get('name')
                if not name:
                    name = opt.get('arg')
                if not name:
                    name = opt.get('dest')
            except Exception:
                name = None

            if name:
                required_when_args.append(name)

    return required_when_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        required = []

        # Prepare context for evaluating string conditions
        if isinstance(args, dict):
            ctx = args
        elif hasattr(args, '__dict__'):
            ctx = vars(args)
        else:
            ctx = {}

        for opt in options_spec:
            # Retrieve option name
            if isinstance(opt, dict):
                name = opt.get('name') or opt.get('arg')
                condition = opt.get('required_when')
            else:
                name = getattr(opt, 'name', None) or getattr(opt, 'arg', None)
                condition = getattr(opt, 'required_when', None)

            if not name:
                continue

            if condition is None:
                continue

            matched = False
            try:
                if callable(condition):
                    matched = bool(condition(command_name, args))
                elif isinstance(condition, bool):
                    matched = condition
                elif isinstance(condition, str):
                    matched = bool(eval(condition, {}, ctx))
            except Exception:
                # Ignore errors in condition evaluation
                matched = False

            if matched:
                required.append(name)

        return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Helpers
    def _evaluate_condition(arg_dict, key, expected):
        """Return True if key in arg_dict satisfies the expected condition."""
        if callable(expected):
            try:
                return expected(arg_dict)
            except Exception:
                return False
        # None expectation: only check that key is present and not None
        if expected is None:
            return key in arg_dict and arg_dict[key] is not None
        # List/tuple/set expectation: membership test
        if isinstance(expected, (list, tuple, set)):
            return arg_dict.get(key) in expected
        # Default: equality
        return arg_dict.get(key) == expected

    # Normalize args to a dictionary of names to values
    if isinstance(args, dict):
        arg_dict = args
    else:
        # If args is not a dict, we cannot evaluate conditions in a meaningful way
        arg_dict = {}

    required = []
    for opt in options_spec:
        # Get option name
        name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
        if not name:
            continue

        # Get required_when specification
        required_when = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        if not required_when:
            continue

        # Determine if condition matches
        matched = False
        if isinstance(required_when, dict):
            # All key-value conditions must be satisfied
            matched = all(_evaluate_condition(arg_dict, k, v) for k, v in required_when.items())
        elif isinstance(required_when, list):
            # Any of the list entries (which should be dicts) must be satisfied
            for cond in required_when:
                if isinstance(cond, dict) and cond:
                    k, v = next(iter(cond.items()))
                    if _evaluate_condition(arg_dict, k, v):
                        matched = True
                        break
        else:
            # For other types (e.g., boolean) we treat as no condition
            matched = False

        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve argument specifications from parsed YAML.
    arg_specs = self.parsed_yaml.get('args', {})
    # Accept either a dict or a list of (name, value) pairs.
    if isinstance(args, list):
        args = dict(args)
    if not isinstance(args, dict):
        raise TypeError("args must be a dict or a list of (name, value) pairs")
    for arg_name, value in args.items():
        spec = arg_specs.get(arg_name, {})
        max_len = spec.get('length')
        # Skip if no length constraint is defined.
        if max_len is None:
            continue
        # Ensure the value supports len().
        try:
            actual_len = len(value)
        except Exception as exc:
            raise ValueError(f"Argument '{arg_name}' does not support len()") from exc
        if actual_len > max_len:
            raise ValueError(f"Length of argument '{arg_name}' ({actual_len}) exceeds maximum allowed ({max_len})")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError('args must be a dict')
    schema_args = self.parsed_yaml.get('args', {})
    # Determine if schema_args is dict or list
    for arg_name, value in args.items():
        # Skip value that is None
        if value is None:
            continue
        # Find the argument definition in the schema
        arg_def = None
        if isinstance(schema_args, dict):
            arg_def = schema_args.get(arg_name)
        elif isinstance(schema_args, list):
            for adict in schema_args:
                if arg_name in adict:
                    arg_def = adict[arg_name]
                    break
        if not arg_def:
            # No definition for this argument; skip
