def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the object has min_ and max_ attributes
    if not hasattr(self, "min_") or not hasattr(self, "max_"):
        raise AttributeError("Instance must define 'min_' and 'max_' attributes for validation")
    min_val, max_val = getattr(self, "min_"), getattr(self, "max_")

    if min_val is None or max_val is None:
        raise ValueError("'min_' and 'max_' must not be None")
    if min_val > max_val:
        raise ValueError("'min_' must be less than or equal to 'max_'")

    # Normalize input arguments: support dict or iterable of values
    if isinstance(args, dict):
        items = args.items()
    else:
        # Treat as sequence of values; use index as key
        items = enumerate(args)

    for key, val in items:
        if val is None:
            # Skip None values unless explicitly required
            continue
        try:
            # Attempt to cast to a numeric type for comparison
            numeric_val = float(val)
        except (TypeError, ValueError):
            # Non-numeric values are ignored; adjust logic if needed
            continue
        if not (min_val <= numeric_val <= max_val):
            raise ValueError(
                f"Argument '{key}' value {numeric_val} is outside the allowed "
                f"range [{min_val}, {max_val}]"
            )
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    :return: args unchanged if all values are within bounds
    :raise ValueError: If any argument is outside the configured bounds
    :raise TypeError: If args is not an iterable or values cannot be compared
    """
    # Ensure args is iterable
    try:
        iter(args)
    except TypeError as exc:
        raise TypeError("args must be an iterable of values") from exc

    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)

    # If no bounds defined, nothing to check
    if min_val is None and max_val is None:
        return args

    for idx, value in enumerate(args):
        # Skip None values (often used as optional)
        if value is None:
            continue
        try:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) is below the minimum {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) is above the maximum {max_val}"
                )
        except TypeError as exc:
            # The value failed comparison operations
            raise TypeError(
                f"Argument at position {idx} ({value}) is not comparable to min/max bounds"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    def _check(value, min_, max_):
        if min_ is not None and max_ is not None and min_ > max_:
            raise ValueError(f"Minimum ({min_}) cannot be greater than maximum ({max_})")
        if min_ is not None and value < min_:
            raise ValueError(f"Value ({value}) is less than the specified minimum ({min_})")
        if max_ is not None and value > max_:
            raise ValueError(f"Value ({value}) is greater than the specified maximum ({max_})")

    if not hasattr(args, "__iter__") or isinstance(args, (str, bytes)):
        raise TypeError("args must be an iterable of argument specifications")

    # Handle dict of argument name to (value, min, max) or dict of dicts
    if isinstance(args, dict):
        for name, spec in args.items():
            if isinstance(spec, (tuple, list)):
                if len(spec) != 3:
                    raise ValueError(f"Spec for '{name}' must be a 3-tuple (value, min, max)")
                value, min_, max_ = spec
            elif isinstance(spec, dict):
                if not {"value", "min", "max"}.issubset(spec):
                    raise ValueError(f"Spec for '{name}' must contain 'value', 'min', and 'max' keys")
                value, min_, max_ = spec["value"], spec.get("min"), spec.get("max")
            else:
                raise TypeError(f"Spec for '{name}' must be a tuple, list, or dict")
            _check(value, min_, max_)
    else:
        # Assume sequence of (value, min, max) tuples
        for idx, spec in enumerate(args):
            if not isinstance(spec, (tuple, list)):
                raise TypeError(f"Argument #{idx} must be a tuple or list of (value, min, max)")
            if len(spec) != 3:
                raise ValueError(f"Argument #{idx} must have 3 elements: (value, min, max)")
            value, min_, max_ = spec
            _check(value, min_, max_)
    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: Iterable of arguments to validate. Each item can be a dict
        with keys ``value``, ``min`` and ``max`` or a tuple/list where the
        first element is the value, the second element (optional) is the
        minimum, and the third element (optional) is the maximum.
        ``min`` or ``max`` can be ``None`` to indicate no bound.
    :raises TypeError: If ``args`` is not iterable, if an item is not a
        dict/tuple/list, or if comparison cannot be performed.
    :raises ValueError: If the minimum is greater than the maximum, or if
        a value falls outside its declared bounds.
    :return: ``args`` if all values satisfy the bounds.
    """
    # Ensure ``args`` is iterable
    try:
        iterator = iter(args)
    except TypeError as exc:
        raise TypeError("args must be an iterable") from exc

    for idx, item in enumerate(iterator):
        # Extract value, min, and max
        if isinstance(item, dict):
            if "value" not in item:
                raise KeyError(f"Argument at index {idx} missing 'value' key")
            value = item["value"]
            min_val = item.get("min")
            max_val = item.get("max")
        elif isinstance(item, (list, tuple)):
            if len(item) == 0:
                raise ValueError(f"Argument at index {idx} is an empty tuple/list")
            value = item[0]
            min_val = item[1] if len(item) > 1 else None
            max_val = item[2] if len(item) > 2 else None
        else:
            raise TypeError(
                f"Argument at index {idx} must be a dict or tuple/list, "
                f"got {type(item).__name__}"
            )

        # Optional: ensure value is comparable
        if not isinstance(value, (int, float)):
            raise TypeError(
                f"Argument {idx} value {value!r} is not numeric"
            )

        # Validate min/max ordering
        if min_val is not None and max_val is not None and min_val > max_val:
            raise ValueError(
                f"Argument {idx} has min {min_val} greater than max {max_val}"
            )

        # Validate lower bound
        if min_val is not None and value < min_val:
            raise ValueError(
                f"Argument {idx} value {value} below minimum {min_val}"
            )

        # Validate upper bound
        if max_val is not None and value > max_val:
            raise ValueError(
                f"Argument {idx} value {value} above maximum {max_val}"
            )

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic input validation
        if not isinstance(subcommand, str) or not subcommand:
            raise ValueError("subcommand must be a non-empty string")
        if not isinstance(type_name, str) or not type_name:
            raise ValueError("type_name must be a non-empty string")
        if not isinstance(option_name, str) or not option_name:
            raise ValueError("option_name must be a non-empty string")

        # If spec_option is callable we assume it is already the type factory.
        if callable(spec_option):
            type_factory = spec_option
        else:
            # Default parsing parameters
            delimiter = ","
            element_type = str

            # Parse spec_option if it is a mapping or string
            if isinstance(spec_option, dict):
                delimiter = spec_option.get("delimiter", delimiter)
                elem = spec_option.get("element_type", element_type)
                if isinstance(elem, str):
                    if elem.lower() == "int":
                        element_type = int
                    elif elem.lower() == "float":
                        element_type = float
                    elif elem.lower() == "str":
                        element_type = str
                    else:
                        raise ValueError(f"Unsupported element_type: {elem}")
                elif callable(elem):
                    element_type = elem
                else:
                    raise ValueError("element_type must be a str or callable")
            elif isinstance(spec_option, str):
                # Try to interpret the string as an element type
                elem = spec_option.lower()
                if elem == "int":
                    element_type = int
                elif elem == "float":
                    element_type = float
                elif elem == "str":
                    element_type = str
                else:
                    # Treat as custom element type name; attempt to resolve
                    try:
                        element_type = eval(elem, {"__builtins__": {}})
                    except Exception:
                        raise ValueError(f"Unsupported spec_option string: {spec_option}")
            else:
                raise ValueError("spec_option must be a callable, dict, or string")

            # Build a parsing function based on the resolved parameters
            def type_factory(value):
                try:
                    parts = [p.strip() for p in value.split(delimiter)]
                    return [element_type(p) for p in parts]
                except Exception as exc:
                    raise ValueError(f"Failed to parse complex argument for {option_name}: {exc}") from exc

        # Provide a name for debugging or introspection
        type_factory.__name__ = f"{subcommand}_{option_name}_{type_name}"
        return type_factory

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a mapping")

    try:
        # Determine the fully‑qualified type name
        type_fqdn = spec_option.pop('__type__', None)
        if type_fqdn is None:
            # Try a default lookup: subcommand.type_name
            type_fqdn = f"{subcommand}.{type_name}"
        constructor = self.load_name(type_fqdn)

        # Arguments to pass to the constructor
        args = spec_option.pop('__args__', [])
        if not isinstance(args, (list, tuple)):
            raise ValueError("__args__ must be a list or tuple")
        # Remaining keyword arguments from spec_option
        kwargs = spec_option

        return constructor(*args, **kwargs)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to create complex arg type '{type_name}' "
            f"for option '{option_name}' under subcommand '{subcommand}': {exc}"
        ) from exc

