    def parse_value(raw):
        if raw is None and 'default' in spec_option:
            raw = spec_option['default']
        try:
            return base_type(raw)
        except Exception as exc:
            raise ValueError(f"Cannot convert '{raw}' to {type_fqdn} for option '{option_name}'") from exc

    # Optional custom validators
    validators = spec_option.get('validators', [])
    def run_validators(value):
        for v in validators:
            if not v(value):
                raise ValueError(f"Validation failed for option '{option_name}': {value!r}")
        return value

    # Build the complex type class dynamically
    class ComplexType:
        __slots__ = ('value',)

        def __init__(self, raw):
            """
            Initialize a complex type instance from a raw string.
            """
            self.value = run_validators(parse_value(raw))

        def __repr__(self):
            return f"<{type_name}:{self.value!r}>"

        def __eq__(self, other):
            if isinstance(other, ComplexType):
                return self.value == other.value
            return False

        @property
        def raw(self):
            """Return the underlying value."""
            return self.value

    # Attach metadata useful for debugging or downstream processing
    ComplexType.subcommand = subcommand
    ComplexType.type_name = type_name
    ComplexType.option_name = option_name
    ComplexType.spec = spec_option

    return ComplexType

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Guard against non-dict input
    if not isinstance(args, dict):
        return {}, {}

    # Determine the set of keys that should be considered control arguments.
    # If the instance defines a collection of control keys, use it; otherwise
    # fall back to an empty set. Concrete subclasses may provide a suitable
    # attribute (e.g., ``self.control_args``) to customize this behavior.
    try:
        control_keys = getattr(self, 'control_args', None)
        if isinstance(control_keys, (list, tuple, set)):
            control_keys = set(control_keys)
        else:
            # If the attribute is defined but not iterable, ignore it.
            control_keys = set()
    except Exception:
        control_keys = set()

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        return {}, {}

    # Convert unknown input formats to a flat dict
    try:
        if isinstance(args, dict):
            arg_dict = args.copy()
        elif isinstance(args, list):
            arg_dict = {}
            for item in args:
                if isinstance(item, tuple) and len(item) == 2:
                    key, val = item
                elif isinstance(item, str):
                    if "=" in item:
                        key, val = item.split("=", 1)
                    else:
                        key, val = item, True
                else:
                    continue
                arg_dict[key] = val
        else:
            raise TypeError("Unsupported args type: %s" % type(args))
    except Exception as exc:
        raise ValueError("Failed to parse input arguments: %s" % exc) from exc

    control_args = {}
    nested_args = {}

    # Known control argument prefixes or names
    CONTROL_PREFIXES = ("control_", "infra_red_", "infra_", "ir_")
    CONTROL_KEYS = (
        "clean",
        "destroy",
        "list",
        "skip",
        "debug",
        "verbose",
        "dry_run",
        "force",
    )

    for key, value in arg_dict.items():
        key_lc = key.lower()
        if (
            any(key_lc.startswith(prefix) for prefix in CONTROL_PREFIXES)
            or key_lc in CONTROL_KEYS
        ):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments into control and nested arguments.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables that should be merged
        into the nested arguments representation.

    :param args: the collected list or mapping of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Helper to simplify handling of key/value pairs
    def _add_arg(key, value, is_control):
        if is_control:
            control_args[key] = value
        else:
            nested_args[key] = value

    try:
        # Detect a mapping (dict-like) which may include nested structure
        if isinstance(args, dict):
            for key, value in args.items():
                if not isinstance(key, str):
                    raise ValueError("Argument keys must be strings, got %r" % (key,))
                is_control = key.startswith('control_')
                _add_arg(key, value, is_control)

        # Detect a list/tuple of raw option strings (e.g. ['--foo=bar'])
        elif isinstance(args, (list, tuple)):
            for option in args:
                if not isinstance(option, str):
                    raise ValueError("All option strings must be str, got %r" % (option,))
                # Strip leading dashes
                opt = option.lstrip('-')
                if '=' in opt:
                    key, val = opt.split('=', 1)
                else:
                    key, val = opt, True
                is_control = key.startswith('control_')
                _add_arg(key, val, is_control)

        else:
            raise TypeError("Unsupported args type: %r" % (type(args),))

    except Exception as exc:
        raise ValueError("Failed to parse nested and control arguments: %s" % exc)

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dict")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list")
    for ev in extra_vars:
        if not isinstance(ev, dict):
            raise TypeError("each extra var must be a dict")
        vars_dict.update(ev)
    return vars_dict.

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if not extra_vars:
        return vars_dict

    # Handle mapping style input
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Handle iterable of mappings or key=value strings
    try:
        # Treat any iterable (including tuples) as a list of items
        iterable = list(extra_vars)  # will raise TypeError if not iterable
    except TypeError:
        # If it's a single string or other non-iterable, try to parse it
        if isinstance(extra_vars, str):
            if '=' in extra_vars:
                key, val = extra_vars.split('=', 1)
                vars_dict[key] = val
                return vars_dict
            else:
                raise ValueError("extra_vars string must be in 'key=value' format")
        else:
            raise ValueError("extra_vars must be a dict, list, tuple, or 'key=value' string")

    # Iterate over items in the iterable
    for item in iterable:
        if isinstance(item, dict):
            vars_dict.update(item)
        elif isinstance(item, str):
            if '=' in item:
                key, val = item.split('=', 1)
                vars_dict[key] = val
        else:
            # ignore unsupported item types
            continue

    return vars_dict

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (each item should be a dict)

    Returns:
        dict: Updated vars_dict after merging
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Nothing to merge
    if not extra_vars:
        return vars_dict

    # Accept a single dict as well as a list of dicts
    if isinstance(extra_vars, dict):
        extra_vars = [extra_vars]
    elif not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a dict or a list of dicts")

    # Merge each dictionary into vars_dict
    for item in extra_vars:
        if not isinstance(item, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(item)

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra_vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    :returns: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # If no extra variables provided, just return the original dictionary
    if extra_vars is None:
        return vars_dict

    # If a single dictionary is provided, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # Accept list-like containers (list, tuple, set)
    if isinstance(extra_vars, (list, tuple, set)):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            elif isinstance(item, str):
                # Try simple `key=value` parsing
                if '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
            else:
                # Skip unsupported item types
                continue
        return vars_dict

    # If an unsupported type is provided, raise an error
    raise TypeError("extra_vars must be a dict or a list of dicts/strings")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    try:
        cmd = ['ansible-playbook']

        # Verbosity
        if verbose is not None:
            if isinstance(verbose, int):
                if verbose > 0:
                    cmd.append('-' + 'v' * verbose)
            else:
                # Assume the caller passed a proper verbosity flag such as '-vv'
                cmd.append(str(verbose))

        # Extra Ansible arguments
        if ansible_args:
            for key, value in ansible_args.items():
                if isinstance(value, bool):
                    if value:  # only add flag if True
                        cmd.append(str(key))
                else:
                    cmd.extend([str(key), str(value)])

        # Extra vars
        if extra_vars:
            var_parts = []
            for k, v in extra_vars.items():
                if isinstance(v, str):
                    var_parts.append(f'{k}="{v}"')
                else:
                    var_parts.append(f'{k}={v}')
            cmd.extend(['--extra-vars', ' '.join(var_parts)])

        # Playbook file
        cmd.append(str(playbook_path))

        # Optional logger
        logger = getattr(ir_plugin, 'logger', None)
        if logger:
            logger.debug("Running ansible-playbook cmd: %s", ' '.join(cmd))

        # Determine working directory if the workspace exposes one
        cwd = getattr(ir_workspace, 'cwd', None)

        # Execute command
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
        )

        if result.returncode != 0:
            error_msg = result.stderr.strip() or result.stdout.strip()
            raise RuntimeError(f"ansible-playbook failed with error: {error_msg}")

        return result.stdout
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the base command
    cmd = ["ansible-playbook"]

    # Verbosity
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            cmd.append("-" + "v" * verbose)
        else:
            # non‑numeric or zero treated as default single verbosity
            cmd.append("-v")
    else:
        # Default verbosity level
        cmd.append("-v")

    # Ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                # flag style argument (e.g., --check)
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}={value}")

    # Extra vars
    if extra_vars:
        import json
        cmd.append("--extra-vars")
        cmd.append(json.dumps(extra_vars))

    # Append the playbook file
    cmd.append(playbook_path)

    # Execute the command
    import subprocess
    try:
        process = subprocess.Popen(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE
        )
        out, err = process.communicate()
        if process.returncode != 0:
            raise RuntimeError(
                f"ansible-playbook failed with exit code {process.returncode}: "
                f"{err.decode('utf-8')}"
            )
        return out.decode("utf-8")
    except FileNotFoundError as exc:
        raise RuntimeError(f"'ansible-playbook' executable not found: {exc}") from exc
    except Exception as exc:
        raise RuntimeError(f"Error running ansible-playbook: {exc}") from exc

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        return  # nothing to do if values_dict is not a dict

    # Helper to coerce a single value
    def _coerce(val):
        # Already a non-string, keep as is
        if not isinstance(val, str):
            return val
        # Try boolean
        if val.lower() in {"true", "t", "yes", "y", "1"}:
            return True
        if val.lower() in {"false", "f", "no", "n", "0"}:
            return False
        # Try integer
        try:
            if val.lstrip("-").isdigit():
                return int(val)
        except Exception:
            pass
        # Try float
        try:
            return float(val)
        except Exception:
            pass
        # Try comma‑separated list
        if "," in val:
            parts = [p.strip() for p in val.split(",")]
            # Coerce each part recursively
            return [_coerce(p) for p in parts]
        # Default: keep as string
        return val

    # Iterate over a list of keys to avoid dict size change during iteration
    for key in list(values_dict.keys()):
        values_dict[key] = _coerce(values_dict[key])

    # Return the modified dictionary for convenience
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the type mapping for the given parser, if one exists.
    type_map = getattr(self, "_parser_type_map", {})
    if not isinstance(type_map, dict) or parser_name not in type_map:
        return values_dict

    conversions = type_map[parser_name]
    for arg, target_type in conversions.items():
        if arg not in values_dict:
            continue

        raw_value = values_dict[arg]
        # Skip if the value is already of the desired type.
        if isinstance(raw_value, target_type):
            continue

        try:
            # Special logic for booleans: interpret common string representations.
            if target_type is bool:
                if isinstance(raw_value, str):
                    lowered = raw_value.strip().lower()
                    if lowered in ("true", "yes", "1"):
                        casted = True
                    elif lowered in ("false", "no", "0"):
                        casted = False
                    else:
                        casted = bool(raw_value)
                else:
                    casted = bool(raw_value)

            # Lists: split comma-separated strings into items.
            elif target_type is list:
                if isinstance(raw_value, str):
                    casted = [item.strip() for item in raw_value.split(",") if item.strip()]
                else:
                    casted = list(raw_value)

            # Dictionaries: attempt to parse JSON string.
            elif target_type is dict:
                if isinstance(raw_value, str):
                    import json
                    casted = json.loads(raw_value)
                else:
                    casted = dict(raw_value)

            # Path objects: convert string to pathlib.Path.
            elif target_type is type("PathStub", (), {"__module__": "pathlib"}).__new__:
                from pathlib import Path
                casted = Path(raw_value)

            # Other callables: use them directly for conversion.
            else:
                casted = target_type(raw_value)

            values_dict[arg] = casted

        except Exception:
            # If conversion fails, leave the original value unchanged.
            pass

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec.

    The function looks for a ``plugin.json`` or ``plugin.yaml`` file inside the
    supplied ``plugin_dir``.  The content of the file is parsed and flattened
    into a single dictionary, where nested keys are joined with a dot.  Lists
    are flattened using numeric indices.

    :param plugin_dir: A path to the plugin's directory.
    :return: A flatten dictionary that contains the plugin's properties.
    """
    import os
    import json

    # Helper function that recursively flattens a nested structure.
    def _flatten(value, prefix, result):
        if isinstance(value, dict):
            for k, v in value.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(v, new_prefix, result)
        elif isinstance(value, list):
            for idx, item in enumerate(value):
                new_prefix = f"{prefix}.{idx}" if prefix else str(idx)
                _flatten(item, new_prefix, result)
        else:
            result[prefix] = value

    spec_file = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        # No spec file found – return empty dictionary.
        return {}

    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                # Assume YAML; try to import yaml.
                try:
                    import yaml
                except ImportError:
                    # Fallback: treat as plain text key=value lines.
                    data = {}
                    for line in f:
                        if "=" in line:
                            k, v = (part.strip() for part in line.split("=", 1))
                            data[k] = v
                else:
                    data = yaml.safe_load(f)
    except Exception:
        # Any error while reading/parsing – return empty dict.
        return {}

    flat = {}
    _flatten(data, "", flat)
    return flat

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    from pathlib import Path
    import json

    # Attempt to import yaml if available for YAML spec files
    try:
        import yaml
    except ImportError:
        yaml = None

    dir_path = Path(plugin_dir)

    # Look for common plugin spec filenames
    spec_file = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = dir_path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        return {}

    try:
        with spec_file.open("r", encoding="utf-8") as f:
            if spec_file.suffix.lower() == ".json":
                data = json.load(f)
            else:
                if yaml is None:
                    return {}
                data = yaml.safe_load(f)
    except Exception:
        return {}

    flat = {}

    def _flatten(prefix, value):
        if isinstance(value, dict):
            for k, v in value.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(new_prefix, v)
        else:
            flat[prefix] = value

    _flatten("", data)
    return flat

