def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Validate input
    if not isinstance(plugin_dir, str):
        raise TypeError(f"plugin_dir must be a string, got {type(plugin_dir).__name__}")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory not found: {plugin_dir}")

    # Look for spec file
    spec_file = None
    for fname in ("spec.json", "plugin.json", "spec.yaml", "plugin.yaml"):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_file = potential
            break
    if not spec_file:
        raise FileNotFoundError(f"No spec file found in {plugin_dir}")

    # Load spec content
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith((".yaml", ".yml")):
                # Attempt to load YAML if possible
                try:
                    import yaml
                    spec = yaml.safe_load(f)
                except Exception as exc:
                    raise ValueError(f"Failed to parse YAML spec file: {exc}") from exc
            else:
                spec = json.load(f)
    except Exception as e:
        # Return empty dict or re-raise? We choose to raise a descriptive error
        raise ValueError(f"Error reading spec file '{spec_file}': {e}") from e

    # Flatten nested dictionary
    def _flatten(current, parent_key=""):
        flat = {}
        if isinstance(current, dict):
            for k, v in current.items():
                full_key = f"{parent_key}.{k}" if parent_key else k
                flat.update(_flatten(v, full_key))
        elif isinstance(current, list):
            for idx, item in enumerate(current):
                full_key = f"{parent_key}[{idx}]" if parent_key else f"[{idx}]"
                flat.update(_flatten(item, full_key))
        else:
            flat[parent_key] = current
        return flat

    flattened = _flatten(spec)
    return flattened

