    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in directory: {plugin_dir}"
        )

    # Load the spec file
    try:
        with open(spec_path, "r", encoding="utf-8") as fh:
            if spec_path.endswith((".yaml", ".yml")):
                spec_data = yaml.safe_load(fh)
            else:  # .json
                spec_data = json.load(fh)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec at {spec_path}: {exc}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec at {spec_path} must be a dictionary")

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flat.update(_flatten(v, new_key))
            else:
                flat[new_key] = v
        return flat

    return _flatten(spec_data)

