def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    # Validate inputs
    if not isinstance(path, str) or not isinstance(root, str):
        raise ValueError("Both path and root must be strings")

    # Normalize paths to absolute form for comparison
    abs_path = os.path.abspath(path)
    abs_root = os.path.abspath(root)

    # Ensure root is indeed a parent of path
    try:
        common = os.path.commonpath([abs_path, abs_root])
    except ValueError:
        # commonpath cannot handle mixed relative/absolute paths
        raise ValueError(f"Unable to compare paths: '{path}' and '{root}'")

    if common != abs_root:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'")

    # Compute relative path
    try:
        rel_path = os.path.relpath(abs_path, abs_root)
    except Exception as exc:
        raise ValueError(f"Error computing relative path: {exc}")

    # On Windows, relpath may return '.' when the two paths are the same
    if rel_path in ('.', ''):
        rel_path = ''

    return rel_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not path or not root:
        raise ValueError("Both 'path' and 'root' must be provided.")
    norm_path = os.path.normpath(path)
    norm_root = os.path.normpath(root)
    try:
        relative = os.path.relpath(norm_path, norm_root)
    except ValueError as exc:
        raise ValueError(f"Cannot strip root: {exc}") from exc
    # If the relative path resolves to the original path, root was not a prefix
    if os.path.samefile(norm_path, norm_root):
        return ''
    if relative == norm_path:
        raise ValueError(f"Root '{root}' is not a prefix of path '{path}'.")
    return relative

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not root:
        raise ValueError("root path must not be empty")
    try:
        rel = os.path.relpath(path, root)
    except Exception as exc:
        raise ValueError(f"Unable to compute relative path from '{root}' to '{path}': {exc}")
    # If the relative path indicates it's outside the root, or if it's the root itself, raise error
    if rel == '.' or rel.startswith('..') or os.path.isabs(rel):
        raise ValueError(f"Path '{path}' is not inside root '{root}'")
    return rel
